    ["Combo Points"] = "Pontos de Combo",
    ["Show combo points"] = "Mostrar pontos de combo",
    ["Shows your combo points on the target's nameplate (Rogue, or Druid in cat form)."] = "Mostra seus pontos de combo na placa de nome do alvo (Ladino, ou Druida em forma felina).",
    ["Pip size"] = "Tamanho do indicador",
    ["Pip spacing"] = "Espaçamento dos indicadores",
    ["Point colour"] = "Cor do ponto",
    ["Show crowd control (separate row)"] = "Mostrar controle de multidão (linha separada)",
    ["A separate, prominent row for crowd-control effects (Polymorph, Fear, Sap, …) on the unit, from anyone."] = "Uma linha separada e destacada para efeitos de controle de multidão (Polimorfia, Medo, Sedar, …) na unidade, de qualquer pessoa.",
    ["CC icon size"] = "Tamanho do ícone de CC",
    ["Max CC"] = "Máximo de CC",
    ["Highlight your focus"] = "Destacar seu foco",
    ["A second, distinct glow ring on your focus target's nameplate."] = "Um segundo anel de brilho, distinto, na placa de nome do seu foco.",
    ["Focus highlight colour"] = "Cor do destaque do foco",
    ["Glow stealable / dispellable buffs"] = "Brilho em benefícios roubáveis / dissipáveis",
    ["Glows enemy buffs you can remove (Spellsteal / Purge / Dispel Magic). Only for classes that can."] = "Faz brilhar os benefícios inimigos que você pode remover (Roubo de Magia / Purgar / Dissipar Magia). Só para classes que conseguem.",
    ["Dispel glow colour"] = "Cor do brilho de dissipação",
    ["Show absorb shield"] = "Mostrar escudo de absorção",
    ["Overlays damage-absorption shields (e.g. Power Word: Shield) on the health bar."] = "Sobrepõe escudos de absorção de dano (ex.: Palavra de Poder: Escudo) na barra de vida.",
    ["Absorb colour"] = "Cor da absorção",
    ["Absorb opacity"] = "Opacidade da absorção",
    ["Colour by threat"] = "Colorir por ameaça",
    ["Colour the health bar by your threat on the unit — coloured for your role. Useful in dungeons."] = "Colore a barra de vida pela sua ameaça na unidade — colorida conforme sua função. Útil em masmorras.",
    ["Your role"] = "Sua função",
    ["DPS / Healer"] = "DPS / Curandeiro",
    ["Tank"] = "Tanque",
    ["Secure (tank has aggro)"] = "Seguro (o tanque tem aggro)",
    ["Warning (gaining / losing)"] = "Alerta (ganhando / perdendo)",
    ["Danger (pulled / lost)"] = "Perigo (puxou / perdeu)",
    ["Show NPC title"] = "Mostrar título do NPC",
    ["Spam Filter"] = "Filtro de Spam",
    ["Hide (and optionally ignore) chat spammers whose names spell 'casino' & co. with look-alike letters."] = "Oculta (e opcionalmente ignora) spammers do bate-papo cujos nomes escrevem “casino” e afins com letras parecidas.",
    ["|cffaaaaaaHides chat from gold/casino spammers whose names use look-alike letters (e.g. Gãsïnô, Casinòbâbe). The name is folded to plain letters, then matched against the keywords below. Applies to whisper, channels, say, yell and emotes — not guild/party/raid.|r"] = "|cffaaaaaaOculta o bate-papo de spammers de ouro/cassino cujos nomes usam letras parecidas (ex.: Gãsïnô, Casinòbâbe). O nome é convertido para letras simples e comparado com as palavras-chave abaixo. Aplica-se a sussurro, canais, dizer, gritar e emotes — não a guilda/grupo/raide.|r",
    ["Hide their chat messages"] = "Ocultar as mensagens de bate-papo deles",
    ["Also add them to your ignore list"] = "Também adicioná-los à sua lista de ignorados",
    ["Adds matched senders to /ignore too. The ignore list holds only ~50 names and spammers keep changing names, so hiding is usually enough — leave this off unless you want it."] = "Adiciona os remetentes detectados também ao /ignore. A lista de ignorados guarda só ~50 nomes e os spammers trocam de nome o tempo todo, então ocultar costuma bastar — deixe desligado a menos que queira.",
    ["Also match the message text"] = "Também verificar o texto da mensagem",
    ["Also checks the message body for the keywords, not just the sender's name. Catches more spam but can have false positives."] = "Verifica também o corpo da mensagem em busca das palavras-chave, não só o nome do remetente. Pega mais spam, mas pode gerar falsos positivos.",
    ["Keywords"] = "Palavras-chave",
    ["|cffaaaaaaBuilt-in: casino / asino / gasino / kasino. Add your own below, comma-separated (look-alike letters are handled automatically).|r"] = "|cffaaaaaaIntegradas: casino / asino / gasino / kasino. Adicione as suas abaixo, separadas por vírgula (letras parecidas são tratadas automaticamente).|r",
    ["Extra keywords"] = "Palavras-chave extras",
    ["Block messages with web links"] = "Bloquear mensagens com links da web",
    ["Hides any message containing a web link (http://, www., domain.tld) in the filtered channels. Whitelisted names are exempt. Opt-in — can catch the occasional legit link."] = "Oculta qualquer mensagem que contenha um link da web (http://, www., domínio.tld) nos canais filtrados. Nomes na lista de permissões ficam isentos. Opcional — pode pegar algum link legítimo de vez em quando.",
    ["Whitelist"] = "Lista de permissões",
    ["|cffaaaaaaNames here are never filtered. Comma-separated, or use |r|cff9b6cff/vcui spam <name>|r|cffaaaaaa to toggle one.|r"] = "|cffaaaaaaNomes aqui nunca são filtrados. Separados por vírgula, ou use |r|cff9b6cff/vcui spam <nome>|r|cffaaaaaa para alternar um.|r",
    ["Never filter these names"] = "Nunca filtrar estes nomes",
    ["Spam filter: '%s' removed from the whitelist."] = "Filtro de spam: “%s” removido da lista de permissões.",
    ["Spam filter: '%s' added to the whitelist (never filtered)."] = "Filtro de spam: “%s” adicionado à lista de permissões (nunca filtrado).",
    ["|cff9b6cffBlocked this session: %d|r"] = "|cff9b6cffBloqueados nesta sessão: %d|r",
    ["Quest Log"] = "Registro de Missões",
    ["Enhances the quest log: quest levels (and optional quest IDs) in the titles, a larger frame, and a Parchment or Dark theme."] = "Aprimora o registro de missões: níveis das missões (e IDs opcionais) nos títulos, um quadro maior e um tema Pergaminho ou Escuro.",
    ["|cffaaaaaaShows quest levels (and optionally IDs) in the quest log, can enlarge it, and lets you pick a Parchment or Dark look.|r"] = "|cffaaaaaaMostra os níveis das missões (e opcionalmente os IDs) no registro de missões, pode ampliá-lo e permite escolher um visual Pergaminho ou Escuro.|r",
    ["Titles"] = "Títulos",
    ["Show quest levels"] = "Mostrar níveis das missões",
    ["Show quest IDs"] = "Mostrar IDs das missões",
    ["Frame"] = "Quadro",
    ["Larger quest log"] = "Registro de missões maior",
    ["Enlarges the quest log so more quests are visible with the detail pane beside the list. /reload to fully apply or revert."] = "Amplia o registro de missões para que mais missões fiquem visíveis com o painel de detalhes ao lado da lista. /reload para aplicar ou reverter totalmente.",
    ["Theme"] = "Tema",
    ["Parchment (default)"] = "Pergaminho (padrão)",
    ["Dark"] = "Escuro",
    ["Quest log size changed. /reload recommended."] = "Tamanho do registro de missões alterado. /reload recomendado.",
    ["Profession Window"] = "Janela de Profissão",
    ["Enlarges and themes the profession windows (Tradeskill & Craft) to match the quest log: the detail pane sits beside the recipe list, with a Parchment or Dark theme."] = "Amplia e aplica tema às janelas de profissão (Ofício e Criação) para combinar com o registro de missões: o painel de detalhes fica ao lado da lista de receitas, com tema Pergaminho ou Escuro.",
    ["|cffaaaaaaEnlarges the Tradeskill and Craft windows so the detail sits beside the recipe list, with a Parchment or Dark look.|r"] = "|cffaaaaaaAmplia as janelas de Ofício e Criação para que os detalhes fiquem ao lado da lista de receitas, com um visual Pergaminho ou Escuro.|r",
    ["Larger profession window"] = "Janela de profissão maior",
    ["Enlarges the profession windows so more recipes are visible with the detail pane beside the list. /reload to fully apply or revert."] = "Amplia as janelas de profissão para que mais receitas fiquem visíveis com o painel de detalhes ao lado da lista. /reload para aplicar ou reverter totalmente.",
    ["Profession window size changed. /reload recommended."] = "Tamanho da janela de profissão alterado. /reload recomendado.",
    ["Recipes"] = "Receitas",
    ["Show craftable count"] = "Mostrar quantidade criável",
    ["Shows how many of each recipe you can make right now, like [12]."] = "Mostra quantas unidades de cada receita você pode criar agora, como [12].",
    ["Craftable"] = "Criáveis",
    ["Missing"] = "Faltando",
    ["Craftable count incl. bank + missing mats"] = "Quantidade criável incl. banco + materiais faltando",
    ["On the selected recipe, shows how many you can craft counting your bank mats too, and lists what's still missing. Bank mats are remembered from your last visit to the bank."] = "Na receita selecionada, mostra quantas você pode criar contando também os materiais do banco, e lista o que ainda falta. Os materiais do banco são lembrados da sua última visita ao banco.",
    ["|cff888888Click a recipe's star (or right-click the recipe) to favourite it — the star turns gold.|r"] = "|cff888888Clique na estrela de uma receita (ou clique com o botão direito na receita) para favoritá-la — a estrela fica dourada.|r",
    ["Favourites first"] = "Favoritas primeiro",
    ["Recipes you marked with the star float to the top of the list."] = "Receitas marcadas com a estrela sobem para o topo da lista.",
    ["Auction value"] = "Valor de leilão",
    ["Show auction value & profit"] = "Mostrar valor de leilão e lucro",
    ["On the selected recipe, shows the crafted item's auction value, material cost and profit, using Auctionator's price data."] = "Na receita selecionada, mostra o valor de leilão do item criado, o custo dos materiais e o lucro, usando os dados de preço do Auctionator.",
    ["|cff1eff00Auctionator found — prices from its data.|r"] = "|cff1eff00Auctionator encontrado — preços vindos dos dados dele.|r",
    ["|cffff5555Auctionator not found. Install Auctionator to get price data.|r"] = "|cffff5555Auctionator não encontrado. Instale o Auctionator para ter dados de preço.|r",
    ["Recipe info (CraftLib)"] = "Informações da receita (CraftLib)",
    ["|cffaaaaaaThree buttons under the recipe list toggle extra info on the selected recipe: source (where to learn/get it), skill levels (orange/yellow/green/grey) and your skill-up chance.|r"] = "|cffaaaaaaTrês botões abaixo da lista de receitas alternam informações extras sobre a receita selecionada: origem (onde aprender/obter), níveis de perícia (laranja/amarelo/verde/cinza) e sua chance de aumento de perícia.|r",
    ["|cff1eff00CraftLib found — recipe source & levels available.|r"] = "|cff1eff00CraftLib encontrado — origem e níveis das receitas disponíveis.|r",
    ["|cffff5555CraftLib not found. Install CraftLib to show recipe source & levels.|r"] = "|cffff5555CraftLib não encontrado. Instale o CraftLib para mostrar a origem e os níveis das receitas.|r",
    ["Source"] = "Origem",
    ["Levels"] = "Níveis",
    ["Skill-up"] = "Aumento de perícia",
    ["Trainer"] = "Treinador",
    ["Vendor"] = "Vendedor",
    ["Drop"] = "Drop",
    ["Reputation"] = "Reputação",
    ["Quest"] = "Missão",
    ["Starter"] = "Inicial",
    ["Discovery"] = "Descoberta",
    ["World drop"] = "Drop mundial",
    ["orange"] = "laranja",
    ["yellow"] = "amarelo",
    ["green"] = "verde",
    ["gray"] = "cinza",
    ["AH value"] = "Valor no leilão",
    ["Material cost"] = "Custo dos materiais",
    ["Profit"] = "Lucro",
    ["Bind-on-Socket Fix"] = "Correção de Vínculo ao Engastar",
    ["Re-adds the missing BIND_SOCKET confirmation dialog so socketing a gem that binds the item no longer throws a Lua error (Anniversary client)."] = "Readiciona a caixa de diálogo de confirmação BIND_SOCKET que estava faltando, para que engastar uma gema que vincula o item não gere mais um erro de Lua (cliente Anniversary).",
    ["Socketing this gem will bind the item to you. Continue?"] = "Engastar esta gema vinculará o item a você. Continuar?",
    ["The Anniversary client is missing the |cffffffffBIND_SOCKET|r confirmation dialog. Socketing a gem that would bind the item then throws \"Dialog BIND_SOCKET does not exist\" and aborts. This re-adds the dialog so socketing works."] = "O cliente Anniversary não tem a caixa de diálogo de confirmação |cffffffffBIND_SOCKET|r. Engastar uma gema que vincularia o item gera “Dialog BIND_SOCKET does not exist” e cancela a ação. Isto readiciona a caixa de diálogo para que o engaste funcione.",
    ["|cff66ff66Dialog defined|r"] = "|cff66ff66Diálogo definido|r",
    ["not defined yet"] = "ainda não definido",
    ["Nameplate Role Fix"] = "Correção de Função nas Placas de Nome",
    ["Stops the Lua error that fires every time a nameplate appears (Blizzard's nameplate code calls a specialization API this client does not support)."] = "Impede o erro de Lua que ocorre toda vez que uma placa de nome aparece (o código de placas de nome da Blizzard chama uma API de especialização que este cliente não suporta).",
    ["Blizzard's own nameplate code asks for your specialization role - an API the Anniversary client rejects. The resulting Lua error fires on every nameplate spawn and aborts part of the nameplate setup. This fix answers the question safely with 'no role'."] = "O próprio código de placas de nome da Blizzard pede a função da sua especialização — uma API que o cliente Anniversary rejeita. O erro de Lua resultante ocorre a cada surgimento de placa de nome e interrompe parte da configuração das placas. Esta correção responde à pergunta com segurança: “sem função”.",
    ["not needed on this client"] = "não necessário neste cliente",
    ["Combat Indicator"] = "Indicador de Combate",
    ["Restores the missing 'in combat' glow on the Player frame (Anniversary default-UI bug). Pulses a red glow around your portrait while you are in combat."] = "Restaura o brilho de “em combate” que falta no quadro do Jogador (bug da interface padrão do Anniversary). Pulsa um brilho vermelho ao redor do seu retrato enquanto você está em combate.",
    ["|cffaaaaaaThe default Player frame on Anniversary no longer shows when you are in combat. This restores it: a red glow pulses around your portrait while you are in combat.|r"] = "|cffaaaaaaO quadro do Jogador padrão no Anniversary não mostra mais quando você está em combate. Isto restaura o efeito: um brilho vermelho pulsa ao redor do seu retrato enquanto você está em combate.|r",
    ["Disenchant Queue"] = "Fila de Desencantamento",
    ["For enchanters: a window with one button that disenchants your bag items one click each, auto-advancing through the queue (no casting + picking each item by hand)."] = "Para encantadores: uma janela com um botão que desencanta os itens da sua mochila com um clique cada, avançando automaticamente pela fila (sem precisar conjurar e escolher cada item na mão).",
    ["%d item(s) to disenchant"] = "%d item(ns) para desencantar",
    ["|cff888888Nothing to disenchant.|r"] = "|cff888888Nada para desencantar.|r",
    ["You need the Enchanting profession (Disenchant) to use this."] = "Você precisa da profissão Encantamento (Desencantar) para usar isto.",
    ["This module is disabled."] = "Este módulo está desativado.",
    ["Disenchant"] = "Desencantar",
    ["Skip"] = "Pular",
    ["Disenchanting…"] = "Desencantando…",
    ["|cffaaaaaaA window with one button that disenchants your bag items one click each and auto-advances through the queue. WoW does not allow fully unattended disenchanting, so this is one click per item — but you never have to cast and pick each item by hand again.|r"] = "|cffaaaaaaUma janela com um botão que desencanta os itens da sua mochila com um clique cada e avança automaticamente pela fila. O WoW não permite desencantar de forma totalmente automática, então é um clique por item — mas você nunca mais precisa conjurar e escolher cada item na mão.|r",
    ["|cff1eff00You know Disenchant.|r"] = "|cff1eff00Você conhece Desencantar.|r",
    ["|cffff5555You are not an enchanter — this tool will do nothing.|r"] = "|cffff5555Você não é encantador — esta ferramenta não fará nada.|r",
    ["Open disenchant queue"] = "Abrir fila de desencantamento",
    ["|cff888888Also: /disenchant or /entzaubern|r"] = "|cff888888Também: /disenchant ou /entzaubern|r",
