    ["Type |cff9b6cff/vcui help|r for the full command list."] = "Digite |cff9b6cff/vcui help|r para ver a lista completa de comandos.",
    ["Spam filter not available."] = "Filtro de spam não disponível.",
    ["Usage: /vcui spam <name> — toggle a name on/off the spam-filter whitelist."] = "Uso: /vcui spam <nome> — adiciona/remove um nome da lista de permissões do filtro de spam.",
    ["Swing Timer"] = "Temporizador de Golpe",
    ["MH"] = "MP",
    ["OH"] = "MS",
    ["Weapon swing timer for your melee auto-attacks (any melee class). Shows a main-hand bar and, while dual-wielding, an off-hand bar."] = "Temporizador de golpe das armas para seus auto-ataques corpo a corpo (qualquer classe corpo a corpo). Mostra uma barra de mão principal e, com empunhadura dupla, uma barra de mão secundária.",
    ["|cffaaaaaaShows when your next melee auto-attack lands (any melee class). The off-hand bar only appears while dual-wielding. The bar fills up toward the swing; the number is the time left.|r"] = "|cffaaaaaaMostra quando seu próximo auto-ataque corpo a corpo acontece (qualquer classe corpo a corpo). A barra de mão secundária só aparece com empunhadura dupla. A barra enche até o golpe; o número é o tempo restante.|r",
    ["Enable swing timer"] = "Ativar temporizador de golpe",
