    ["Foreground transparency"] = "Transparência do primeiro plano",
    ["Background texture"] = "Textura do fundo",
    ["Background transparency"] = "Transparência do fundo",
    ["|cffffffffSWING TIMER|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffTEMPORIZADOR DE GOLPE|r\\n|cffaaaaaaArraste ou use as setas|r",
    ["|cffffffffLOADOUTS SIDEBAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffBARRA LATERAL DE CONJUNTOS|r\\n|cffaaaaaaArraste ou use as setas|r",
    ["Swing Timer position: x=%.0f, y=%.0f"] = "Posição do Temporizador de Golpe: x=%.0f, y=%.0f",
    ["Swing Timer mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Posicionador do Temporizador de Golpe ativo. |cff9b6cffArraste a caixa roxa|r ou use as |cff9b6cffsetas|r (SHIFT = 5px). Clique em “Destravar / Testar” de novo para concluir.",
    ["Swing Timer mover disabled."] = "Posicionador do Temporizador de Golpe desativado.",
    ["Show off-hand bar (while dual-wielding)"] = "Mostrar barra de mão secundária (com empunhadura dupla)",
    ["Show time remaining"] = "Mostrar tempo restante",
    ["Only show while attacking"] = "Mostrar só ao atacar",
    ["Hides the bars unless you're auto-attacking. Turn off to always show them."] = "Oculta as barras a menos que você esteja em auto-ataque. Desligue para mostrá-las sempre.",
