    ["Save and quickly equip gear sets for different specs, content, or roles."] = "Salve e equipe rapidamente conjuntos de equipamento para diferentes especializações, conteúdos ou funções.",
    ["Save your current equipment as named gear sets and quickly switch between them. Equipping requires you to be out of combat — items in your bags are auto-equipped via Use."] = "Salve seu equipamento atual como conjuntos nomeados e alterne rapidamente entre eles. Equipar exige estar fora de combate — itens nas suas mochilas são equipados automaticamente via Usar.",
    ["Save current equipment as a new loadout. Enter name:"] = "Salvar o equipamento atual como um novo conjunto. Digite o nome:",
