    ["Equipment swap API not available on this client."] = "API de troca de equipamento não disponível neste cliente.",
    ["No loadouts saved yet."] = "Nenhum conjunto salvo ainda.",
    ["|cffaaaaaaNo loadouts saved yet. Use the button above to save your current gear.|r"] = "|cffaaaaaaNenhum conjunto salvo ainda. Use o botão acima para salvar seu equipamento atual.|r",
    ["Saved loadouts:"] = "Conjuntos salvos:",
    ["Usage: /loadout equip <name> | save <name> | delete <name> | list"] = "Uso: /loadout equip <nome> | save <nome> | delete <nome> | list",
    ["Usage: /loadout delete <name>"] = "Uso: /loadout delete <nome>",
    ["|cffaaaaaaSlash commands: /loadout save <name>, /loadout equip <name>, /loadout delete <name>, /loadout list. Short alias: /lo|r"] = "|cffaaaaaaComandos: /loadout save <nome>, /loadout equip <nome>, /loadout delete <nome>, /loadout list. Atalho curto: /lo|r",
    ["No account-wide loadouts to import."] = "Nenhum conjunto de toda a conta para importar.",
    ["Imported %d account-wide loadout(s) onto this character."] = "%d conjunto(s) de toda a conta importado(s) para este personagem.",
    ["You have account-wide loadouts from an older version. Type /lo import to copy them onto this character."] = "Você tem conjuntos de toda a conta de uma versão antiga. Digite /lo import para copiá-los para este personagem.",
    ["Import from older version"] = "Importar de versão antiga",
    ["|cffaaaaaaYou have gear sets saved account-wide by an older version. Loadouts are now per-character — import copies them onto THIS character.|r"] = "|cffaaaaaaVocê tem conjuntos de equipamento salvos para toda a conta por uma versão antiga. Os conjuntos agora são por personagem — importar os copia para ESTE personagem.|r",
    ["Import account-wide loadouts"] = "Importar conjuntos de toda a conta",
