    ["Macro Factory"] = "Fábrica de Macros",
    ["|cffaaaaaaOne click builds a ready-made macro (per character). Then open |cffffffff/macro|r and drag it onto your action bar. Works on any client — uses item slots / IDs, no English needed.|r"] = "|cffaaaaaaUm clique cria uma macro pronta (por personagem). Depois abra |cffffffff/macro|r e arraste-a para sua barra de ação. Funciona em qualquer cliente — usa espaços/IDs de itens, sem precisar de inglês.|r",
    ["Macro Factory: can't create macros in combat."] = "Fábrica de Macros: não é possível criar macros em combate.",
    ["Macro Factory: nothing to build (e.g. no healing potion in your bags)."] = "Fábrica de Macros: nada para criar (ex.: nenhuma poção de cura nas suas mochilas).",
