    ["Minimap Button"] = "Botão do Minimapa",
    ["Left-click for a quick set-switcher menu, right-click to open settings, drag to reposition."] = "Clique esquerdo para um menu rápido de troca de conjuntos, clique direito para abrir as configurações, arraste para reposicionar.",
    ["Left-click: switch set"] = "Clique esquerdo: trocar de conjunto",
    ["Right-click: settings"] = "Clique direito: configurações",
    ["Drag: reposition"] = "Arrastar: reposicionar",
    ["Auto-Switch on Stance/Form"] = "Troca Automática por Postura/Forma",
    ["Enable auto-switching"] = "Ativar troca automática",
    ["Automatically equips a loadout when your stance/form changes (warrior stances, druid forms). Out-of-combat only — if a stance change happens in combat, the swap is deferred until combat ends."] = "Equipa automaticamente um conjunto quando sua postura/forma muda (posturas de guerreiro, formas de druida). Só fora de combate — se a mudança de postura ocorrer em combate, a troca é adiada até o fim do combate.",
    ["Auto-equip on form"] = "Equipar automaticamente na forma",
    ["Equip this loadout automatically when the chosen stance/form is activated."] = "Equipa este conjunto automaticamente quando a postura/forma escolhida é ativada.",
    ["Auto-Switch on Dual Spec"] = "Troca Automática por Especialização Dupla",
    ["Enable spec auto-switching"] = "Ativar troca automática por especialização",
    ["Automatically equips a loadout when you switch between Spec 1 and Spec 2 (dual spec). Bind each loadout to a spec below. Requires dual spec to be active."] = "Equipa automaticamente um conjunto quando você alterna entre a Especialização 1 e a Especialização 2 (especialização dupla). Vincule cada conjunto a uma especialização abaixo. Requer especialização dupla ativa.",
    ["Auto-equip on spec"] = "Equipar automaticamente na especialização",
    ["Equip this loadout automatically when you switch to this spec."] = "Equipa este conjunto automaticamente quando você troca para esta especialização.",
    ["None"] = "Nenhum",
