    ["Form %d"] = "Forma %d",
    ["Character Frame Sidebar"] = "Barra Lateral do Quadro do Personagem",
    ["Show sidebar on character frame"] = "Mostrar barra lateral no quadro do personagem",
    ["Attach a quick-access sidebar to the right of the character window. Click a set to select, double-click or button to equip, right-click for context menu."] = "Anexa uma barra lateral de acesso rápido à direita da janela do personagem. Clique em um conjunto para selecionar, clique duplo ou botão para equipar, clique direito para o menu de contexto.",
    ["|cffaaaaaaTip: with the character window open, enable edit mode (Unlock) to drag the sidebar; right-click the purple box to reset its position.|r"] = "|cffaaaaaaDica: com a janela do personagem aberta, ative o modo de edição (Destravar) para arrastar a barra lateral; clique com o botão direito na caixa roxa para redefinir a posição dela.|r",
    ["New Set"] = "Novo Conjunto",
