    ["Right-click: remove this slot from the set."] = "Clique direito: remover este espaço do conjunto.",
    ["Left-click to pick an item from your bags"] = "Clique esquerdo para escolher um item das suas mochilas",
    ["(equipped)"] = "(equipado)",
    ["Slot Picker"] = "Seletor de Espaços",
    ["Enable slot picker"] = "Ativar seletor de espaços",
    ["|cffaaaaaaRight-click an equipment slot in the character window to see all compatible items from your bags and click one to equip it.|r"] = "|cffaaaaaaClique com o botão direito em um espaço de equipamento na janela do personagem para ver todos os itens compatíveis das suas mochilas e clique em um para equipá-lo.|r",
    ["Hover an equipment slot in the Character frame for a compact flyout of compatible bag items, or modifier-click for a larger pinnable picker. Click an item to equip it (out-of-combat)."] = "Passe o mouse sobre um espaço de equipamento no quadro do Personagem para um painel suspenso compacto com itens compatíveis das mochilas, ou use clique com modificador para um seletor maior e fixável. Clique em um item para equipá-lo (fora de combate).",
    ["Flyout on hover"] = "Painel suspenso ao passar o mouse",
    ["Hovering an equipment slot pops out a compact strip of items you can swap in — the paperdoll flyout look. Turn off to use only the modifier-click picker."] = "Passar o mouse sobre um espaço de equipamento abre uma tira compacta de itens que você pode trocar — o mesmo visual do painel suspenso da janela do personagem. Desligue para usar só o seletor por clique com modificador.",
    ["Activation modifier"] = "Modificador de ativação",
    ["Choose which key combination opens the item picker when you click an equipment slot."] = "Escolha qual combinação de teclas abre o seletor de itens ao clicar em um espaço de equipamento.",
