    ["Crisp portrait hit numbers"] = "Números de dano nítidos no retrato",
    ["Renders the damage/heal numbers that flash on the Player/Pet portrait with a fixed, sharp font instead of Blizzard's blurry growing animation."] = "Exibe os números de dano/cura que piscam no retrato do Jogador/Ajudante com uma fonte fixa e nítida, em vez da animação borrada e crescente da Blizzard.",
    ["Hit number size"] = "Tamanho dos números de dano",
    ["Font size of the portrait hit numbers (when 'Crisp' is on)."] = "Tamanho da fonte dos números no retrato (quando “Nítido” está ativo).",
    ["Auto-select single gossip option"] = "Selecionar automaticamente a única opção de diálogo",
    ["Skips NPC dialog windows that only have a single option. Hold SHIFT to temporarily bypass."] = "Pula janelas de diálogo de NPC que têm apenas uma opção. Segure SHIFT para ignorar temporariamente.",
    ["Faster auto-loot"] = "Saque automático mais rápido",
