    ["Group type"] = "Tipo de grupo",
    ["Buffs & Procs (only show while active)"] = "Benefícios e Procs (mostrar só enquanto ativos)",
    ["|cffaaaaaaIcons appear only while their buff/proc is on you; the bar is empty otherwise. Add the BUFF (e.g. Clearcasting) by name or ID.|r"] = "|cffaaaaaaOs ícones aparecem só enquanto o benefício/proc está em você; caso contrário, a barra fica vazia. Adicione o BENEFÍCIO (p. ex. Conjuração Límpida) por nome ou ID.|r",
    ["|cffaaaaaaIcons show the cooldown of each spell/trinket.|r"] = "|cffaaaaaaOs ícones mostram o tempo de recarga de cada magia/berloque.|r",
    ["Size & offsets"] = "Tamanho e deslocamentos",
    ["Extra settings"] = "Configurações extras",
    ["Friends List"] = "Lista de Amigos",
    ["Dialog Popups"] = "Janelas de Diálogo",
    ["Restyles Blizzard's confirmation dialogs (logout countdown, delete item, resurrect, group invite) to match the dark look."] = "Reestiliza os diálogos de confirmação da Blizzard (contagem de saída, excluir item, ressurreição, convite de grupo) para combinar com o visual escuro.",
    ["|cffaaaaaaRestyles Blizzard's confirmation dialogs — logout countdown, delete item, resurrect, group invite — to match the dark look.|r"] = "|cffaaaaaaReestiliza os diálogos de confirmação da Blizzard — contagem de saída, excluir item, ressurreição, convite de grupo — para combinar com o visual escuro.|r",
    ["Accent strip"] = "Faixa de destaque",
    ["Draws a thin accent gradient along the top edge of each dialog."] = "Desenha um gradiente fino de destaque na borda superior de cada diálogo.",
    ["Addon Skins"] = "Visual de Addons",
    ["Restyles supported third-party addon windows to match the dark look: error list, quest tracker, loot browser, profiler and more."] = "Reestiliza as janelas de addons de terceiros compatíveis para combinar com o visual escuro: lista de erros, rastreador de missões, navegador de saque, medidor de desempenho e mais.",
    ["|cffaaaaaaRestyles the windows of supported addons to the dark look. Skins apply when the addon is loaded; turning one off needs a /reload (the quest tracker restores live).|r"] = "|cffaaaaaaReestiliza as janelas dos addons compatíveis com o visual escuro. Os visuais são aplicados quando o addon é carregado; desativar um exige um /reload (o rastreador de missões é restaurado na hora).|r",
    ["not loaded"] = "não carregado",
    ["Dark window skin"] = "Visual escuro da janela",
    ["Restyles the whole friends window dark with purple accents. Turning it off needs a /reload to restore Blizzard's frame."] = "Reestiliza toda a janela de amigos em escuro com detalhes roxos. Desativar exige um /reload para restaurar o quadro da Blizzard.",
    ["Class color names"] = "Nomes com cor da classe",
    ["Colors each online friend's name by their class."] = "Colore o nome de cada amigo online conforme a classe dele.",
    ["Show class icons"] = "Mostrar ícones de classe",
    ["Shows a class icon next to online WoW friends (in-game and Battle.net)."] = "Mostra um ícone de classe ao lado dos amigos online do WoW (no jogo e no Battle.net).",
    ["Class icon style"] = "Estilo do ícone de classe",
    ["Blizzard crests"] = "Brasões da Blizzard",
    ["Circles"] = "Círculos",
    ["Squares"] = "Quadrados",
    ["Show status dot"] = "Mostrar ponto de status",
    ["A coloured dot after the name: green online, yellow away, red busy, grey offline."] = "Um ponto colorido após o nome: verde online, amarelo ausente, vermelho ocupado, cinza offline.",
    ["Show friend notes"] = "Mostrar anotações do amigo",
    ["Shows your saved note for the friend in grey under their name."] = "Mostra a anotação salva do amigo em cinza sob o nome dele.",
    ["Faction"] = "Facção",
    ["Faction accent on realm line"] = "Destaque de facção na linha do reino",
    ["Tints the realm/zone line red (Horde) or blue (Alliance)."] = "Tinge a linha de reino/zona de vermelho (Horda) ou azul (Aliança).",
    ["Faction row tint"] = "Tom de facção na linha",
    ["Adds a subtle red/blue background tint to each online friend's row."] = "Adiciona um leve tom vermelho/azul ao fundo da linha de cada amigo online.",
    ["Invites"] = "Convites",
    ["Auto-accept Battle.net friend invites"] = "Aceitar automaticamente convites de amizade do Battle.net",
    ["Automatically accepts incoming Battle.net friend requests."] = "Aceita automaticamente os pedidos de amizade recebidos no Battle.net.",
    ["Auto-accept group invites from friends"] = "Aceitar automaticamente convites de grupo de amigos",
    ["Automatically joins a group when the invite comes from someone on your friends list."] = "Entra automaticamente em um grupo quando o convite vem de alguém da sua lista de amigos.",
    ["Class-coloured names, class icons, status dots, inline notes, faction tint and optional auto-accept."] = "Nomes coloridos por classe, ícones de classe, pontos de status, anotações na linha, tom de facção e aceite automático opcional.",
