    ["Countdown text color..."] = "Cor do texto da contagem...",
    ["Warn color under (sec)"] = "Cor de alerta abaixo de (s)",
    ["Below this many seconds the countdown switches to the warn color; 0 turns the warn color off."] = "Abaixo desse número de segundos, a contagem muda para a cor de alerta; 0 desativa a cor de alerta.",
    ["Warn color..."] = "Cor de alerta...",
    ["Glow while ready"] = "Brilho quando pronta",
    ["A steady glow while the cooldown is ready - and, for spells, only while it is actually usable (enough mana etc.)."] = "Um brilho constante enquanto a recarga está pronta — e, para magias, apenas enquanto ela for realmente utilizável (mana suficiente etc.).",
    ["Glow color"] = "Cor do brilho",
    ["Show keybinds"] = "Mostrar atalhos",
    ["Shows the key the spell/item is bound to on your action bars. Macros are not matched; stance pages follow the main bar."] = "Mostra a tecla à qual a magia/item está associado nas suas barras de ação. Macros não são reconhecidas; páginas de postura seguem a barra principal.",
    ["Keybind color..."] = "Cor do atalho...",
    ["Keep inactive buffs visible (greyed out)"] = "Manter benefícios inativos visíveis (acinzentados)",
    ["Icons stay in place when the buff runs out, just desaturated - the bar never jumps around."] = "Os ícones permanecem no lugar quando o benefício acaba, apenas dessaturados — a barra nunca fica pulando.",
    ["Add (name / ID)"] = "Adicionar (nome / ID)",
    ["Tracked"] = "Rastreados",
    ["  |cff888888(item)|r"] = "  |cff888888(item)|r",
