    ["Left"] = "Esquerda",
    ["Down"] = "Baixo",
    ["Only show while on cooldown"] = "Mostrar somente em recarga",
    ["Hides ready icons; they reappear when on cooldown."] = "Oculta os ícones prontos; eles reaparecem quando entram em recarga.",
    ["Show countdown text"] = "Mostrar texto da contagem",
    ["Show stacks"] = "Mostrar acúmulos",
    ["  |cffaa5555(other class)|r"] = "  |cffaa5555(outra classe)|r",
    ["Edit mode — move the cooldown bars"] = "Modo de edição — mover as barras de recarga",
    ["Stop editing — lock the cooldown bars"] = "Parar de editar — travar as barras de recarga",
    ["Unlocks just the cooldown bars so you can drag them. Arrow keys fine-tune; right-click a purple box for X/Y. (To move ALL VuloUI windows, use 'Unlock Mode' in Global.)"] = "Destrava apenas as barras de recarga para você arrastá-las. As setas fazem o ajuste fino; clique com o botão direito em uma caixa roxa para X/Y. (Para mover TODAS as janelas do VuloUI, use “Modo Destravar” em Global.)",
    ["Hide cooldowns under (sec)"] = "Ocultar recargas abaixo de (s)",
    ["Cooldowns at or below this are ignored. 1.5 hides the global cooldown; raise it to also hide short cooldowns; 0 shows everything."] = "Recargas iguais ou menores que isso são ignoradas. 1,5 oculta a recarga global; aumente para ocultar também recargas curtas; 0 mostra tudo.",
    ["Move earlier"] = "Mover para antes",
    ["Move later"] = "Mover para depois",
    ["Stack / reagent position"] = "Posição de acúmulo / reagente",
    ["Stack / reagent size"] = "Tamanho de acúmulo / reagente",
    ["Stack / reagent color..."] = "Cor de acúmulo / reagente...",
    ["Bottom right"] = "Inferior direito",
    ["Bottom left"] = "Inferior esquerdo",
    ["Top right"] = "Superior direito",
    ["Top left"] = "Superior esquerdo",
    ["Show reagent counts"] = "Mostrar contagem de reagentes",
    ["Shows each spell's OWN reagent count — Soul Shards on Soul Fire, Infernal Stone on Inferno, etc. Spells without a reagent show nothing. Needs 'Show stacks' on."] = "Mostra a contagem do PRÓPRIO reagente de cada magia — Fragmentos de Alma em Fogo das Almas, Pedra Infernal em Inferno, etc. Magias sem reagente não mostram nada. Requer “Mostrar acúmulos” ativado.",
    ["Anchor"] = "Ancoragem",
    ["Anchor to"] = "Ancorar a",
    ["Pin this bar to a unit frame, the minimap, or another group's bar — it then moves with it. Drag the bar to detach."] = "Fixe esta barra a um quadro de unidade, ao minimapa ou à barra de outro grupo — ela passa a se mover junto. Arraste a barra para soltá-la.",
    ["Player Frame"] = "Quadro do Jogador",
    ["Focus Frame"] = "Quadro do Foco",
    ["Pet Frame"] = "Quadro do Ajudante",
    ["None (free)"] = "Nenhum (livre)",
    ["Cooldown Manager: can't anchor there — it would loop."] = "Gerenciador de Recargas: não é possível ancorar aí — criaria um laço.",
    ["Side"] = "Lado",
    ["Below"] = "Abaixo",
    ["Above"] = "Acima",
    ["Left of"] = "À esquerda de",
