    ["Icon crop (%)"] = "Corte do ícone (%)",
    ["How much is cut off each edge of the icon. 0 shows the whole icon including the border baked into its artwork."] = "Quanto é cortado de cada borda do ícone. 0 mostra o ícone inteiro, incluindo a borda presente na sua imagem.",
    ["Cooldown swipe darkness"] = "Escurecimento da varredura de recarga",
    ["Only in combat"] = "Somente em combate",
    ["Only with a target"] = "Somente com um alvo",
    ["Only with an attackable target"] = "Somente com um alvo atacável",
    ["Hide while mounted"] = "Ocultar quando montado",
    ["Only in instances"] = "Somente em instâncias",
    ["Dim icon while on cooldown"] = "Escurecer o ícone durante a recarga",
    ["Flash when ready"] = "Piscar quando pronta",
    ["Saves named snapshots of your action bars, macros and keybindings, and restores them with one click."] = "Salva instantâneos nomeados das suas barras de ação, macros e atalhos de teclado, e os restaura com um clique.",
    ["|cffaaaaaaSaves your complete bar setup (all action slots, macros, keybindings) as a named profile and restores it with one click — e.g. PvP and Raid layouts, or to copy a setup to a twink (account-wide storage).|r"] = "|cffaaaaaaSalva toda a sua configuração de barras (todos os espaços de ação, macros, atalhos de teclado) como um perfil nomeado e a restaura com um clique — p. ex. layouts de PvP e de raide, ou para copiar uma configuração para um twink (armazenamento em toda a conta).|r",
    ["Load"] = "Carregar",
    ["Save current setup"] = "Salvar configuração atual",
    ["Please enter a profile name first."] = "Digite primeiro um nome de perfil.",
    ["|cff888888No profiles saved yet.|r"] = "|cff888888Nenhum perfil salvo ainda.|r",
    ["Also restore macros"] = "Restaurar também as macros",
    ["Rewrites saved macros by name (existing ones are updated, missing ones created)."] = "Reescreve as macros salvas pelo nome (as existentes são atualizadas, as ausentes são criadas).",
    ["Also restore keybindings"] = "Restaurar também os atalhos de teclado",
    ["Load profile"] = "Carregar perfil",
    ["Overwrite with current setup"] = "Sobrescrever com a configuração atual",
    ["Replaces the selected profile with your current bars/macros/bindings."] = "Substitui o perfil selecionado pelas suas barras/macros/atalhos atuais.",
    ["Note: profile '%s' was saved on another class (%s)."] = "Aviso: o perfil “%s” foi salvo em outra classe (%s).",
    ["Flight Timer"] = "Cronômetro de Voo",
    ["|cffff8800Flight route database not loaded.|r Fully restart WoW (a /reload is not enough after an update) so the flight times work."] = "|cffff8800Banco de dados de rotas de voo não carregado.|r Reinicie o WoW por completo (um /reload não basta após uma atualização) para que os tempos de voo funcionem.",
    ["Show flight time bar"] = "Mostrar barra de tempo de voo",
    ["Shows destination and remaining time while on a taxi. The first flight of a route is learned, then you get a draining countdown."] = "Mostra o destino e o tempo restante durante o voo. O primeiro voo de uma rota é aprendido; depois você recebe uma contagem regressiva.",
    ["Flight: %s (%s)"] = "Voo: %s (%s)",
    ["Print flight time to chat"] = "Exibir o tempo de voo no bate-papo",
    ["After landing, prints the measured flight time."] = "Após o pouso, exibe o tempo de voo medido.",
    ["Reset learned times"] = "Redefinir tempos aprendidos",
    ["Deletes all saved route durations."] = "Exclui todas as durações de rota salvas.",
    ["Learned flight times reset."] = "Tempos de voo aprendidos redefinidos.",
    ["|cffffffffFLIGHT TIME|r"] = "|cffffffffTEMPO DE VOO|r",
    ["Flight timer: x=%.0f, y=%.0f"] = "Cronômetro de voo: x=%.0f, y=%.0f",
    ["Flight timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Movimentação do cronômetro de voo ativa. |cff9b6cffArraste|r ou use as |cff9b6cffsetas do teclado|r (SHIFT = 5px).",
    ["Flight timer mover disabled."] = "Movimentação do cronômetro de voo desativada.",
    ["Flight debug on — take a flight, the resolution appears in the chat."] = "Depuração de voo ativada — faça um voo e a resolução aparecerá no chat.",
    ["Flight debug off."] = "Depuração de voo desativada.",
    ["LazyVulo"] = "LazyVulo",
    ["Training"] = "Training",
    ["Group Board"] = "Painel de Grupo",
    ["Apexis Relic memory minigame helper (Ogri'la dailies): record the flashing color sequence, always see what to click next."] = "Auxiliar do minijogo de memória da Relíquia de Apexis (diárias de Ogri'la): registre a sequência de cores piscantes e sempre veja no que clicar em seguida.",
    ["Green relic"] = "Relíquia verde",
    ["Yellow relic"] = "Relíquia amarela",
    ["Blue relic"] = "Relíquia azul",
    ["Red relic"] = "Relíquia vermelha",
    ["Left click: remove this entry.\nRight click: remove this and all later entries."] = "Clique esquerdo: remover esta entrada.\\nClique direito: remover esta e todas as entradas seguintes.",
    ["Click to record this color."] = "Clique para registrar esta cor.",
    ["Hotkey: %s"] = "Tecla de atalho: %s",
    ["LazyVulo is disabled."] = "O LazyVulo está desativado.",
    ["|cffaaaaaaHelper for the Apexis Relic memory minigame (Ogri'la dailies). Record the flashing sequence with the buttons or hotkeys; the first icon is always your next click. Correct clicks are consumed automatically, wrong clicks are restored.|r"] = "|cffaaaaaaAuxiliar para o minijogo de memória da Relíquia de Apexis (diárias de Ogri'la). Registre a sequência piscante com os botões ou teclas de atalho; o primeiro ícone é sempre o seu próximo clique. Cliques corretos são consumidos automaticamente e cliques errados são restaurados.|r",
    ["|cffaaaaaaOpen manually with /lazyvulo or /lv.|r"] = "|cffaaaaaaAbra manualmente com /lazyvulo ou /lv.|r",
    ["Auto-show at the Apexis Relic"] = "Mostrar automaticamente na Relíquia de Apexis",
    ["Opens the window automatically when you start the relic minigame."] = "Abre a janela automaticamente quando você inicia o minijogo da relíquia.",
    ["Enable hotkeys while the window is shown"] = "Ativar teclas de atalho enquanto a janela estiver visível",
    ["Disable hotkeys while in combat"] = "Desativar teclas de atalho em combate",
    ["Hands the keys back to your action bars while you are in combat."] = "Devolve as teclas às suas barras de ação enquanto você estiver em combate.",
    ["Show help tooltips"] = "Mostrar dicas de ajuda",
    ["Window scale"] = "Escala da janela",
    ["Hotkeys"] = "Teclas de atalho",
    ["|cffaaaaaaOne key per color (e.g. G, Y, B, R or NUMPAD1). Empty = no hotkey.|r"] = "|cffaaaaaaUma tecla por cor (p. ex. G, Y, B, R ou NUMPAD1). Vazio = sem tecla de atalho.|r",
