    ["Auto-declines party/raid invites from players who are not in your guild or on your friends list."] = "Recusa automaticamente convites de grupo/raide de jogadores que não estão na sua guilda nem na sua lista de amigos.",
    ["Block trades from strangers"] = "Bloquear trocas de estranhos",
    ["Auto-closes trade windows opened by players who are not in your guild or on your friends list. Trades you start yourself are not affected."] = "Fecha automaticamente as janelas de troca abertas por jogadores que não estão na sua guilda nem na sua lista de amigos. Trocas iniciadas por você não são afetadas.",
    ["|cffffd200[QoL]|r Blocked group invite from %s (not guild/friend)."] = "|cffffd200[QoL]|r Convite de grupo de %s bloqueado (não é da guilda/amigo).",
    ["|cffffd200[QoL]|r Blocked trade from %s (not guild/friend)."] = "|cffffd200[QoL]|r Troca de %s bloqueada (não é da guilda/amigo).",
    ["Adds a tab to your spell book that lists the abilities you can still learn from your class trainer, grouped by level. Open the book icon below the spell schools."] = "Adiciona uma aba ao seu livro de magias que lista as habilidades que você ainda pode aprender com o treinador de classe, agrupadas por nível. Abra o ícone de livro abaixo das escolas de magia.",
    ["|cffaaaaaaAdds a tab to your spell book (the book icon on the side, below the spell schools) listing every ability you can still learn from your class trainer — grouped by status and coloured by level. No need to visit a trainer.|r"] = "|cffaaaaaaAdiciona uma aba ao seu livro de magias (o ícone de livro na lateral, abaixo das escolas de magia) listando todas as habilidades que você ainda pode aprender com o treinador de classe — agrupadas por estado e coloridas por nível. Sem precisar visitar o treinador.|r",
    ["Available now"] = "Disponíveis agora",
    ["Available but Missing Requirements"] = "Disponíveis, mas faltam requisitos",
    ["Upcoming"] = "Em breve",
    ["Not Yet Available"] = "Ainda não disponíveis",
    ["Missing Required Talents"] = "Faltam talentos necessários",
    ["Already Known"] = "Já aprendidas",
    ["Level %d"] = "Nível %d",
    ["Cost: %s"] = "Custo: %s",
    ["What can I train?"] = "O que posso treinar?",
    ["No results found"] = "Nenhum resultado encontrado",
    ["|cffffffffPOWER BAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffBARRA DE PODER|r\\n|cffaaaaaaArraste ou use as setas|r",
    ["Power Bar mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Move' again to finish."] = "Modo de mover da Barra de Poder ativo. |cff9b6cffArraste a caixa roxa|r ou use as |cff9b6cffsetas do teclado|r (SHIFT = 5px). Clique em 'Destravar / Mover' novamente para concluir.",
    ["Power Bar mover disabled."] = "Modo de mover da Barra de Poder desativado.",
    ["|cffaaaaaaResource bar that follows your class automatically (Mana / Rage / Energy). Druids switch with their form: Bear = Rage, Cat = Energy, otherwise Mana.|r"] = "|cffaaaaaaBarra de recurso que acompanha sua classe automaticamente (Mana / Fúria / Energia). Druidas mudam conforme a forma: Urso = Fúria, Felino = Energia, caso contrário Mana.|r",
    ["v%s loaded. /vcui to open."] = "v%s carregada. /vcui para abrir.",
    ["UI not loaded. Likely a Lua error during init. Enable /console scriptErrors 1 and /reload."] = "Interface não carregada. Provavelmente um erro de Lua na inicialização. Ative /console scriptErrors 1 e /reload.",
    ["Not possible in combat."] = "Não é possível em combate.",
    ["DB reset. UI reloading."] = "BD redefinido. Recarregando a interface.",
    ["Debug = %s"] = "Depuração = %s",
    ["Registered modules:"] = "Módulos registrados:",
    ["ON"] = "LIGADO",
    ["off"] = "desligado",
    ["Gold Tracker not active."] = "Rastreador de ouro não está ativo.",
    ["|cffff5555Error while executing:|r %s"] = "|cffff5555Erro ao executar:|r %s",
    ["|cffff5555Event handler error (%s):|r %s"] = "|cffff5555Erro no manipulador de evento (%s):|r %s",
    ["WARN: Module '%s' already registered."] = "AVISO: módulo '%s' já registrado.",
    ["|cffff5555Error enabling module '%s':|r %s"] = "|cffff5555Erro ao ativar o módulo '%s':|r %s",
    ["|cffff5555Error disabling '%s':|r %s"] = "|cffff5555Erro ao desativar '%s':|r %s",
    ["Module '%s' disabled. /reload recommended for full effect."] = "Módulo '%s' desativado. /reload recomendado para efeito completo.",
    ["|cffff5555LibSharedMedia-3.0 not found, Media Registry will be skipped.|r"] = "|cffff5555LibSharedMedia-3.0 não encontrada, o Registro de Mídia será ignorado.|r",
    ["Profiles"] = "Perfis",
    ["Manage profiles with different settings. A default profile can be assigned per class and is loaded automatically on login."] = "Gerencie perfis com configurações diferentes. Um perfil padrão pode ser atribuído por classe e é carregado automaticamente ao entrar.",
    ["Active Profile"] = "Perfil Ativo",
    ["You are currently using: |cff9b6cff%s|r  (Class: %s)"] = "Você está usando atualmente: |cff9b6cff%s|r  (Classe: %s)",
    ["Switch Profile"] = "Trocar de Perfil",
    ["Profile for this character"] = "Perfil para este personagem",
    ["|cffaaaaaaPins a profile to THIS character only. At login it beats the class assignment and the account-wide selection - so every character can keep its own minimap, bars and window settings.|r"] = "|cffaaaaaaFixa um perfil APENAS neste personagem. Ao entrar, ele tem prioridade sobre a atribuição por classe e sobre a seleção da conta - assim cada personagem mantém seu próprio minimapa, barras e configurações de janela.|r",
    ["This character"] = "Este personagem",
    ["Create New Profile"] = "Criar Novo Perfil",
    ["Name"] = "Nome",
    ["Copy Settings From"] = "Copiar Configurações De",
    ["- empty profile (defaults) -"] = "- perfil vazio (padrões) -",
    ["- none -"] = "- nenhum -",
    ["Create Profile"] = "Criar Perfil",
    ["|cffff5555Please enter a name.|r"] = "|cffff5555Por favor, insira um nome.|r",
    ["|cffff5555Please enter a new name.|r"] = "|cffff5555Por favor, insira um novo nome.|r",
    ["Error."] = "Erro.",
    ["Share Profile"] = "Compartilhar Perfil",
    ["|cffaaaaaaExport the current profile as a text string - as a backup or to share it. Importing always creates a NEW profile and never overwrites anything.|r"] = "|cffaaaaaaExporte o perfil atual como um texto - para backup ou para compartilhar. A importação sempre cria um NOVO perfil e nunca sobrescreve nada.|r",
    ["Export as string"] = "Exportar como texto",
    ["Import from string"] = "Importar de texto",
    ["This is not a VuloClassicUI profile string."] = "Este não é um texto de perfil do VuloClassicUI.",
    ["The profile string is damaged."] = "O texto do perfil está danificado.",
    ["Profile '%s' imported. Activate it via 'Switch Profile'."] = "Perfil '%s' importado. Ative-o em 'Trocar de Perfil'.",
    ["Manage Profiles"] = "Gerenciar Perfis",
    ["Delete..."] = "Excluir...",
    ["Reset to defaults..."] = "Restaurar padrões...",
    ["Delete profile '%s'? This cannot be undone."] = "Excluir o perfil '%s'? Isso não pode ser desfeito.",
    ["Reset profile '%s' to the default settings? This cannot be undone."] = "Restaurar o perfil '%s' para as configurações padrão? Isso não pode ser desfeito.",
    ["Profile changed. Reload the UI now so every module picks it up?"] = "Perfil alterado. Recarregar a interface agora para que todos os módulos o adotem?",
    ["|cffff5555Profile '%s' could not be loaded:|r %s"] = "|cffff5555Não foi possível carregar o perfil '%s':|r %s",
    ["Rename to"] = "Renomear para",
    ["Rename"] = "Renomear",
    ["|cffff5555Default profile cannot be deleted.|r"] = "|cffff5555O perfil padrão não pode ser excluído.|r",
    ["Apply to Active Class"] = "Aplicar à Classe Ativa",
    ["Sets the current profile as the default for %s."] = "Define o perfil atual como padrão para %s.",
    ["'%s' is now the default profile for %s."] = "'%s' agora é o perfil padrão de %s.",
    ["Per-class profile (quick setup)"] = "Perfil por classe (configuração rápida)",
    ["|cffaaaaaaOne click: makes a profile named after your class (copied from the current one) and loads it for this class automatically. Run it once on each character — every class then keeps its own cooldown bars, frames and settings.|r"] = "|cffaaaaaaUm clique: cria um perfil com o nome da sua classe (copiado do atual) e o carrega automaticamente para essa classe. Execute uma vez em cada personagem — cada classe passa a manter suas próprias barras de recarga, quadros e configurações.|r",
    ["Set up a %s profile"] = "Configurar um perfil de %s",
    ["'%s' is now the %s profile. |cffffff00/reload|r to apply."] = "'%s' agora é o perfil de %s. |cffffff00/reload|r para aplicar.",
    ["Profile Assignment per Class"] = "Atribuição de Perfil por Classe",
    ["Choose a default profile for each class. When logging in with a character of that class, the profile will be loaded automatically."] = "Escolha um perfil padrão para cada classe. Ao entrar com um personagem dessa classe, o perfil será carregado automaticamente.",
    ["Settings migrated to profile system (all settings are in profile '%s')."] = "Configurações migradas para o sistema de perfis (todas as configurações estão no perfil '%s').",
    ["|cffff5555Profile '%s' does not exist.|r"] = "|cffff5555O perfil '%s' não existe.|r",
    ["Profile '%s' created%s."] = "Perfil '%s' criado%s.",
    [" (copy of '%s')"] = " (cópia de '%s')",
    ["Name cannot be empty."] = "O nome não pode ficar vazio.",
    ["Profile already exists."] = "O perfil já existe.",
    ["Default profile cannot be deleted."] = "O perfil padrão não pode ser excluído.",
    ["Profile does not exist."] = "O perfil não existe.",
