    ["Profile '%s' deleted."] = "Perfil '%s' excluído.",
    ["Default profile cannot be renamed."] = "O perfil padrão não pode ser renomeado.",
    ["New name already exists."] = "O novo nome já existe.",
    ["Profile '%s' renamed to '%s'."] = "Perfil '%s' renomeado para '%s'.",
    ["Profile '%s' loaded. |cffffff00/reload|r recommended so all modules use the new settings."] = "Perfil '%s' carregado. |cffffff00/reload|r recomendado para que todos os módulos usem as novas configurações.",
