    ["Max Camera Distance"] = "Distância Máxima da Câmera",
    ["Maximum camera distance (CVar cameraDistanceMaxZoomFactor)."] = "Distância máxima da câmera (CVar cameraDistanceMaxZoomFactor).",
    ["Show Minimap Button"] = "Mostrar Botão do Minimapa",
    ["Toggle the VuloClassicUI button on the minimap."] = "Ativa ou desativa o botão do VuloClassicUI no minimapa.",
    ["Show CPU Usage in Header"] = "Mostrar Uso de CPU no Cabeçalho",
    ["Shows total CPU usage of all active addons (plus VuloClassicUI's own share) at the top of the config header.\n\n|cffaaaaaaRequires /reload after toggling.\n\nNote: Enables WoW's scriptProfile CVar, which costs ~3-5% performance — that's the price for WoW collecting this data at all.|r"] = "Mostra o uso total de CPU de todos os addons ativos (mais a parte do próprio VuloClassicUI) no topo do cabeçalho da configuração.\\n\\n|cffaaaaaaRequer /reload após alternar.\\n\\nObservação: ativa a CVar scriptProfile do WoW, que reduz o desempenho em ~3-5% — esse é o preço para o WoW coletar esses dados.|r",
    ["Script profiling changed. /reload required for the CPU display to update."] = "Perfilamento de scripts alterado. /reload necessário para atualizar a exibição de CPU.",
    ["Reload now"] = "Recarregar agora",
    ["Later"] = "Mais tarde",
    ["Shows a button on the minimap to quickly open VuloClassicUI. Shift+drag moves the button."] = "Mostra um botão no minimapa para abrir rapidamente o VuloClassicUI. Shift+arrastar move o botão.",
    ["UI is not loaded yet."] = "A interface ainda não foi carregada.",
    ["|cffffffffLeft click:|r Open options"] = "|cffffffffClique esquerdo:|r Abrir opções",
    ["|cffffffffRight click:|r Quick module selection"] = "|cffffffffClique direito:|r Seleção rápida de módulos",
    ["|cffffffffShift+drag:|r Move button"] = "|cffffffffShift+arrastar:|r Mover botão",
    ["Open Options"] = "Abrir Opções",
    ["Show button on minimap"] = "Mostrar botão no minimapa",
    ["If off, the button is completely hidden."] = "Se desativado, o botão fica completamente oculto.",
    ["Distance from center"] = "Distância do centro",
    ["Angle (degrees)"] = "Ângulo (graus)",
    ["Tip: You can also move the button directly on the minimap — hold Shift and drag it to the desired position."] = "Dica: você também pode mover o botão diretamente no minimapa — segure Shift e arraste-o até a posição desejada.",
    ["Font Bars"] = "Fontes das Barras",
    ["Smaller font sizes for Player/Target/Pet Health & Mana bars, optionally hide TargetFrameBackground."] = "Tamanhos de fonte menores nas barras de vida e mana de jogador/alvo/mascote, com opção de ocultar TargetFrameBackground.",
    ["Health Bar Text"] = "Texto da Barra de Vida",
    ["Font size on health bars (Player/Target/Pet)."] = "Tamanho da fonte nas barras de vida (jogador/alvo/mascote).",
    ["Power Bar Text"] = "Texto da Barra de Poder",
    ["Font size on mana/power bars."] = "Tamanho da fonte nas barras de mana/poder.",
    ["Pet Combat Feedback Text"] = "Texto de Combate do Mascote",
    ["Font size for 'Damage', 'Dodge', 'Miss' on the pet."] = "Tamanho da fonte de 'Dano', 'Esquiva', 'Errou' no mascote.",
    ["Only affect Player/Target/Pet bars"] = "Afetar apenas as barras de jogador/alvo/mascote",
    ["If off: all TextStatusBars in the UI are overridden with the sizes above (may interfere with other addons)."] = "Se desativado: todas as TextStatusBars da interface são sobrescritas com os tamanhos acima (pode interferir em outros addons).",
    ["Hide TargetFrame background"] = "Ocultar fundo do TargetFrame",
    ["Permanently hides the dark background element of the TargetFrame."] = "Oculta permanentemente o elemento escuro de fundo do TargetFrame.",
    ["Target Frame"] = "Quadro do Alvo",
    ["|cffaaaaaaAdds the modern Target/Focus frame extras the default Anniversary UI is missing - all cosmetic, no taint.|r"] = "|cffaaaaaaAdiciona os recursos modernos de alvo/foco que faltam na interface padrão do Anniversary - tudo cosmético, sem corromper o código protegido.|r",
    ["Numeric threat %"] = "Ameaça numérica em %",
    ["Shows your threat percentage on the target (and focus) above the frame, coloured by threat status."] = "Mostra sua porcentagem de ameaça no alvo (e no foco) acima do quadro, colorida conforme o status de ameaça.",
    ["Threat glow"] = "Brilho de ameaça",
    ["Glows the target (and focus) frame in yellow/orange/red as your threat rises."] = "Faz o quadro do alvo (e do foco) brilhar em amarelo/laranja/vermelho conforme sua ameaça aumenta.",
    ["Rare-Elite border"] = "Borda de Raro-Elite",
    ["Shows the winged silver-dragon Rare-Elite border on rare-elite mobs."] = "Mostra a borda alada de dragão prateado de Raro-Elite em criaturas raras-elite.",
    ["Class icon on player targets"] = "Ícone de classe em alvos jogadores",
    ["Shows the target's class crest on the frame when you target a player."] = "Mostra o brasão de classe do alvo no quadro quando você seleciona um jogador.",
    ["Also apply to the Focus frame"] = "Aplicar também ao quadro de Foco",
    ["Health"] = "Vida",
    ["Show real NPC health"] = "Mostrar vida real de NPCs",
    ["Shows the true health value on NPCs instead of the obfuscated percentage (enemy players stay %)."] = "Mostra o valor real de vida em NPCs em vez da porcentagem ofuscada (jogadores inimigos continuam em %).",
    ["Player Castbar"] = "Barra de Conjuração do Jogador",
    ["Player castbar with two modes: Original (Blizzard bar extended) or Custom castbar (VUI style)."] = "Barra de conjuração do jogador com dois modos: Original (barra da Blizzard estendida) ou Personalizada (estilo VUI).",
    ["|cffffffffCASTBAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffBARRA DE CONJURAÇÃO|r\\n|cffaaaaaaArraste ou use as setas|r",
    ["Castbar position: x=%.0f, y=%.0f"] = "Posição da barra de conjuração: x=%.0f, y=%.0f",
    ["|cff9b6cffMind Flay|r"] = "|cff9b6cffFlagelo Mental|r",
    ["Castbar mover active. |cff9b6cffDrag purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Modo de mover da barra de conjuração ativo. |cff9b6cffArraste a caixa roxa|r ou use as |cff9b6cffsetas do teclado|r (SHIFT = 5px). Clique em 'Destravar / Testar' novamente para concluir.",
    ["Castbar mover disabled."] = "Modo de mover da barra de conjuração desativado.",
    ["Castbar Variant"] = "Variante da Barra de Conjuração",
    ["Switch between Original (Blizzard bar extended) and Custom castbar (VUI style with icon, spell name below bar)."] = "Alterne entre Original (barra da Blizzard estendida) e Personalizada (estilo VUI, com ícone e nome da magia abaixo da barra).",
    ["Original (Blizzard bar extended)"] = "Original (barra da Blizzard estendida)",
    ["Custom Castbar (VUI style)"] = "Barra de Conjuração Personalizada (estilo VUI)",
    ["Castbar mode switched to |cff9b6cffOriginal|r. |cffffff00/reload|r recommended so the default bar works normally again."] = "Modo da barra de conjuração alterado para |cff9b6cffOriginal|r. |cffffff00/reload|r recomendado para que a barra padrão volte a funcionar normalmente.",
    ["Castbar mode switched to |cff9b6cffVUI Style|r."] = "Modo da barra de conjuração alterado para |cff9b6cffEstilo VUI|r.",
    ["|cffaaaaaaMode switch: A /reload may be required after switching so the default bar works normally again.|r"] = "|cffaaaaaaTroca de modo: pode ser necessário um /reload após a troca para que a barra padrão volte a funcionar normalmente.|r",
    ["Show spell name"] = "Mostrar nome da magia",
    ["Show cast timer"] = "Mostrar cronômetro de conjuração",
    ["Show channel ticks"] = "Mostrar marcas de canalização",
    ["Shows vertical lines at tick points (Mind Flay, Drain Soul, Hellfire, etc.)"] = "Mostra linhas verticais nos pontos de pulso (Flagelo Mental, Drenar Alma, Fogo do Inferno, etc.)",
    ["Show clip window"] = "Mostrar janela de corte",
    ["Shades your latency at the end of the bar: on channels the moment to recast without losing the last tick, on casts the spell-queue window where the next cast can already be pressed."] = "Escurece sua latência no fim da barra: em canalizações, o momento de reconjurar sem perder o último pulso; em conjurações, a janela de fila em que a próxima magia já pode ser acionada.",
    ["Timer format"] = "Formato do cronômetro",
    ["Remaining / total (1.5 / 2.0)"] = "Restante / total (1.5 / 2.0)",
    ["Remaining only (1.5)"] = "Apenas restante (1.5)",
    ["Whole seconds (2)"] = "Segundos inteiros (2)",
    ["Show pushback"] = "Mostrar recuo",
    ["Briefly shows the time lost to spell pushback in red above the bar."] = "Mostra brevemente em vermelho, acima da barra, o tempo perdido com o recuo de conjuração.",
    ["Merge crafting casts"] = "Unir conjurações de criação",
    ["When crafting several items in a row the bar shows a counter like 3/20 instead of single casts."] = "Ao criar vários itens em sequência, a barra mostra um contador como 3/20 em vez de conjurações individuais.",
    ["Fill color"] = "Cor de preenchimento",
    ["Bar textures = the classic yellow/green art. Accent or class color tint a neutral bar instead."] = "Texturas de barra = a arte clássica amarela/verde. A cor de destaque ou a cor de classe tingem uma barra neutra.",
    ["Bar textures (yellow/green)"] = "Texturas de barra (amarelo/verde)",
    ["Accent color"] = "Cor de destaque",
    ["VUI Style: Position & Size"] = "Estilo VUI: Posição e Tamanho",
    ["Unlock / Test"] = "Destravar / Testar",
    ["Center Position"] = "Posição Central",
    ["|cffaaaaaaTip: Hold |cffffffffSHIFT|r and drag the castbar with the left mouse button during a cast to move it. Or use 'Unlock / Test' for a permanent test bar for positioning.|r"] = "|cffaaaaaaDica: segure |cffffffffSHIFT|r e arraste a barra de conjuração com o botão esquerdo durante uma conjuração para movê-la. Ou use 'Destravar / Testar' para ter uma barra de teste permanente e posicioná-la.|r",
    ["Show icon"] = "Mostrar ícone",
    ["Icon Size"] = "Tamanho do Ícone",
    ["Icon X Offset"] = "Deslocamento X do Ícone",
    ["Icon Y Offset"] = "Deslocamento Y do Ícone",
    ["Moves the icon horizontally. Negative = left, positive = right."] = "Move o ícone na horizontal. Negativo = esquerda, positivo = direita.",
    ["Moves the icon vertically. Positive = up, negative = down."] = "Move o ícone na vertical. Positivo = cima, negativo = baixo.",
    ["Test only available in 'Custom Castbar' mode."] = "O teste só está disponível no modo 'Barra de Conjuração Personalizada'.",
    ["Cooldown Pulse"] = "Pulso de Recarga",
    ["Shows the icon of an expired cooldown as a brief pulsing animation in the screen center."] = "Mostra o ícone de um tempo de recarga expirado como uma breve animação pulsante no centro da tela.",
    ["Test Spell"] = "Magia de Teste",
    ["Cooldown Pulse position reset."] = "Posição do Pulso de Recarga redefinida.",
    ["Test Pulse"] = "Pulso de Teste",
    ["Plays a test animation."] = "Reproduz uma animação de teste.",
    ["Reset Position"] = "Redefinir Posição",
    ["Max Opacity"] = "Opacidade Máxima",
    ["Animation Scale"] = "Escala da Animação",
    ["Fade-In Time (s)"] = "Tempo de Surgimento (s)",
    ["Hold Time (s)"] = "Tempo de Permanência (s)",
    ["Fade-Out Time (s)"] = "Tempo de Desvanecimento (s)",
    ["Show Before Available (s)"] = "Mostrar Antes de Ficar Pronto (s)",
    ["Triggers the animation X seconds BEFORE the cooldown expires. 0 = exactly at cooldown end."] = "Dispara a animação X segundos ANTES do fim do tempo de recarga. 0 = exatamente no fim da recarga.",
    ["Spell Filter"] = "Filtro de Magias",
    ["Show spell names"] = "Mostrar nomes das magias",
    ["Shows the name of the spell under the icon."] = "Mostra o nome da magia abaixo do ícone.",
    ["Invert filter (whitelist instead of blacklist)"] = "Inverter filtro (lista de permissão em vez de bloqueio)",
    ["Off: List = ignored spells. On: List = show ONLY these spells."] = "Desligado: lista = magias ignoradas. Ligado: lista = mostrar SOMENTE estas magias.",
    ["Spell List (comma-separated)"] = "Lista de Magias (separadas por vírgula)",
    ["Spell names exactly as in-game, comma-separated. Spell IDs also work."] = "Nomes das magias exatamente como no jogo, separados por vírgula. IDs de magia também funcionam.",
    ["Arena Frames"] = "Quadros de Arena",
    ["Enhances the Arena enemy frames: move/scale, class colors, class icons, PvP trinket CD, DR tracking, castbar, drag&drop layout."] = "Melhora os quadros dos inimigos na arena: mover/escalar, cores de classe, ícones de classe, recarga do berloque de PvP, rastreio de DR, barra de conjuração e disposição por arrastar e soltar.",
    ["|cffff5555ArenaFrames submodule error:|r %s"] = "|cffff5555Erro no submódulo ArenaFrames:|r %s",
    ["|cffff5555Arena submodule OnEnable error:|r %s"] = "|cffff5555Erro em OnEnable do submódulo de Arena:|r %s",
    ["Layout"] = "Disposição",
    ["Class Color"] = "Cor de Classe",
    ["PvP Trinket"] = "Berloque de PvP",
    ["DR Tracker"] = "Rastreador de DR",
    ["Castbar"] = "Barra de Conjuração",
    ["ArenaPlayer"] = "ArenaPlayer",
    ["Reset position"] = "Redefinir posição",
    ["Position reset."] = "Posição redefinida.",
    ["In unlock mode a purple overlay appears above the frames. Click + drag to move, mouse wheel to scale."] = "No modo destravado, uma sobreposição roxa aparece acima dos quadros. Clique + arraste para mover, roda do mouse para escalar.",
    ["Layout (Order)"] = "Disposição (Ordem)",
    ["Order of the arena frames. Use up/down to move slots 1-5."] = "Ordem dos quadros de arena. Use cima/baixo para mover os espaços 1-5.",
    ["|cff9b6cff%d.|r  Arena Slot %d"] = "|cff9b6cff%d.|r  Espaço de Arena %d",
    ["Move up"] = "Mover para cima",
    ["Move down"] = "Mover para baixo",
    ["Spacing between frames"] = "Espaçamento entre os quadros",
    ["Grow direction"] = "Direção de crescimento",
    ["Downward"] = "Para baixo",
    ["Upward"] = "Para cima",
    ["Reset order"] = "Redefinir ordem",
    ["Class Visuals"] = "Visuais de Classe",
    ["Class-colored health bars"] = "Barras de vida com cor de classe",
    ["Colors the health bar in the player's class color."] = "Colore a barra de vida com a cor de classe do jogador.",
    ["Class-colored name"] = "Nome com cor de classe",
    ["Class icon instead of portrait"] = "Ícone de classe em vez de retrato",
    ["Replaces the 3D portrait with a class symbol."] = "Substitui o retrato 3D por um símbolo de classe.",
    ["PvP Trinket Tracker"] = "Rastreador de Berloque de PvP",
    ["Show PvP trinket cooldown"] = "Mostrar recarga do berloque de PvP",
    ["Shows an icon with cooldown spiral next to the arena frame when the opponent used their PvP trinket."] = "Mostra um ícone com espiral de recarga ao lado do quadro de arena quando o oponente usa o berloque de PvP.",
    ["Icon size"] = "Tamanho do ícone",
    ["Left of frame"] = "À esquerda do quadro",
    ["Right of frame"] = "À direita do quadro",
    ["Offset X"] = "Deslocamento X",
    ["Offset Y"] = "Deslocamento Y",
    ["Diminishing Returns Tracker"] = "Rastreador de Retornos Decrescentes",
    ["Shows icons next to each arena frame for active DR categories (Stun, Fear, Polymorph etc.) with color indicator: |cff00ff00green|r = full, |cffffff00yellow|r = 1/2, |cffff8000orange|r = 1/4, |cffff0000red|r = immune."] = "Mostra ícones ao lado de cada quadro de arena para as categorias de DR ativas (Atordoamento, Medo, Polimorfar etc.) com indicador de cor: |cff00ff00verde|r = completo, |cffffff00amarelo|r = 1/2, |cffff8000laranja|r = 1/4, |cffff0000vermelho|r = imune.",
    ["Enable DR tracking"] = "Ativar rastreio de DR",
    ["INTERRUPTED"] = "INTERROMPIDO",
    ["Castbar for arena opponents"] = "Barra de conjuração dos oponentes na arena",
    ["Shows a castbar below the frame when the opponent casts or channels."] = "Mostra uma barra de conjuração abaixo do quadro quando o oponente conjura ou canaliza.",
    ["Collection of simple quality-of-life toggles: auto-accept (quest, res, summon), auto-sell, repair, hide UI spam, text sizes."] = "Conjunto de ajustes simples de qualidade de vida: aceitar automaticamente (missão, ressurreição, invocação), venda automática, reparo, ocultar excessos da interface e tamanhos de texto.",
    ["Auto-sold: %d items, +%s"] = "Vendido automaticamente: %d itens, +%s",
    ["Auto-sold: %d items."] = "Vendido automaticamente: %d itens.",
    ["Repair exceeds gold (%d < %d)."] = "O reparo excede seu ouro (%d < %d).",
    ["Auto-repaired (%dg %ds)."] = "Reparo automático (%do %dp).",
    ["MAX"] = "MÁX",
    ["General - Auto Actions"] = "Geral - Ações Automáticas",
    ["|cffaaaaaaSimple on/off switches for common QoL actions. Take effect immediately, no /reload needed.|r"] = "|cffaaaaaaInterruptores simples para ações comuns de qualidade de vida. Têm efeito imediato, sem precisar de /reload.|r",
    ["Auto-accept quests"] = "Aceitar missões automaticamente",
    ["Automatically accepts quests when clicking an NPC."] = "Aceita missões automaticamente ao clicar em um NPC.",
    ["Auto-turn in quests"] = "Entregar missões automaticamente",
    ["Automatically completes finished quests. Waits for user choice on multi-reward quests (no auto-pick)."] = "Conclui automaticamente as missões finalizadas. Aguarda a escolha do usuário em missões com várias recompensas (sem escolha automática).",
    ["Auto-accept resurrect"] = "Aceitar ressurreição automaticamente",
    ["Automatically clicks 'Accept' on resurrect popups (not in combat)."] = "Clica automaticamente em 'Aceitar' nos avisos de ressurreição (fora de combate).",
    ["Auto-accept summon"] = "Aceitar invocação automaticamente",
    ["Automatically clicks 'Accept' on warlock/stone summon popups."] = "Clica automaticamente em 'Aceitar' nos avisos de invocação de bruxo/pedra.",
    ["Auto-release spirit in PvP/Arena"] = "Libertar espírito automaticamente em PvP/Arena",
    ["Releases instantly on death in BG or arena."] = "Liberta instantaneamente ao morrer em campo de batalha ou arena.",
    ["Auto-sell junk (grey)"] = "Vender lixo automaticamente (cinza)",
    ["Sells all grey items when opening a vendor. Earnings shown in chat."] = "Vende todos os itens cinzas ao abrir um vendedor. Os ganhos aparecem no bate-papo.",
    ["Auto-repair"] = "Reparo automático",
    ["Repairs entire equipment at the vendor if gold is sufficient."] = "Repara todo o equipamento no vendedor se houver ouro suficiente.",
    ["Stack-split popup: MAX button"] = "Aviso de divisão de pilha: botão MÁX",
    ["Adds a 'MAX' button to the quantity popup. Click = buy full stack (at vendor) or split completely (for bag items)."] = "Adiciona um botão 'MÁX' ao aviso de quantidade. Clique = comprar a pilha inteira (no vendedor) ou dividir por completo (itens da mochila).",
    ["Stack-split popup: VuloUI look"] = "Aviso de divisão de pilha: visual VuloUI",
    ["Restyles the quantity popup (stack buying/splitting) to match the addon look: dark panel, clean buttons and arrows. Turning this off needs a /reload."] = "Reestiliza o aviso de quantidade (compra/divisão de pilhas) para combinar com o visual do addon: painel escuro, botões e setas limpos. Desativar isto exige um /reload.",
    ["Hide UI error messages"] = "Ocultar mensagens de erro da interface",
    ["Hides the red error messages in the screen center."] = "Oculta as mensagens de erro vermelhas no centro da tela.",
    ["Hide zone text"] = "Ocultar nome da zona",
    ["Hides the large zone name when entering new areas."] = "Oculta o nome grande da zona ao entrar em novas áreas.",
    ["Hide level numbers on portrait"] = "Ocultar números de nível no retrato",
    ["Hides the level display on the Player/Target/Pet portrait."] = "Oculta a exibição de nível no retrato de jogador/alvo/mascote.",
    ["Hide keybind text on action buttons"] = "Ocultar texto das teclas nos botões de ação",
    ["Hides the small key labels (1, F1, etc.) on the action buttons."] = "Oculta as pequenas etiquetas de tecla (1, F1, etc.) nos botões de ação.",
    ["Hide macro/spell names on action buttons"] = "Ocultar nomes de macro/magia nos botões de ação",
    ["Hides the text labels under the action buttons."] = "Oculta as etiquetas de texto abaixo dos botões de ação.",
    ["Hide stack/charge numbers on action buttons"] = "Ocultar números de pilha/cargas nos botões de ação",
    ["Hides the small boxes with numbers at the top right (item stacks, charges, cooldown seconds for long CDs)."] = "Oculta as pequenas caixas com números no canto superior direito (pilhas de itens, cargas, segundos de recarga em recargas longas).",
    ["Hide raid group labels"] = "Ocultar rótulos de grupo de raide",
    ["Hides the 'Group 1'/'Group 2' labels above the compact raid frames."] = "Oculta os rótulos 'Grupo 1'/'Grupo 2' acima dos quadros compactos de raide.",
    ["Mail Text Size"] = "Tamanho do Texto do Correio",
    ["Font size in mail body (opened + sent mail)."] = "Tamanho da fonte no corpo do correio (mensagens abertas e enviadas).",
    ["Quest Text Size"] = "Tamanho do Texto de Missões",
    ["Font size in quest descriptions + quest log."] = "Tamanho da fonte nas descrições de missões e no diário de missões.",
    ["Book Text Size"] = "Tamanho do Texto de Livros",
    ["Font size in readable books and letters from item text."] = "Tamanho da fonte em livros legíveis e cartas com texto de item.",
    ["Queue Timer"] = "Cronômetro de Fila",
    ["Shows a countdown on the PvP/PvE queue pop dialog. Optional sound warning at 5 seconds."] = "Mostra uma contagem regressiva no aviso de fila de PvP/PvE. Aviso sonoro opcional aos 5 segundos.",
    ["Queue expires in"] = "A fila expira em",
    ["|cff00c0ffQueueTimer:|r "] = "|cff00c0ffQueueTimer:|r ",
    ["Dungeon queue popped instantly!"] = "A fila da masmorra abriu instantaneamente!",
    ["Dungeon queue popped after %s"] = "A fila da masmorra abriu após %s",
    ["Dungeon queue popped."] = "A fila da masmorra abriu.",
    ["Queue popped instantly!"] = "A fila abriu instantaneamente!",
    ["Queue popped after %s"] = "A fila abriu após %s",
    ["Sound on queue pop"] = "Som ao abrir a fila",
    ["Plays a sound as soon as the queue pops."] = "Toca um som assim que a fila abre.",
    ["5-second warning"] = "Aviso de 5 segundos",
    ["Plays 3 quick sounds when only 5 seconds remain to accept."] = "Toca 3 sons rápidos quando restam apenas 5 segundos para aceitar.",
    ["Hide other timers (e.g. BigWigs)"] = "Ocultar outros cronômetros (ex.: BigWigs)",
    ["Hides foreign StatusBars on the LFG ready popup so only our timer is visible."] = "Oculta StatusBars externas no aviso de prontidão do LFG para que apenas o nosso cronômetro apareça.",
    ["Tooltip IDs"] = "IDs nas Dicas",
    ["Shows SpellID, ItemID, NPC ID and many other IDs in tooltips (based on idTip by silverwind)."] = "Mostra SpellID, ItemID, NPC ID e muitos outros IDs nas dicas (baseado em idTip, de silverwind).",
    ["|cff9b6cffTalents:|r "] = "|cff9b6cffTalentos:|r ",
    ["|cff9b6cffiLvL:|r %d"] = "|cff9b6cffiLvL:|r %d",
    ["  |cff888888(off by default)|r"] = "  |cff888888(desativado por padrão)|r",
    ["Shows %s in tooltips."] = "Mostra %s nas dicas.",
    ["Shows additional ID lines in tooltips, e.g. spell, item or NPC IDs."] = "Mostra linhas adicionais de ID nas dicas, por exemplo IDs de magia, item ou NPC.",
    ["Quick Select"] = "Seleção Rápida",
    ["All on"] = "Tudo ligado",
    ["All off"] = "Tudo desligado",
    ["Defaults"] = "Padrões",
    ["Player Tooltip (Inspect-based)"] = "Dica de Jogador (via inspeção)",
    ["|cffaaaaaaWhen you hover over a player, their average iLvL + talent distribution (e.g. 14/0/47) is shown in the tooltip. Data is cached 60s per player, inspect throttle 1/s.|r"] = "|cffaaaaaaAo passar o mouse sobre um jogador, o nível de item médio e a distribuição de talentos (ex.: 14/0/47) aparecem na dica. Os dados ficam em cache por 60s por jogador, com limite de inspeção de 1/s.|r",
    ["Show average iLvL"] = "Mostrar nível de item médio",
    ["Show talent distribution (e.g. 14/0/47)"] = "Mostrar distribuição de talentos (ex.: 14/0/47)",
    ["ID Types"] = "Tipos de ID",
    ["Auto Item Buy"] = "Compra Automática de Itens",
    ["Automatically buys configured items at configured vendors. Shift when opening the merchant window = emergency stop."] = "Compra automaticamente os itens configurados nos vendedores configurados. Segurar Shift ao abrir a janela do vendedor = parada de emergência.",
    ["|cffffd200[AutoItemBuy]|r "] = "|cffffd200[AutoItemBuy]|r ",
    ["Buying: "] = "Comprando: ",
    ["Close merchant window after purchase"] = "Fechar a janela do vendedor após a compra",
    ["Closes the merchant window automatically ~0.2s after purchase."] = "Fecha a janela do vendedor automaticamente ~0.2s após a compra.",
    ["Chat message on each purchase"] = "Mensagem no bate-papo a cada compra",
    ["|cffaaaaaaTip: Hold SHIFT when opening the merchant window to skip automatic purchase once.|r"] = "|cffaaaaaaDica: segure SHIFT ao abrir a janela do vendedor para pular a compra automática uma vez.|r",
    ["Add Vendor"] = "Adicionar Vendedor",
    ["Vendor Name"] = "Nome do Vendedor",
    ["Add"] = "Adicionar",
    ["|cffff5555Please enter a vendor name.|r"] = "|cffff5555Por favor, insira um nome de vendedor.|r",
    ["|cffff5555Vendor '%s' already exists.|r"] = "|cffff5555O vendedor '%s' já existe.|r",
    ["Vendor '%s' added."] = "Vendedor '%s' adicionado.",
    ["Manage Vendors"] = "Gerenciar Vendedores",
    ["|cffaaaaaaNo vendors added yet. Add a vendor above, then select it here to configure items.|r"] = "|cffaaaaaaNenhum vendedor adicionado ainda. Adicione um vendedor acima e depois selecione-o aqui para configurar os itens.|r",
    ["Currently selected vendor"] = "Vendedor selecionado atualmente",
    ["Delete this vendor"] = "Excluir este vendedor",
    ["Vendor '%s' removed."] = "Vendedor '%s' removido.",
    ["Items at '%s'"] = "Itens em '%s'",
    ["Item name (exactly as in-game)"] = "Nome do item (exatamente como no jogo)",
    ["|cffff5555Please enter an item name.|r"] = "|cffff5555Digite um nome de item.|r",
    ["Item '%s' added at vendor '%s'."] = "Item “%s” adicionado ao vendedor “%s”.",
    ["|cffaaaaaaItem names must match the in-game name exactly (including case and special characters).|r"] = "|cffaaaaaaOs nomes dos itens devem corresponder exatamente ao nome no jogo (incluindo maiúsculas e caracteres especiais).|r",
    ["|cffaaaaaaNo items configured. Add items above that should be bought automatically at this vendor.|r"] = "|cffaaaaaaNenhum item configurado. Adicione acima os itens que devem ser comprados automaticamente neste vendedor.|r",
    ["Remove"] = "Remover",
    ["Item '%s' removed."] = "Item “%s” removido.",
    ["Inspect Fix"] = "Correção de Inspeção",
    ["Inspect state manually reset. Try again now."] = "Estado de inspeção redefinido manualmente. Tente novamente agora.",
    ["|cffffff00[VuloClassicUI]|r Inspect state reset."] = "|cffffff00[VuloClassicUI]|r Estado de inspeção redefinido.",
    ["Auto-reset on timeout"] = "Redefinição automática por tempo limite",
    ["If no response from the server comes after X seconds, the pending inspect state is automatically reset — so the next inspect attempt works again."] = "Se nenhuma resposta do servidor chegar após X segundos, o estado de inspeção pendente é redefinido automaticamente — assim a próxima tentativa de inspeção volta a funcionar.",
    ["How long to wait for INSPECT_READY before auto-reset kicks in. 5 seconds is the new default for Anniversary — fast enough to recover quickly."] = "Quanto tempo esperar por INSPECT_READY antes de a redefinição automática entrar em ação. 5 segundos é o novo padrão no Anniversary — rápido o bastante para recuperar logo.",
    ["|cffaaaaaaSlash commands: /inspectreset (force-reset), /inspectstate (debug info in chat)|r"] = "|cffaaaaaaComandos: /inspectreset (redefinição forçada), /inspectstate (informações de depuração no chat)|r",
    ["Timeout (seconds)"] = "Tempo limite (segundos)",
    ["Manual Reset"] = "Redefinição manual",
    ["Reset inspect state now"] = "Redefinir o estado de inspeção agora",
    ["Inspect state manually reset."] = "Estado de inspeção redefinido manualmente.",
    ["NotifyInspect hook: %s\nInspectFrame hook: %s"] = "Gancho em NotifyInspect: %s\\nGancho em InspectFrame: %s",
    ["|cff66ff66active|r"] = "|cff66ff66ativo|r",
    ["|cffff8800waiting|r"] = "|cffff8800aguardando|r",
    ["|cffff8800waiting for Blizzard_InspectUI|r"] = "|cffff8800aguardando Blizzard_InspectUI|r",
    ["|cffaaaaaaWhat the fix does: tracks active inspects with a timestamp, repaints late-arriving item data, re-requests an all-empty inspect once, and calls ClearInspectPlayer() on close + on timeout. Prevents a stuck state from blocking all subsequent inspects.|r"] = "|cffaaaaaaO que a correção faz: acompanha as inspeções ativas com um registro de tempo, redesenha os dados de itens que chegam atrasados, solicita novamente uma vez a inspeção que veio totalmente vazia e chama ClearInspectPlayer() ao fechar e no tempo limite. Evita que um estado travado bloqueie todas as inspeções seguintes.|r",
    ["Auto-retry empty inspects"] = "Repetir inspeções vazias automaticamente",
    ["After the server answers, the item slots are repainted again shortly after (data often arrives late). If the window is still completely empty, the inspect is automatically requested one more time."] = "Depois que o servidor responde, os espaços de itens são redesenhados pouco depois (os dados costumam chegar atrasados). Se a janela ainda estiver completamente vazia, a inspeção é solicitada mais uma vez automaticamente.",
    ["|cffaaaaaaStatus: %s|r"] = "|cffaaaaaaEstado: %s|r",
    ["|cff66ff66Hook active|r"] = "|cff66ff66Gancho ativo|r",
    ["LFG Browse Nil Fix"] = "Correção de Nil na Busca de Grupo",
    ["Catches Lua errors in the Anniversary Group Finder (LFGBrowseSearchEntry_Update with stale resultIDs). Prevents chat spam and broken browse lists."] = "Captura erros de Lua no Localizador de Grupo do Anniversary (LFGBrowseSearchEntry_Update com resultIDs obsoletos). Evita spam no chat e listas de busca quebradas.",
    ["|cffffff00[VuloClassicUI]|r Blizzard LFG browse error caught (stale entry skipped)."] = "|cffffff00[VuloClassicUI]|r Erro da busca de grupo da Blizzard capturado (entrada obsoleta ignorada).",
    ["Chat message on first error"] = "Mensagem no chat no primeiro erro",
    ["Shows a brief message once per session in chat when an LFG browse error was caught."] = "Mostra uma mensagem breve no chat, uma vez por sessão, quando um erro da busca de grupo é capturado.",
    ["This fix wraps Blizzard's |cffffffffLFGBrowseSearchEntry_Update|r function in a protected call (xpcall). When the entry crashes due to a stale resultID (\"searchResultInfo nil\"), the error is swallowed — Blizzard's next refresh automatically cleans up the list entry."] = "Esta correção envolve a função |cffffffffLFGBrowseSearchEntry_Update|r da Blizzard em uma chamada protegida (xpcall). Quando a entrada falha por um resultID obsoleto (“searchResultInfo nil”), o erro é absorvido — a próxima atualização da Blizzard limpa a entrada da lista automaticamente.",
    ["waiting for Blizzard_GroupFinder_VanillaStyle"] = "aguardando Blizzard_GroupFinder_VanillaStyle",
    ["Guild News Nil Fix"] = "Correção de Nil nas Notícias da Guilda",
    ["Catches Lua errors in guild news entries (typically \"formatString\" or \"GuildUtil\") and replaces broken entries with a fallback text instead of letting the whole panel break."] = "Captura erros de Lua nas entradas de notícias da guilda (normalmente “formatString” ou “GuildUtil”) e substitui as entradas quebradas por um texto alternativo, em vez de deixar o painel inteiro quebrar.",
    ["|cffff8080Invalid guild news entry|r"] = "|cffff8080Entrada de notícia da guilda inválida|r",
    ["|cffffff00[VuloClassicUI]|r Blizzard guild news error caught (fallback applied)."] = "|cffffff00[VuloClassicUI]|r Erro das notícias da guilda da Blizzard capturado (texto alternativo aplicado).",
    ["Shows a brief message once per session in chat when a guild news error was caught."] = "Mostra uma mensagem breve no chat, uma vez por sessão, quando um erro das notícias da guilda é capturado.",
    ["This fix wraps Blizzard's |cffffffffGuildNewsButton_SetNews|r function in a protected call (xpcall). When an entry throws a known error (\"formatString\" or \"GuildUtil\"), the entry is replaced with a fallback text \"Invalid guild news entry\" — the panel remains usable."] = "Esta correção envolve a função |cffffffffGuildNewsButton_SetNews|r da Blizzard em uma chamada protegida (xpcall). Quando uma entrada gera um erro conhecido (“formatString” ou “GuildUtil”), ela é substituída pelo texto alternativo “Entrada de notícia da guilda inválida” — o painel continua utilizável.",
    ["waiting for Blizzard_Communities"] = "aguardando Blizzard_Communities",
    ["Auction Price Fix"] = "Correção de Preço do Leilão",
    ["Fixes a nil error in the German auction house UI (PriceDropdown not defined)."] = "Corrige um erro de nil na interface da casa de leilões em alemão (PriceDropdown não definido).",
    ["This fix addresses a known bug in the German WoW localization: the auction house UI references a \"PriceDropdown\" element that was never defined, which causes Lua errors when opening the auction house."] = "Esta correção trata de um bug conhecido na localização alemã do WoW: a interface da casa de leilões usa um elemento “PriceDropdown” que nunca foi definido, o que causa erros de Lua ao abrir a casa de leilões.",
    ["|cffaaaaaaCurrent locale: %s|r"] = "|cffaaaaaaIdioma atual: %s|r",
    ["|cffaaaaaaThe fix only applies on German clients (deDE). On other languages the module is inactive.|r"] = "|cffaaaaaaA correção só se aplica a clientes em alemão (deDE). Nos outros idiomas o módulo fica inativo.|r",
    ["|cff66ff66applied|r"] = "|cff66ff66aplicada|r",
    ["skipped (deDE-only)"] = "ignorada (apenas deDE)",
    ["not applied"] = "não aplicada",
