    ["|cffffffffCOMBAT TEXT|r"] = "|cffffffffTEXTO DE COMBATE|r",
    ["Flashing combat notifications (with live preview) plus a scrolling combat-log text engine."] = "Notificações de combate piscantes (com pré-visualização ao vivo) e um motor de texto rolante para o registro de combate.",
    ["Show Preview"] = "Mostrar pré-visualização",
