    ["Also apply font to Blizzard mob FCT"] = "Aplicar a fonte também ao texto flutuante dos monstros da Blizzard",
    ["Additionally sets DAMAGE_TEXT_FONT globally - changes the font of the damage numbers above mobs/pets. Requires /reload to take effect."] = "Define adicionalmente DAMAGE_TEXT_FONT de forma global - muda a fonte dos números de dano acima de monstros/pets. Requer /reload para valer.",
    ["Interrupted"] = "Interrompido",
    ["Parried/Dodged/Missed"] = "Aparado/Esquivado/Errou",
    ["Engine FCT (above mob/pet)"] = "Texto flutuante do motor (acima do monstro/pet)",
    ["Sharper hit indicator font (Friz Quadrata)"] = "Fonte mais nítida no indicador de acerto (Friz Quadrata)",
    ["Engine FCT Scale"] = "Escala do texto flutuante do motor",
    ["Damage numbers above mob/pet — bitmap scaling."] = "Números de dano acima do monstro/pet — escala de bitmap.",
    ["Center"] = "Centralizar",
    ["Unlock / Position"] = "Desbloquear / posicionar",
    ["Trinkets"] = "Berloques",
    ["Two trinket slots on screen with cooldown display, dropdown selection and auto-queue."] = "Dois espaços de berloque na tela com tempo de recarga, seleção por menu suspenso e fila automática.",
    ["|cffaaaaaaTwo trinket slots with cooldown, dropdown selection and auto-queue.|nLeft click = use, right click = dropdown.|r"] = "|cffaaaaaaDois espaços de berloque com tempo de recarga, seleção por menu suspenso e fila automática.|nClique esquerdo = usar, clique direito = menu suspenso.|r",
    ["Show frame"] = "Mostrar o quadro",
    ["Hides or shows the two trinket slots. Auto-queue continues to run while hidden."] = "Oculta ou mostra os dois espaços de berloque. A fila automática continua funcionando enquanto estiverem ocultos.",
    ["Position locked"] = "Posição travada",
    ["If on, the frame cannot be accidentally moved."] = "Se ativado, o quadro não pode ser movido sem querer.",
    ["Size"] = "Tamanho",
    ["Scales the trinket slots."] = "Ajusta a escala dos espaços de berloque.",
    ["Character Panel"] = "Painel do Personagem",
    ["Dark Skin"] = "Visual Escuro",
    ["The dark look of the UI in one place: a built-in dark skin for action buttons and WeakAuras icons, plus an optional Dark Mode that darkens Blizzard's default frames, minimap and bars."] = "O visual escuro da interface em um só lugar: um visual escuro integrado para os botões de ação e os ícones do WeakAuras, além de um Modo Escuro opcional que escurece os quadros padrão da Blizzard, o minimapa e as barras.",
    ["The dark action-bar button skin."] = "O visual escuro dos botões da barra de ação.",
    ["Enable Dark Mode"] = "Ativar o Modo Escuro",
    ["Re-tints Blizzard's default frames, minimap and action-bar artwork to a dark tone. Off by default."] = "Recolore os quadros padrão da Blizzard, o minimapa e a arte das barras de ação num tom escuro. Desativado por padrão.",
    ["|cffaaaaaaOptional: darkens and desaturates Blizzard's default artwork — unit frames, minimap and action bars — to a neutral dark tone. Reversible: turn it off and the gold look returns.|r"] = "|cffaaaaaaOpcional: escurece e dessatura a arte padrão da Blizzard — quadros de unidade, minimapa e barras de ação — deixando-a num tom escuro neutro. Reversível: desative e o visual dourado volta.|r",
    ["Action Bars"] = "Barras de Ação",
    ["Skin the action bars"] = "Aplicar o visual às barras de ação",
    ["Bar style"] = "Estilo da barra",
    ["WeakAuras Icons"] = "Ícones do WeakAuras",
    ["Skin WeakAuras icons"] = "Aplicar o visual aos ícones do WeakAuras",
    ["Hide WeakAuras' own border"] = "Ocultar a borda própria do WeakAuras",
    ["Hides the light border WeakAuras draws on icons, so only our dark rim shows. /reload to fully restore it."] = "Oculta a borda clara que o WeakAuras desenha nos ícones, deixando visível só a nossa borda escura. Use /reload para restaurá-la por completo.",
    ["Circle"] = "Círculo",
    ["Also skin pet & stance buttons"] = "Aplicar o visual também aos botões de pet e de postura",
    ["Enhances the character panel: iLvL per slot, socket display, shortened enchant text."] = "Aprimora o painel do personagem: nível de item por espaço, exibição de engastes, texto de encantamento abreviado.",
    ["Show item level per slot"] = "Mostrar o nível de item por espaço",
    ["Show average item level"] = "Mostrar o nível de item médio",
    ["Show sockets"] = "Mostrar os engastes",
    ["Shorten enchant text (DE/EN)"] = "Abreviar o texto de encantamento (DE/EN)",
    ["Example: 'Stamina' -> 'Stam', 'Ausdauer' -> 'Ausd'."] = "Exemplo: “Stamina” → “Stam”, “Ausdauer” → “Ausd”.",
    ["Treat rings as enchantable"] = "Tratar anéis como encantáveis",
    ["Also shows enchant text on rings (TBC: some professions can enchant rings). /reload required."] = "Mostra o texto de encantamento também nos anéis (TBC: algumas profissões podem encantar anéis). Requer /reload.",
    ["Text Size"] = "Tamanho do texto",
    ["Item Level Text Size"] = "Tamanho do texto do nível de item",
    ["Font size of the item level number on each item slot. Takes effect immediately when the character panel is open."] = "Tamanho da fonte do número de nível de item em cada espaço de item. Vale imediatamente com o painel do personagem aberto.",
    ["Note: Some changes only take full effect after /reload, since the character panel is hooked on load."] = "Observação: algumas mudanças só valem por completo após um /reload, pois o painel do personagem é enganchado no carregamento.",
    ["|cffff0000No Ench|r"] = "|cffff0000Sem enc.|r",
    ["|c%siLvL - %d|r"] = "|c%siLvL - %d|r",
    ["Gold Tracker"] = "Rastreador de Ouro",
    ["Shows in the backpack gold tooltip how much gold has been gained or spent since the last reset. Per-char persistent."] = "Mostra na dica de ouro da mochila quanto ouro foi ganho ou gasto desde a última redefinição. Persistente por personagem.",
    ["Gold Tracker reset|r. Start = "] = "Rastreador de Ouro redefinido|r. Início = ",
    ["Gold Balance|r"] = "Balanço de Ouro|r",
    ["Gained:|r"] = "Ganho:|r",
    ["Spent:|r"] = "Gasto:|r",
    ["|cffffffffNet:|r"] = "|cffffffffSaldo:|r",
    ["Start:|r"] = "Início:|r",
    ["Now:|r"] = "Agora:|r",
    ["Reset with /vcui goldreset|r"] = "Redefina com /vcui goldreset|r",
    ["|cffaaaaaaShows in the backpack gold tooltip the balance since the last manual reset:|n  - |cff44ff44Gained|r (quests, loot, vendor sales, mail)|n  - |cffff4444Spent|r (repair, vendor buy, mail cost)|n  - |cffffffffNet|r (+/- since reset)|n|nValues are |cffffffffper-char persistent|r across /reload and logout.|nOffline gold (AH mail, trade) is not counted.|n|nReset: button below or |cffffff00/vcui goldreset|r.|r"] = "|cffaaaaaaMostra na dica de ouro da mochila o balanço desde a última redefinição manual:|n  - |cff44ff44Ganho|r (missões, saques, vendas a vendedores, correio)|n  - |cffff4444Gasto|r (reparos, compras em vendedores, custo do correio)|n  - |cffffffffSaldo|r (+/- desde a redefinição)|n|nOs valores são |cffffffffpersistentes por personagem|r após /reload e logout.|nO ouro recebido offline (correio da casa de leilões, troca) não é contado.|n|nRedefinir: botão abaixo ou |cffffff00/vcui goldreset|r.|r",
    ["Reset session"] = "Redefinir a sessão",
    ["Class Specific"] = "Específico da Classe",
    ["|cffaaaaaaVampiric Touch mana tracker — shows live how much mana you've given to the group (5% of shadow damage per tick, per mana user).|n|cffffffffReset automatically on combat start.|r|r"] = "|cffaaaaaaRastreador de mana do Toque Vampírico — mostra ao vivo quanta mana você deu ao grupo (5% por tique do dano sombrio, por usuário de mana).|n|cffffffffRedefinido automaticamente no início do combate.|r|r",
    ["|cffff8800These tools are only active while playing a Priest.|r"] = "|cffff8800Estas ferramentas só ficam ativas jogando de Sacerdote.|r",
    ["No tools yet"] = "Ainda sem ferramentas",
    ["|cffaaaaaaNo class-specific tools for this class yet. Got an idea? Let me know!|r"] = "|cffaaaaaaAinda não há ferramentas específicas para esta classe. Tem uma ideia? Me avise!|r",
    ["|cff9b6cffVT Mana:|r %d"] = "|cff9b6cffMana do TV:|r %d",
    ["|cff9b6cffVT Mana:|r 0"] = "|cff9b6cffMana do TV:|r 0",
    ["Vampiric Touch: %d mana given to the group."] = "Toque Vampírico: %d de mana dado ao grupo.",
    ["|cffffffffVT MANA|r"] = "|cffffffffMANA DO TV|r",
    ["VT mana frame: x=%.0f, y=%.0f"] = "Quadro da mana do TV: x=%.0f, y=%.0f",
    ["VT mana mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Movedor da mana do TV ativo. |cff9b6cffArraste|r ou use as |cff9b6cffsetas|r (SHIFT = 5px).",
    ["VT mana mover disabled."] = "Movedor da mana do TV desativado.",
    ["Print to chat at combat end"] = "Escrever no chat ao fim do combate",
    ["Writes a summary in chat after each fight."] = "Escreve um resumo no chat depois de cada luta.",
    ["Reset manually"] = "Redefinir manualmente",
    ["VT mana reset."] = "Mana do TV redefinida.",
    ["Bars"] = "Barras",
    ["Icons"] = "Ícones",
    ["Shadow Word: Pain"] = "Palavra Sombria: Dor",
    ["Vampiric Touch"] = "Toque Vampírico",
    ["Devouring Plague"] = "Praga Devoradora",
    ["Warning (seconds left)"] = "Aviso (segundos restantes)",
    ["Bar width"] = "Largura da barra",
    ["Bar height"] = "Altura da barra",
    ["Spacing"] = "Espaçamento",
    ["Color the timer text"] = "Colorir o texto do temporizador",
    ["Show recast gain %"] = "Mostrar o ganho de relançamento em %",
    ["Shows how much harder a fresh cast would hit right now (e.g. +12% with a spell power proc up). Negative values mean the running DoT snapshotted stronger — keep it."] = "Mostra quanto um novo lançamento bateria mais forte agora (por exemplo, +12% com um efeito de poder mágico ativo). Valores negativos significam que o DoT em andamento foi registrado mais forte — mantenha-o.",
    ["DoT Tracker"] = "Rastreador de DoTs",
    ["|cffaaaaaaTracks your DoTs on the target. |cff44ff44Green|r = a buff is up that makes it hit harder if you recast now (TBC snapshot); |cffff4444red|r = about to expire.|r"] = "|cffaaaaaaAcompanha seus DoTs no alvo. |cff44ff44Verde|r = há um benefício ativo que faz o dano bater mais forte se você relançar agora (instantâneo do TBC); |cffff4444vermelho|r = prestes a expirar.|r",
    ["|cffff8800Only active while playing a %s.|r"] = "|cffff8800Só fica ativo jogando de %s.|r",
    ["|cffaaaaaaTracks your Warlock DoTs (Corruption, Curse of Agony, Unstable Affliction, Siphon Life, Immolate, Curse of Doom) on the target, with the same recast-snapshot readout as the Priest tracker.|r"] = "|cffaaaaaaAcompanha seus DoTs de Bruxo (Corrupção, Maldição da Agonia, Aflição Instável, Sifão de Vida, Imolar, Maldição da Perdição) no alvo, com a mesma leitura de instantâneo de relançamento do rastreador do Sacerdote.|r",
    ["Corruption"] = "Corrupção",
    ["Curse of Agony"] = "Maldição da Agonia",
    ["Unstable Affliction"] = "Aflição Instável",
    ["Siphon Life"] = "Sifão de Vida",
    ["Immolate"] = "Imolar",
    ["Curse of Doom"] = "Maldição da Perdição",
    ["|cffffffffDOTS|r"] = "|cffffffffDOTS|r",
    ["Shadow DoTs: x=%.0f, y=%.0f"] = "DoTs de Sombras: x=%.0f, y=%.0f",
    ["Shadow DoTs mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Movedor dos DoTs de Sombras ativo. |cff9b6cffArraste|r ou use as |cff9b6cffsetas|r (SHIFT = 5px).",
    ["Shadow DoTs mover disabled."] = "Movedor dos DoTs de Sombras desativado.",
    ["Mark empty sockets"] = "Marcar os engastes vazios",
    ["Adds a red ring around item sockets that have no gem."] = "Adiciona um anel vermelho nos engastes de itens sem gema.",
    ["Text shadow (instead of outline)"] = "Sombra no texto (em vez de contorno)",
    ["Cleaner text with a drop shadow instead of a thick outline."] = "Texto mais limpo, com sombra projetada em vez de um contorno grosso.",
    ["|cffaaaaaaA modern round minimap with a beveled ring, zone text and clock in a slim pill. Zoom with the mouse wheel. |cffffffffShift+drag the map|r to move it — or use Unlock / the addon's own Edit Mode (/vedit). Blizzard's Edit Mode does not manage this map.|r"] = "|cffaaaaaaUm minimapa redondo e moderno, com anel chanfrado, texto da zona e relógio numa faixa fina. Use a roda do mouse para o zoom. |cffffffffShift+arraste o mapa|r para movê-lo — ou use Desbloquear / o Modo de Edição do próprio addon (/vedit). O Modo de Edição da Blizzard não gerencia este mapa.|r",
    ["|cffffffffMINIMAP|r"] = "|cffffffffMINIMAPA|r",
    ["Minimap: x=%.0f, y=%.0f"] = "Minimapa: x=%.0f, y=%.0f",
    ["Minimap mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Movedor do minimapa ativo. |cff9b6cffArraste|r ou use as |cff9b6cffsetas|r (SHIFT = 5px).",
    ["Minimap module disabled — /reload restores the default layout completely."] = "Módulo do minimapa desativado — /reload restaura a disposição padrão por completo.",
    ["Minimap ping: %s"] = "Sinal no minimapa: %s",
    ["Shape"] = "Formato",
    ["Round"] = "Redondo",
    ["Accent ring"] = "Anel de destaque",
    ["Ring color"] = "Cor do anel",
    ["Accent (purple)"] = "Destaque (roxo)",
    ["Class color"] = "Cor da classe",
    ["Custom color"] = "Cor personalizada",
    ["Theme color"] = "Cor do tema",
    ["Dark guild & communities window"] = "Janela escura de guilda e comunidades",
    ["Restyles the guild and communities window to the same dark look. Turning it off needs a /reload."] = "Aplica à janela de guilda e comunidades o mesmo visual escuro. Desativar isso exige um /reload.",
    ["Debuffs on target (yours only)"] = "Penalidades no alvo (só as suas)",
    ["Missing buffs (reminder)"] = "Benefícios ausentes (lembrete)",
    ["|cffaaaaaaIcons appear while YOUR debuff/DoT is on the target, with its remaining time. Add the debuff by name or ID.|r"] = "|cffaaaaaaOs ícones aparecem enquanto SUA penalidade/DoT está no alvo, com o tempo restante. Adicione a penalidade pelo nome ou pelo ID.|r",
    ["|cffaaaaaaIcons appear while the buff is MISSING on you - a reminder for weapon oils, blessings, food buffs. Add the buff by name or ID.|r"] = "|cffaaaaaaOs ícones aparecem enquanto o benefício está FALTANDO em você - um lembrete para óleos de arma, bênçãos e benefícios de comida. Adicione o benefício pelo nome ou pelo ID.|r",
    ["Tint blue when out of mana"] = "Tingir de azul quando faltar mana",
    ["Tint red when out of range"] = "Tingir de vermelho quando estiver fora de alcance",
    ["Needs a target; uses the spell's own range."] = "Precisa de um alvo; usa o alcance da própria magia.",
    ["Auto-track equipped trinkets"] = "Rastrear automaticamente os berloques equipados",
    ["Keeps both equipped trinkets in this group automatically - they follow along when you swap trinkets."] = "Mantém os dois berloques equipados neste grupo automaticamente - eles acompanham quando você troca de berloque.",
    ["(copy)"] = "(cópia)",
    ["Show tooltips on hover"] = "Mostrar dicas ao passar o mouse",
    ["The icons then intercept the mouse - leave this off if the bar sits over clickable UI."] = "Os ícones então interceptam o mouse - deixe desativado se a barra ficar sobre partes clicáveis da interface.",
    ["Copy the link with Ctrl+C:"] = "Copie o link com Ctrl+C:",
    ["Click: copy link"] = "Clique: copiar o link",
    ["|cffaaaaaaColors everything that is purple today in the color of your choice - sidebar, borders, highlights, bars. A /reload applies it everywhere.|r"] = "|cffaaaaaaColore com a cor da sua escolha tudo o que hoje é roxo - barra lateral, bordas, destaques, barras. Um /reload aplica em todo lugar.|r",
    ["Preset"] = "Predefinição",
    ["Purple (default)"] = "Roxo (padrão)",
    ["Turquoise"] = "Turquesa",
    ["Pink"] = "Rosa",
    ["Orange"] = "Laranja",
    ["Theme color changed. /reload applies it to everything (elements already drawn keep the old color until then)."] = "Cor do tema alterada. /reload aplica em tudo (os elementos já desenhados mantêm a cor antiga até lá).",
    ["Custom ring color"] = "Cor personalizada do anel",
    ["A thin colored line around the dark ring (round shape only)."] = "Uma linha fina colorida ao redor do anel escuro (apenas no formato redondo).",
    ["Zone panel"] = "Painel da zona",
    ["Zone text and clock"] = "Texto da zona e relógio",
    ["Above the map"] = "Acima do mapa",
    ["Below the map"] = "Abaixo do mapa",
    ["Hidden"] = "Oculto",
    ["Show clock"] = "Mostrar o relógio",
    ["Show date"] = "Mostrar a data",
    ["Shows the date next to the clock. Click it to open the calendar."] = "Mostra a data ao lado do relógio. Clique nela para abrir o calendário.",
    ["Buttons"] = "Botões",
    ["Zoom buttons (+/-)"] = "Botões de zoom (+/-)",
    ["Shows a flat + and - on the right edge of the map. The mouse wheel always zooms too."] = "Mostra um + e um - discretos na borda direita do mapa. A roda do mouse também dá zoom sempre.",
    ["Show day/night button"] = "Mostrar o botão dia/noite",
    ["Restyle addon buttons"] = "Reestilizar os botões de addons",
    ["Removes the gold borders from other addons' minimap buttons and gives them a clean round look. Turning this off needs a /reload."] = "Remove as bordas douradas dos botões de minimapa de outros addons e dá a eles um visual redondo e limpo. Desativar isso exige um /reload.",
    ["Addon buttons only on mouseover"] = "Botões de addons só ao passar o mouse",
    ["Hides other addons' minimap buttons until the mouse is over the minimap."] = "Oculta os botões de minimapa de outros addons até o mouse estar sobre o minimapa.",
    ["Ping in chat"] = "Sinal no chat",
    ["Prints who pinged the minimap."] = "Escreve quem sinalizou no minimapa.",
    ["Totem Bar"] = "Barra de Totens",
    ["|cffaaaaaa|cffffffffLeft-click|r an icon to (re)cast that element's totem, |cffffffffhover|r a slot to pick which totem from the icon list, |cffffffffmiddle-click|r to recall all totems. The icon border turns red just before the totem expires.|r"] = "|cffaaaaaa|cffffffffClique esquerdo|r em um ícone para (re)invocar o totem daquele elemento, |cffffffffpasse o mouse|r sobre um espaço para escolher qual totem da lista de ícones, |cffffffffclique do meio|r para recolher todos os totens. A borda do ícone fica vermelha pouco antes de o totem expirar.|r",
    ["|cffff8800Only active while playing a Shaman.|r"] = "|cffff8800Só fica ativo jogando de Xamã.|r",
    ["Totem set"] = "Conjunto de totens",
    ["Active set"] = "Conjunto ativo",
    ["Set name"] = "Nome do conjunto",
    ["New set"] = "Novo conjunto",
    ["Delete set"] = "Excluir conjunto",
    ["Shown elements"] = "Elementos exibidos",
    ["Sound before a totem expires"] = "Som antes de um totem expirar",
    ["Icon border (action-bar style)"] = "Borda do ícone (estilo barra de ação)",
    ["Style"] = "Estilo",
    ["VuloUI (dark)"] = "VuloUI (escuro)",
    ["Classic (metal)"] = "Clássico (metal)",
    ["Flyout direction"] = "Direção do seletor",
    ["Which way the totem picker opens when you hover a slot. Automatic picks the side away from the screen edge."] = "Para que lado o seletor de totens abre ao passar o mouse sobre um espaço. Automático escolhe o lado oposto à borda da tela.",
    ["Automatic"] = "Automático",
    ["Upwards"] = "Para cima",
    ["Downwards"] = "Para baixo",
    ["To the left"] = "Para a esquerda",
    ["To the right"] = "Para a direita",
    ["Open flyout in combat"] = "Abrir o seletor em combate",
    ["Tooltip with cooldown on hover"] = "Dica com tempo de recarga ao passar o mouse",
    ["Hovering a totem slot or a picker icon shows the totem name and its remaining cooldown."] = "Passar o mouse sobre um espaço de totem ou sobre um ícone do seletor mostra o nome do totem e o tempo de recarga restante.",
    ["Off = hovering a slot never opens the totem picker while you are fighting (clicks still cast). The picker now also closes itself on mouse-out and after every cast, even in combat."] = "Desativado = passar o mouse sobre um espaço nunca abre o seletor de totens enquanto você luta (os cliques continuam lançando). O seletor agora também se fecha ao tirar o mouse e depois de cada lançamento, mesmo em combate.",
    ["Earth"] = "Terra",
    ["Water"] = "Água",
    ["|cffffffffTOTEMS|r"] = "|cffffffffTOTENS|r",
    ["Totems: x=%.0f, y=%.0f"] = "Totens: x=%.0f, y=%.0f",
    ["Totem timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Movedor do temporizador de totens ativo. |cff9b6cffArraste|r ou use as |cff9b6cffsetas|r (SHIFT = 5px).",
    ["Totem timer mover disabled."] = "Movedor do temporizador de totens desativado.",
    ["|cffff5555Class tool error:|r %s"] = "|cffff5555Erro na ferramenta de classe:|r %s",
    ["EDIT MODE"] = "MODO DE EDIÇÃO",
    ["Edit Mode"] = "Modo de Edição",
    ["Open Edit Mode"] = "Abrir o Modo de Edição",
    ["Close Edit Mode and lock all windows. Your changes stay applied."] = "Fecha o Modo de Edição e trava todas as janelas. Suas alterações continuam aplicadas.",
    ["Keep the current arrangement and carry on editing. Discard then returns to this point instead of to how things looked when Edit Mode opened."] = "Mantém a disposição atual e continua editando. Depois disso, Descartar volta para este ponto, e não para como estava quando o Modo de Edição foi aberto.",
    ["Window positions saved."] = "Posições das janelas salvas.",
    ["Exit"] = "Sair",
