    ["Reset all VuloUI window positions to the screen centre."] = "Redefine todas as posições das janelas do VuloUI para o centro da tela.",
    ["Reset all VuloUI window positions to the screen centre?"] = "Redefinir todas as posições das janelas do VuloUI para o centro da tela?",
    ["Done — lock everything"] = "Concluído — travar tudo",
    ["Grid"] = "Grade",
