    ["Show an alignment grid."] = "Mostra uma grade de alinhamento.",
    ["Snap windows to the grid while dragging."] = "Encaixa as janelas na grade ao arrastar.",
    ["%d frames here - hold Alt to cycle"] = "%d quadros aqui - segure Alt para alternar",
    ["Which screen point the frame is pinned to (keeps it put across resolution changes)."] = "A que ponto da tela o quadro está preso (mantém o lugar mesmo mudando de resolução).",
    ["ANCHOR"] = "ÂNCORA",
    ["POSITION"] = "POSIÇÃO",
    ["SCALE"] = "ESCALA",
    ["FREE MOVE"] = "MOVIMENTO LIVRE",
    ["FOLLOW WINDOW"] = "SEGUIR JANELA",
    ["Pins this window to another one - it then moves along whenever that window is moved. Dragging this window keeps the pin and just updates the distance."] = "Prende esta janela a outra - ela passa a se mover junto sempre que a outra for movida. Arrastar esta janela mantém a fixação e apenas atualiza a distância.",
    ["Not possible - that would create a loop."] = "Não é possível - isso criaria um laço.",
    ["Shows a friendly NPC's subtitle (e.g. <Innkeeper>) under its name in name-only mode."] = "Exibe o subtítulo de um NPC amigável (ex.: <Estalajadeiro>) sob o nome no modo somente nome.",
    ["<Innkeeper>"] = "<Estalajadeiro>",
