    ["Faded opacity"] = "Opacidade esmaecida",
    ["Fade speed (sec.)"] = "Velocidade do esmaecimento (seg.)",
    ["|cffff5555Action Bars: leaving combat to restore Blizzard's bars…|r"] = "|cffff5555Barras de Ação: aguardando o fim do combate para restaurar as barras da Blizzard…|r",
    ["|cffaaaaaaOwn buttons for every action bar (1-5): real combat / mouseover show-hide, scale and grid layout, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. Move each in Edit Mode (/vedit). After disabling, /reload to fully restore Blizzard's bars.|r"] = "|cffaaaaaaBotões próprios para todas as barras de ação (1-5): exibição/ocultação real em combate / ao passar o mouse, escala e disposição em grade, paginação correta da barra principal (formas de druida/ladino/guerreiro/sacerdote) e seus atalhos. Mova cada uma no Modo de Edição (/vedit). Após desativar, use /reload para restaurar totalmente as barras da Blizzard.|r",
    ["Action Bar 1 (Main)"] = "Barra de Ação 1 (Principal)",
    ["Action Bar 2"] = "Barra de Ação 2",
    ["Action Bar 3"] = "Barra de Ação 3",
    ["Action Bar 4"] = "Barra de Ação 4",
    ["Action Bar 5"] = "Barra de Ação 5",
    ["Action Bar 6 (Extra)"] = "Barra de Ação 6 (Extra)",
    ["Grow from"] = "Crescer a partir de",
    ["Left edge (rightwards)"] = "Borda esquerda (para a direita)",
    ["Right edge (leftwards)"] = "Borda direita (para a esquerda)",
    ["Rows grow"] = "Fileiras crescem",
    ["Mouseover reveals all mouseover bars"] = "Passar o mouse revela todas as barras desse modo",
    ["Hovering ANY mouseover bar shows every bar set to mouseover at once."] = "Passar o mouse sobre QUALQUER barra desse modo exibe de uma vez todas as barras definidas como ao passar o mouse.",
    ["Button text styling"] = "Estilo do texto dos botões",
    ["|cffaaaaaaColours and fine offsets for the button texts, on every bar.|r"] = "|cffaaaaaaCores e ajustes finos de deslocamento para os textos dos botões, em todas as barras.|r",
    ["Keybind text colour"] = "Cor do texto do atalho",
    ["Macro text colour"] = "Cor do texto da macro",
    ["Count text colour"] = "Cor do texto da quantidade",
    ["Keybind offset X"] = "Deslocamento X do atalho",
    ["Keybind offset Y"] = "Deslocamento Y do atalho",
    ["Macro offset X"] = "Deslocamento X da macro",
    ["Macro offset Y"] = "Deslocamento Y da macro",
    ["Count offset X"] = "Deslocamento X da quantidade",
    ["Count offset Y"] = "Deslocamento Y da quantidade",
    ["0 = use the game's default size."] = "0 = usa o tamanho padrão do jogo.",
    ["Vertical layout"] = "Disposição vertical",
    ["Reverse order"] = "Ordem inversa",
    ["Hide keybind text"] = "Ocultar o texto do atalho",
    ["Hide macro text"] = "Ocultar o texto da macro",
    ["Game Menu"] = "Menu do Jogo",
    ["Game menu: VuloUI look"] = "Menu do jogo: visual do VuloUI",
    ["Restyles the Escape menu to match the addon look: dark panel, flat buttons, accent title. Changing this needs a /reload."] = "Reestiliza o menu Escape para combinar com o visual do addon: painel escuro, botões planos, título em destaque. Alterar isto exige um /reload.",
    ["Game menu: VuloClassicUI button"] = "Menu do jogo: botão do VuloClassicUI",
    ["Adds a VuloClassicUI button to the Escape menu that opens the options window. Turning this off needs a /reload."] = "Adiciona ao menu Escape um botão do VuloClassicUI que abre a janela de opções. Desativar isto exige um /reload.",
    ["Hide the FPS / latency bar"] = "Ocultar a barra de FPS / latência",
    ["Hides Blizzard's small green performance (FPS / latency) bar."] = "Oculta a pequena barra verde de desempenho (FPS / latência) da Blizzard.",
    ["Micro menu style"] = "Estilo do micromenu",
    ["World map"] = "Mapa-múndi",
    ["Friends list"] = "Lista de amigos",
    ["Group finder"] = "Localizador de grupos",
    ["Bag bar style"] = "Estilo da barra de mochilas",
    ["Key ring"] = "Chaveiro",
    ["Timer decimals below 10 seconds"] = "Decimais no cronômetro abaixo de 10 segundos",
    ["Interrupted by %s"] = "Interrompido por %s",
    ["Value + percent"] = "Valor + porcentagem",
    ["Value + percent layout"] = "Disposição de valor + porcentagem",
    ["Short values (12.3k)"] = "Valores curtos (12,3k)",
    ["Show percent sign"] = "Exibir o sinal de porcentagem",
    ["Smooth health changes"] = "Transição suave de vida",
    ["The bar glides to the new value; a bright trail marks health draining away."] = "A barra desliza até o novo valor; um rastro claro marca a vida que se esvai.",
    ["Tint background with bar colour"] = "Tingir o fundo com a cor da barra",
    ["The empty part of the bar shows a darkened shade of the bar colour instead of plain dark grey."] = "A parte vazia da barra exibe um tom escurecido da cor da barra em vez de cinza-escuro simples.",
    ["Glow at the bar edge"] = "Brilho na borda da barra",
    ["A soft glow rides the end of the fill, tinted in the bar's own colour. Also applies to the cast bar."] = "Um brilho suave acompanha o fim do preenchimento, tingido com a própria cor da barra. Também se aplica à barra de conjuração.",
    ["Edge glow width"] = "Largura do brilho da borda",
    ["Rounded bar corners"] = "Cantos arredondados da barra",
    ["Clips the fill and background to a rounded shape. The line border stays square, so a thin border may show slightly at the corners."] = "Recorta o preenchimento e o fundo em um formato arredondado. A borda em linha permanece quadrada, então uma borda fina pode aparecer levemente nos cantos.",
    ["Overall plate scale (%)"] = "Escala geral das placas (%)",
    ["Scales every plate at once, on top of each individual size."] = "Redimensiona todas as placas de uma vez, além do tamanho individual de cada uma.",
    ["Vertical offset"] = "Deslocamento vertical",
    ["Moves every plate up or down relative to its unit."] = "Move todas as placas para cima ou para baixo em relação à sua unidade.",
    ["Font outline"] = "Contorno da fonte",
    ["How plate text is lifted off the background."] = "Como o texto da placa se destaca do fundo.",
    ["Thick outline"] = "Contorno grosso",
    ["Show level"] = "Exibir o nível",
    ["Shows the unit level to the left of the name; ?? means the level is far above yours."] = "Exibe o nível da unidade à esquerda do nome; ?? significa que o nível está muito acima do seu.",
    ["Mark rare and elite"] = "Marcar raros e elites",
    ["Appends a rank to the level and turns it gold: + elite, R rare, R+ rare elite, B world boss."] = "Acrescenta uma classificação ao nível e o deixa dourado: + elite, R raro, R+ raro elite, B chefe mundial.",
    ["Level size"] = "Tamanho do nível",
    ["0 = uses the name size."] = "0 = usa o tamanho do nome.",
    ["Emphasise casting units"] = "Destacar unidades conjurando",
    ["While a unit casts, its plate grows a little and stays readable even when something else is targeted."] = "Enquanto uma unidade conjura, sua placa cresce um pouco e continua legível mesmo quando outra coisa está selecionada.",
    ["Casting scale (%)"] = "Escala ao conjurar (%)",
    ["Casting opacity (%)"] = "Opacidade ao conjurar (%)",
    ["Colour border by school"] = "Colorir a borda pela escola",
    ["Aura borders take the colour of their school: magic blue, curse purple, disease orange, poison green."] = "As bordas das auras assumem a cor de sua escola: magia azul, maldição roxa, doença laranja, veneno verde.",
    ["Flash before running out"] = "Piscar antes de acabar",
    ["The icon pulses over the last part of its duration, so you can see when to refresh."] = "O ícone pulsa na parte final de sua duração, para você ver quando renovar.",
    ["Flash below (%)"] = "Piscar abaixo de (%)",
    ["Your Own Debuffs"] = "Suas próprias penalidades",
    ["|cffaaaaaaA separate row for the harmful auras you cast yourself - your damage-over-time timers, kept away from everything else on the target.|r"] = "|cffaaaaaaUma fileira separada para as auras nocivas que você mesmo lança - seus cronômetros de dano ao longo do tempo, longe de tudo o mais no alvo.|r",
    ["Show your own debuffs (separate row)"] = "Exibir suas próprias penalidades (fileira separada)",
    ["Max icons"] = "Máximo de ícones",
    ["Icons per line"] = "Ícones por linha",
    ["0 = one line. Otherwise the row wraps after this many icons."] = "0 = uma linha. Caso contrário, a fileira quebra após esta quantidade de ícones.",
    ["Reminders"] = "Lembretes",
    ["|cffaaaaaaShows a short row of icons for what you are missing right now. Out of combat a click casts or uses the fix; hovering explains what it wants. The row holds still during combat.|r"] = "|cffaaaaaaExibe uma pequena fileira de ícones com o que está faltando agora. Fora de combate, um clique lança ou usa a solução; passar o mouse explica o que ele quer. A fileira fica parada durante o combate.|r",
    ["Also warn about empty equipment slots"] = "Avisar também sobre espaços de equipamento vazios",
    ["Off by default: a ring, trinket or cloak is often legitimately empty while levelling."] = "Desativado por padrão: um anel, berloque ou capa costuma estar legitimamente vazio enquanto você sobe de nível.",
    ["Shows what you are missing - class buffs, weapon enchants, food, stance, pet, ammo, durability, empty gear slots and unspent talent points."] = "Exibe o que está faltando - benefícios de classe, encantamentos de arma, comida, postura, mascote, munição, durabilidade, espaços de equipamento vazios e pontos de talento não gastos.",
    ["What to watch"] = "O que monitorar",
    ["Class buffs"] = "Benefícios de classe",
    ["Weapon enchants"] = "Encantamentos de arma",
    ["Stance and aura"] = "Postura e aura",
    ["Food and flask"] = "Comida e frasco",
    ["Ammo, durability, gear, talents"] = "Munição, durabilidade, equipamento, talentos",
    ["Most icons at once"] = "Máximo de ícones ao mesmo tempo",
    ["Anything past this is bundled into a single counter instead of adding another icon."] = "Tudo além disso é agrupado em um único contador em vez de adicionar outro ícone.",
    ["Show labels"] = "Exibir rótulos",
    ["Settle time (seconds)"] = "Tempo de espera (segundos)",
    ["How long something must stay missing before an icon appears. Stops it flickering between casts."] = "Por quanto tempo algo precisa ficar faltando antes de um ícone aparecer. Evita que ele pisque entre as conjurações.",
    ["Warn when under (seconds)"] = "Avisar quando faltar menos de (segundos)",
    ["Also warn while a buff or weapon enchant is about to run out. 0 = only warn when it is gone."] = "Avisa também enquanto um benefício ou encantamento de arma está prestes a acabar. 0 = avisar apenas quando já tiver acabado.",
    ["Durability below (%)"] = "Durabilidade abaixo de (%)",
    ["Ammo below"] = "Munição abaixo de",
    ["Quiet while resting"] = "Silêncio ao descansar",
    ["No reminders in a city or inn."] = "Sem lembretes em uma cidade ou estalagem.",
    ["Quiet while eating or drinking"] = "Silêncio ao comer ou beber",
    ["Click to cast."] = "Clique para conjurar.",
    ["Missing: %s"] = "Faltando: %s",
    ["Main hand"] = "Mão principal",
    ["Off hand"] = "Mão secundária",
    ["No weapon enchant: %s"] = "Sem encantamento de arma: %s",
    ["Weapon enchant running out: %s"] = "Encantamento de arma acabando: %s",
    ["Stance"] = "Postura",
    ["No stance active"] = "Nenhuma postura ativa",
    ["Aura"] = "Aura",
    ["No aura active"] = "Nenhuma aura ativa",
    ["Pet"] = "Mascote",
    ["No pet out"] = "Nenhum mascote invocado",
    ["Passive"] = "Passivo",
    ["Pet is set to passive"] = "O mascote está definido como passivo",
    ["Food"] = "Comida",
    ["Not well fed"] = "Sem Bem Alimentado",
    ["Flask"] = "Frasco",
    ["No flask or elixir"] = "Sem frasco ou elixir",
    ["Low ammo: %d left"] = "Pouca munição: restam %d",
    ["Equipment damaged: %d%% left"] = "Equipamento danificado: restam %d%%",
    ["Empty equipment slots: %d"] = "Espaços de equipamento vazios: %d",
    ["Unspent talent points: %d"] = "Pontos de talento não gastos: %d",
    ["Racials"] = "Raciais",
    ["Racial Cooldowns"] = "Tempos de recarga raciais",
    ["Shows the opponent's racial ability and its cooldown once they use it. These are this expansion's cooldowns, and no racial shares one with the PvP trinket yet."] = "Exibe a habilidade racial do oponente e seu tempo de recarga assim que ele a usa. Estes são os tempos de recarga desta expansão, e nenhuma racial ainda compartilha recarga com o berloque de JcJ.",
    ["Show racial cooldown"] = "Exibir o tempo de recarga racial",
    ["Shadow Sight"] = "Visão Sombria",
    ["Shadow Sight up"] = "Visão Sombria disponível",
    ["Shadow Sight up - next in %d s"] = "Visão Sombria disponível - próxima em %d s",
    ["Shadow Sight in %d s"] = "Visão Sombria em %d s",
    ["Counts down the arena orbs: the first pair appears 95 seconds after the gates open, and each one returns 122 seconds after it is taken."] = "Faz a contagem regressiva dos orbes da arena: o primeiro par surge 95 segundos após a abertura dos portões, e cada um retorna 122 segundos depois de ser pego.",
    ["Show Shadow Sight timer"] = "Exibir o cronômetro da Visão Sombria",
    ["Aura on the class icon"] = "Aura no ícone de classe",
    ["Puts the single most relevant aura on the opponent's class icon: an immunity outranks crowd control, which outranks a defensive, which outranks an offensive cooldown."] = "Coloca no ícone de classe do oponente a única aura mais relevante: uma imunidade supera o controle de multidão, que supera uma defensiva, que supera uma ofensiva.",
    ["Show aura on the class icon"] = "Exibir a aura no ícone de classe",
    ["Crowd control only"] = "Apenas controle de multidão",
    ["Dispels"] = "Dissipações",
    ["Dispel Cooldowns"] = "Tempos de recarga de dissipação",
    ["|cffaaaaaaMost dispels have no cooldown in this expansion, so only Mass Dispel and the felhunter's Devour Magic can ever show up here.|r"] = "|cffaaaaaaA maioria das dissipações não tem tempo de recarga nesta expansão, então apenas Dissipar em Massa e o Devorar Magia do caçador vil podem aparecer aqui.|r",
    ["Show dispel cooldown"] = "Exibir o tempo de recarga de dissipação",
    ["Range"] = "Alcance",
    ["Fades the frame while the opponent is out of reach, measured with a spell your class knows rather than a fixed distance."] = "Esmaece o quadro enquanto o oponente está fora de alcance, medido com uma magia que sua classe conhece em vez de uma distância fixa.",
    ["Fade out-of-range opponents"] = "Esmaecer oponentes fora de alcance",
    ["Discard changes and revert every window to the last save point, or to how it was when Edit Mode opened."] = "Descarta as alterações e reverte todas as janelas ao último ponto salvo, ou a como estavam quando o Modo de Edição foi aberto.",
    ["Discard all changes made since the last save?"] = "Descartar todas as alterações feitas desde o último salvamento?",
    ["Grey out when you walk out of range"] = "Esmaecer em cinza ao sair do alcance",
    ["Drains the colour while you are outside a totem's radius, and restores it when you step back in. Recognised from the buff the totem puts on you, so totems that grant no buff (Searing, Magma, Tremor, ...) always stay lit."] = "Drena a cor enquanto você está fora do raio de um totem e a restaura quando você volta. Reconhecido pelo benefício que o totem coloca em você, então totens que não concedem benefício (Chamuscante, Magma, Tremular, ...) permanecem sempre acesos.",
    ["Limit to"] = "Limitar a",
    ["Everything"] = "Tudo",
    ["Only mine"] = "Apenas as minhas",
    ["Only removable"] = "Apenas removíveis",
    ["Narrows this row to auras you cast yourself, or to ones that can be removed."] = "Restringe esta fileira às auras que você mesmo lança, ou às que podem ser removidas.",
    ["Nudges every aura row at once, on top of each row's own offset."] = "Ajusta todas as fileiras de auras de uma vez, além do deslocamento próprio de cada fileira.",
    ["Share of the remaining duration at which the pulse starts."] = "Fração da duração restante em que o pulso começa.",
    ["Own colour while your interrupt is ready"] = "Cor própria quando sua interrupção está pronta",
    ["Interruptible casts paint in this colour while your interrupt is off cooldown — kick at will."] = "Conjurações interrompíveis são pintadas nesta cor enquanto sua interrupção está fora da recarga — chute à vontade.",
    ["Interrupt-ready colour"] = "Cor de interrupção pronta",
    ["Own colour while channelling"] = "Cor própria ao canalizar",
    ["Channel colour"] = "Cor da canalização",
    ["Own colour when the cast targets YOU"] = "Cor própria quando a conjuração mira em VOCÊ",
    ["The bar turns this colour while the caster's target is you."] = "A barra assume esta cor enquanto o alvo do conjurador é você.",
    ["Targets-you colour"] = "Cor de mira em você",
    ["Show who interrupted"] = "Exibir quem interrompeu",
    ["The interrupt flash shows the name of whoever landed the interrupt."] = "O clarão de interrupção exibe o nome de quem realizou a interrupção.",
    ["On: 9.9, 3.4 … Off: whole seconds (9, 3)."] = "Ativado: 9,9, 3,4 … Desativado: segundos inteiros (9, 3).",
    ["Modern puts the real bag buttons on a flat dark strip in the VuloUI look — opening, swapping and tooltips stay identical."] = "O estilo Moderno coloca os botões reais de mochila em uma faixa escura e plana com o visual do VuloUI — abrir, trocar e as dicas continuam idênticos.",
    ["Modern replaces Blizzard's buttons with a flat dark icon strip in the VuloUI look. Clicks and tooltips stay identical."] = "O estilo Moderno substitui os botões da Blizzard por uma faixa de ícones escura e plana com o visual do VuloUI. Os cliques e as dicas continuam idênticos.",
    ["Classic (Blizzard buttons)"] = "Clássico (botões da Blizzard)",
    ["Modern (flat icon strip)"] = "Moderno (faixa de ícones plana)",
    ["Hides the row of menu buttons (character, spellbook, …)."] = "Oculta a fileira de botões do menu (personagem, grimório, …).",
    ["Hide the bag bar"] = "Ocultar a barra de mochilas",
    ["Hides the backpack and bag slots."] = "Oculta a mochila principal e os demais espaços de mochila.",
    ["|cff9b6cffThe micro menu, bag bar, FPS/latency bar and the XP bar below are movable in Edit Mode (/vedit) like the action bars.|r"] = "|cff9b6cffO micromenu, a barra de mochilas, a barra de FPS/latência e a barra de XP abaixo podem ser movidos no Modo de Edição (/vedit), como as barras de ação.|r",
    ["Micro menu"] = "Micromenu",
    ["Bag bar"] = "Barra de mochilas",
    ["FPS / latency bar"] = "Barra de FPS / latência",
    ["XP bar"] = "Barra de XP",
    ["Show a custom XP bar"] = "Exibir uma barra de XP personalizada",
    ["Colour"] = "Cor",
    ["Bar opacity"] = "Opacidade da barra",
    ["Show empty buttons"] = "Exibir botões vazios",
    ["Off hides empty slots; they reappear automatically while you drag an ability."] = "Desativado oculta os espaços vazios; eles reaparecem automaticamente enquanto você arrasta uma habilidade.",
    ["Click through"] = "Clique atravessa",
    ["The bar ignores the mouse entirely — clicks go through it. Keybinds still work."] = "A barra ignora completamente o mouse — os cliques passam através dela. Os atalhos continuam funcionando.",
    ["Keybind text size"] = "Tamanho do texto do atalho",
    ["Macro text size"] = "Tamanho do texto da macro",
    ["Count text size"] = "Tamanho do texto da quantidade",
    ["Cooldown text size"] = "Tamanho do texto da recarga",
    ["0 = default size."] = "0 = tamanho padrão.",
    ["0 = default size. Requires cooldown numbers to be enabled in the game options."] = "0 = tamanho padrão. Requer que os números de recarga estejam ativados nas opções do jogo.",
    ["Cooldown & look"] = "Recarga e aparência",
    ["|cffff5555Quick keybind mode is not available on this client.|r"] = "|cffff5555O modo de atalho rápido não está disponível neste cliente.|r",
    ["Modifier paging"] = "Paginação por modificador",
    ["Click: open these settings"] = "Clique: abrir estas configurações",
    ["Crowd Control"] = "Controle de Multidão",
    ["Addon font (default)"] = "Fonte do addon (padrão)",
    ["The typeface for every text on the plates (name, health, cast, auras)."] = "A tipografia de todos os textos das placas (nome, vida, conjuração, auras).",
    ["Health text size"] = "Tamanho do texto de vida",
    ["0 = uses the general text size."] = "0 = usa o tamanho geral do texto.",
    ["Cast text size"] = "Tamanho do texto de conjuração",
    ["Cast background colour"] = "Cor do fundo da conjuração",
    ["Cast background opacity"] = "Opacidade do fundo da conjuração",
    ["0 = uses the global background opacity."] = "0 = usa a opacidade global do fundo.",
    ["Icon scale"] = "Escala do ícone",
    ["Icon on the right"] = "Ícone à direita",
    ["Icon offset X"] = "Deslocamento X do ícone",
    ["Icon offset Y"] = "Deslocamento Y do ícone",
    ["Shield on uninterruptible casts"] = "Escudo em conjurações ininterrompíveis",
    ["Tick where your interrupt becomes ready"] = "Marca onde sua interrupção fica pronta",
    ["Marks the spot on the enemy cast bar where YOUR interrupt comes off cooldown — everything after the tick is kickable."] = "Marca o ponto na barra de conjuração inimiga em que SUA interrupção sai da recarga — tudo depois da marca é interrompível.",
    ["Tick colour"] = "Cor da marca",
    ["Flash when a cast is interrupted"] = "Piscar quando uma conjuração é interrompida",
    ["Flash colour"] = "Cor do clarão",
    ["Cast text colour"] = "Cor do texto de conjuração",
    ["Timer side"] = "Lado do cronômetro",
    ["Timer colour"] = "Cor do cronômetro",
    ["Hide name while casting"] = "Ocultar o nome ao conjurar",
    ["Cast timer size"] = "Tamanho do cronômetro de conjuração",
    ["NPC title size"] = "Tamanho do título do NPC",
    ["0 = slightly smaller than the name."] = "0 = um pouco menor que o nome.",
    ["CC icon width"] = "Largura do ícone de controle",
    ["CC icon height"] = "Altura do ícone de controle",
    ["0 = square (uses the icon size)."] = "0 = quadrado (usa o tamanho do ícone).",
    ["Cast bar width"] = "Largura da barra de conjuração",
    ["0 = match the health bar width."] = "0 = igual à largura da barra de vida.",
    ["Name offset X"] = "Deslocamento X do nome",
    ["Name offset Y"] = "Deslocamento Y do nome",
