    ["Diamond"] = "Losango",
    ["Triangle"] = "Triângulo",
    ["Below the bar"] = "Abaixo da barra",
    ["Above the bar"] = "Acima da barra",
    ["Execute line"] = "Linha de execução",
    ["A thin marker line on the bar at the chosen health percentage (e.g. 20 for Execute)."] = "Uma linha marcadora fina na barra na porcentagem de vida escolhida (ex.: 20 para Executar).",
    ["Execute line only on your target"] = "Linha de execução apenas no seu alvo",
    ["Execute line colour"] = "Cor da linha de execução",
    ["Execute line percent"] = "Porcentagem da linha de execução",
    ["Show remaining cast time"] = "Exibir o tempo restante de conjuração",
    ["Own colour while your interrupt is on cooldown"] = "Cor própria quando sua interrupção está em recarga",
    ["Interruptible casts paint differently while YOUR interrupt ability is still on cooldown — you see at a glance whether kicking is even possible."] = "Conjurações interrompíveis são pintadas de forma diferente enquanto SUA habilidade de interrupção ainda está em recarga — você vê de relance se dá para interromper.",
    ["Interrupt-on-cooldown colour"] = "Cor de interrupção em recarga",
    ["Own bar colour on your target"] = "Cor própria da barra no seu alvo",
    ["Your current target's health bar uses this colour instead of reaction / class / threat colours."] = "A barra de vida do seu alvo atual usa esta cor em vez das cores de reação / classe / ameaça.",
    ["Target bar colour"] = "Cor da barra do alvo",
    ["Mouseover highlight"] = "Destaque ao passar o mouse",
    ["Lightens the health bar of the plate under your mouse cursor."] = "Clareia a barra de vida da placa sob o cursor do mouse.",
    ["Target plate scale"] = "Escala da placa do alvo",
    ["Your target's plate is drawn this much larger (100 = off)."] = "A placa do seu alvo é desenhada com este tamanho a mais (100 = desativado).",
    ["Behaviour"] = "Comportamento",
    ["|cffaaaaaaThese are the game's own nameplate settings, changed live (not part of the profile). Not changeable in combat.|r"] = "|cffaaaaaaEstas são as próprias configurações de placa de nome do jogo, alteradas ao vivo (não fazem parte do perfil). Não podem ser alteradas em combate.|r",
    ["Plate motion"] = "Movimento das placas",
    ["Overlapping"] = "Sobreposto",
    ["Stacking"] = "Empilhado",
    ["Stacked spacing"] = "Espaçamento do empilhamento",
    ["Vertical distance between stacked plates (a tenth of the game value)."] = "Distância vertical entre placas empilhadas (um décimo do valor do jogo).",
    ["Line-of-sight opacity"] = "Opacidade fora da linha de visão",
    ["Opacity of plates whose unit is out of your line of sight."] = "Opacidade das placas cuja unidade está fora da sua linha de visão.",
    ["Plate view distance"] = "Distância de visão das placas",
    ["|cffaaaaaaWhile the key is held (or your target matches), the main bar shows the chosen bar's abilities instead. Fully secure — works in combat.|r"] = "|cffaaaaaaEnquanto a tecla estiver pressionada (ou seu alvo corresponder), a barra principal exibe as habilidades da barra escolhida. Totalmente seguro — funciona em combate.|r",
    ["Shift held"] = "Shift pressionado",
    ["Ctrl held"] = "Ctrl pressionado",
    ["Alt held"] = "Alt pressionado",
    ["Friendly target"] = "Alvo amigável",
    ["Hostile target"] = "Alvo hostil",
    ["Group visibility"] = "Visibilidade de grupo",
    ["Always"] = "Sempre",
    ["Only in a group"] = "Apenas em grupo ou raide",
    ["Only in a party"] = "Apenas em grupo (não raide)",
    ["Only solo"] = "Apenas sozinho",
    ["Hide when mounted"] = "Ocultar ao montar",
    ["Hide without target"] = "Ocultar sem alvo",
    ["Hide without enemy target"] = "Ocultar sem alvo inimigo",
    ["Quick keybind mode (/vkb)"] = "Modo de atalho rápido (/vkb)",
    ["Hover an action button and press a key to bind it. Hidden bars are shown while binding."] = "Passe o mouse sobre um botão de ação e pressione uma tecla para vinculá-la. As barras ocultas ficam visíveis durante a vinculação.",
    ["Swipe colour"] = "Cor da varredura",
    ["Icon opacity on cooldown"] = "Opacidade do ícone em recarga",
    ["Dims the whole icon while the ability is on cooldown (100 = off)."] = "Escurece o ícone inteiro enquanto a habilidade está em recarga (100 = desativado).",
    ["Show cooldown numbers"] = "Exibir os números de recarga",
    ["The game's own countdown numbers on cooldowns (a game setting, changed live)."] = "Os próprios números de contagem regressiva do jogo nas recargas (uma configuração do jogo, alterada ao vivo).",
    ["|cffaaaaaaApplies to every action bar.|r"] = "|cffaaaaaaAplica-se a todas as barras de ação.|r",
    ["Cooldown swipe opacity"] = "Opacidade da varredura de recarga",
    ["How dark the cooldown sweep overlay is (0 = invisible)."] = "Quão escura é a sobreposição da varredura de recarga (0 = invisível).",
    ["Desaturate icons on cooldown"] = "Dessaturar ícones em recarga",
    ["Out-of-range colouring"] = "Coloração fora de alcance",
    ["Tints the whole icon while your target is out of range."] = "Tinge o ícone inteiro enquanto seu alvo está fora de alcance.",
    ["Tooltips"] = "Dicas",
    ["Hide in combat"] = "Ocultar em combate",
    ["Hide always"] = "Ocultar sempre",
    ["A movable, resizable experience bar with rested overlay. Hidden at max level. Replaces Blizzard's bar while on."] = "Uma barra de experiência móvel e redimensionável com sobreposição de descanso. Oculta no nível máximo. Substitui a barra da Blizzard quando ativada.",
    ["Hide Blizzard's XP / reputation bar"] = "Ocultar a barra de XP / reputação da Blizzard",
    ["Removes the leftover blue experience / reputation bar under the action bar."] = "Remove a barra azul remanescente de experiência / reputação abaixo da barra de ação.",
    ["Stance bar"] = "Barra de postura",
    ["Pet bar"] = "Barra do mascote",
    ["Takes over every action bar with its own movable frames: real combat/mouseover show-hide, scale and grid layout per bar, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. EXPERIMENTAL — test ability clicks and paging in combat; /reload after disabling."] = "Assume todas as barras de ação com quadros móveis próprios: exibição/ocultação real em combate/ao passar o mouse, escala e disposição em grade por barra, paginação correta da barra principal (formas de druida/ladino/guerreiro/sacerdote) e seus atalhos. EXPERIMENTAL — teste os cliques de habilidade e a paginação em combate; use /reload após desativar.",
    ["Standard action bars are back. Reload the interface to restore every last piece of the default layout."] = "As barras de ação padrão voltaram. Recarregar a interface restaura até o último detalhe do layout padrão.",
    ["Buttons per row"] = "Botões por fileira",
    ["Button spacing"] = "Espaçamento dos botões",
    ["Reset ALL VuloClassicUI settings for every character on this account? This cannot be undone."] = "Redefinir TODAS as configurações do VuloClassicUI para todos os personagens desta conta? Esta ação não pode ser desfeita.",
    ["Swing Timer switched off: it only tracks melee auto-attacks, which this character's talents do not use."] = "Temporizador de Golpe desativado: ele só acompanha os ataques automáticos corpo a corpo, que os talentos deste personagem não usam.",
    ["|cffff5555Settings migration %s failed:|r %s"] = "|cffff5555Falha na migração de configurações %s:|r %s",
    ["Plays a raid warning sound the moment an opponent uses their PvP trinket."] = "Toca um som de aviso de raide assim que um oponente usa seu berloque PvP.",
    ["Flashes the icon briefly when an opponent uses their PvP trinket."] = "Faz o ícone piscar brevemente quando um oponente usa seu berloque PvP.",
    ["Icon gap"] = "Espaço do ícone",
    ["Distance between the icon and the bar."] = "Distância entre o ícone e a barra.",
    ["Accent colour"] = "Cor de destaque",
    ["Used for the bar while the fill mode is not a texture, and for channelled casts on Blizzard's own castbar."] = "Usada na barra enquanto o modo de preenchimento não for uma textura, e nas conjurações canalizadas na barra da Blizzard.",
    ["Cast finished"] = "Conjuração concluída",
    ["The bar flashes in this colour when a cast completes."] = "A barra pisca nesta cor quando uma conjuração termina.",
    ["Cast interrupted"] = "Conjuração interrompida",
    ["The bar flashes in this colour when a cast is interrupted or fails."] = "A barra pisca nesta cor quando uma conjuração é interrompida ou falha.",
    ["Fade-in time"] = "Tempo de surgimento",
    ["How long an icon takes to appear. 0 makes it show instantly."] = "Quanto tempo um ícone leva para aparecer. 0 o mostra na hora.",
    [" and %d item(s)"] = " e %d item(ns)",
    ["/vlfg toggles the group board."] = "/vlfg abre ou fecha o quadro de grupos.",
    ["Auto-apply a lure when the pole has none"] = "Aplicar isca automaticamente quando a vara não tiver",
    ["Auto-equip a fishing pole if none is worn"] = "Equipar uma vara de pesca automaticamente se nenhuma estiver equipada",
    ["Auto-loot while fishing"] = "Saque automático enquanto pesca",
    ["Bags are full — some items were left in the mail."] = "Bolsas cheias — alguns itens ficaram no correio.",
    ["Boost fishing sound (hear the bite clearly)"] = "Reforçar o som da pesca (ouvir a fisgada com clareza)",
    ["Burning Crusade Dungeons"] = "Masmorras de Burning Crusade",
    ["Burning Crusade Raids"] = "Raides de Burning Crusade",
    ["Can't change the fishing key in combat."] = "Não dá para mudar a tecla de pesca em combate.",
    ["Classic Dungeons"] = "Masmorras de Classic",
    ["Classic Raids"] = "Raides de Classic",
    ["Clear key"] = "Limpar tecla",
    ["Extra items & macros"] = "Itens e macros extras",
    ["Fishing key cleared."] = "Tecla de pesca limpa.",
    ["Fishing key set to: %s"] = "Tecla de pesca definida como: %s",
    ["Fishing key: %s  —  click to change"] = "Tecla de pesca: %s  —  clique para mudar",
    ["Fishing sound volume"] = "Volume do som da pesca",
    ["Friends"] = "Amigos",
    ["Guild"] = "Guilda",
    ["H"] = "H",
    ["Hide the reel error spam while fishing"] = "Ocultar os erros de recolhimento enquanto pesca",
    ["In Progress"] = "Em andamento",
    ["Invite"] = "Convidar",
    ["Keep requests for (minutes)"] = "Manter os pedidos por (minutos)",
    ["Keep sound audible when the game is in the background"] = "Manter o som audível com o jogo em segundo plano",
    ["Keep this many bag slots free"] = "Deixar esta quantidade de espaços livres na bolsa",
    ["Mail emptied: looted %s%s."] = "Correio esvaziado: %s%s recolhido.",
    ["No contacts yet"] = "Ainda sem contatos",
    ["No groups forming right now."] = "Ninguém está formando grupo no momento.",
    ["One-key reel (soft-target interact)"] = "Recolher com uma tecla (interação de alvo suave)",
    ["Open All"] = "Abrir tudo",
    ["Press the key for fishing  (ESC to cancel)"] = "Pressione a tecla para pescar  (ESC para cancelar)",
    ["Print a looted summary"] = "Exibir um resumo do saque",
    ["Recently mailed"] = "Enviados recentemente",
    ["Recipient dropdown on the Send tab"] = "Menu de destinatários na aba Enviar",
    ["Scan guild chat"] = "Analisar o bate-papo da guilda",
    ["Scan say / yell"] = "Analisar dizer e gritar",
    ["Scan world / trade / LFG channels"] = "Analisar os canais mundo, comércio e procurar grupo",
    ["Set fishing key"] = "Definir tecla de pesca",
    ["Slot %d"] = "Espaço %d",
    ["Speed (seconds between actions)"] = "Velocidade (segundos entre ações)",
    ["Take item attachments"] = "Pegar os itens anexados",
    ["Take money"] = "Pegar o dinheiro",
    ["While the bobber is out, maxes effect + master volume and dims music/ambience so the splash is easy to hear. Restored when you reel in."] = "Enquanto a boia está na água, o volume de efeitos e o geral vão ao máximo e a música e o ambiente baixam, para ouvir bem o splash. Restaurado ao recolher.",
    ["While the bobber is out, the same key interacts with it to reel in. Needs soft-target interaction, which is enabled only while fishing and restored afterwards."] = "Enquanto a boia está na água, a mesma tecla interage com ela para recolher. Precisa da interação de alvo suave, ativada só durante a pesca e restaurada depois.",
    ["Whisper"] = "Sussurrar",
    ["Who"] = "Quem",
    ["Your characters"] = "Seus personagens",
    ["now"] = "agora",
    ["|cffaaaaaaAdds an 'Open All' button to the mailbox. It takes every attachment and coin, skipping CoD and GM mail. Shift-click the button to ignore the filters and take everything.|r"] = "|cffaaaaaaAdiciona um botão «Abrir tudo» à caixa de correio. Ele pega todos os anexos e moedas, pulando encomendas com cobrança e correio de MJ. Shift+clique no botão para ignorar os filtros e pegar tudo.|r",
    ["|cffaaaaaaItems or macros also used by the key while fishing — only when ready (off cooldown, buff missing, conditions met), then it goes back to casting. Type an item name or ID, shift-click an item into the box, or paste a /macro.|r"] = "|cffaaaaaaItens ou macros que a tecla também usa enquanto pesca — só quando estão prontos (fora da recarga, sem o benefício, condições atendidas), depois volta a lançar. Digite o nome ou o ID de um item, Shift+clique para inserir um item, ou cole uma /macro.|r",
    ["|cffaaaaaaOne key does it all: cast, reel in, and apply a lure — then auto-loots. Set a key below, face some water, and press it.|r"] = "|cffaaaaaaUma tecla faz tudo: lançar, recolher e aplicar isca — depois saqueia sozinho. Defina uma tecla abaixo, vire-se para a água e pressione.|r",
    ["|cffff5555Arena submodule OnDisable error:|r %s"] = "|cffff5555Erro em OnDisable do submódulo de Arena:|r %s",
    -- Patch notes, module descriptions, anchors, embedded engine (sweep 2026-07)
    ["Languages"] = "Idiomas",
    ["Reminders (new module)"] = "Lembretes (novo módulo)",
    ["Arena"] = "Arena",
    ["Totems"] = "Totens",
    ["Fixes"] = "Correções",
    ["Resource Bar"] = "Barra de Recurso",
    ["Settings Window"] = "Janela de Configurações",
    ["Character Window"] = "Janela do Personagem",
    ["Nameplates (German: Namensplaketten)"] = "Placas de Nome (em alemão: Namensplaketten)",
    ["German client"] = "Cliente alemão",
    ["Performance"] = "Desempenho",
    ["Equipment Sets"] = "Conjuntos de Equipamento",
    ["Spanish, French, Italian, Portuguese, Russian and Korean. All six are complete — every one of the 2244 texts is translated, nothing falls back to English. Spanish also serves Latin American clients. Choose your language under General, or leave it on Auto."] = "Espanhol, francês, italiano, português, russo e coreano. Todos os seis estão completos — cada um dos 2244 textos está traduzido, nada recai para o inglês. O espanhol também atende os clientes latino-americanos. Escolha seu idioma em Geral, ou deixe em Auto.",
    ["Shows what you are missing before a pull: weapon oils and stones, blessings, food and flask buffs, the aura or stance you forgot to set. Click a reminder to cast or use it. Off by default, found under Quality of Life."] = "Mostra o que está faltando antes de um pull: óleos e pedras de arma, bênçãos, benefícios de comida e frasco, a aura ou postura que você esqueceu de ativar. Clique em um lembrete para conjurá-lo ou usá-lo. Desligado por padrão, encontrado em Qualidade de Vida.",
    ["A spark at the bar's fill point, rounded corners, aura rows you can assign freely, and your own damage-over-time effects on a row of their own."] = "Uma faísca no ponto de preenchimento da barra, cantos arredondados, linhas de auras que você pode atribuir livremente e seus próprios efeitos de dano ao longo do tempo em uma linha só deles.",
    ["Aura borders take the colour of their spell school, and an aura flashes shortly before it runs out."] = "As bordas das auras assumem a cor da escola de magia, e uma aura pisca pouco antes de acabar.",
    ["Level and elite text, plus overall scale and vertical offset per plate."] = "Texto de nível e de elite, além de escala geral e deslocamento vertical por placa.",
    ["A window can take its width or height from another window and keep it."] = "Uma janela pode copiar a largura ou a altura de outra janela e mantê-la.",
    ["Save button. While dragging, hold Shift to lock one axis."] = "Botão de salvar. Ao arrastar, segure Shift para travar um eixo.",
    ["Trinket and racial cooldowns, Shadow Sight timer, a ring on the class icon for the most important aura, and range checking."] = "Recargas de berloques e raciais, temporizador de Visão das Sombras, um anel no ícone de classe para a aura mais importante e verificação de alcance.",
    ["Totem icons grey out once you leave the totem's range and regain their colour when you come back."] = "Os ícones de totem ficam acinzentados quando você sai do alcance do totem e recuperam a cor quando você volta.",
    ["The character sheet and spellbook open in combat again. The action bars no longer set a protected field from our own code, which was the real cause."] = "A ficha do personagem e o livro de magias abrem em combate novamente. As barras de ação não definem mais um campo protegido a partir do nosso próprio código, que era a causa real.",
    ["The melee swing timer is off by default and only loads for melee classes and specialisations."] = "O temporizador de golpe corpo a corpo vem desligado por padrão e só carrega para classes e especializações corpo a corpo.",
    ["Sliders got a proper look: soft edges, an inner shadow and a smoother hover."] = "Os controles deslizantes ganharam um visual decente: bordas suaves, uma sombra interna e um destaque mais suave ao passar o mouse.",
    ["Own icons for the three collection pages, and class icons on the class tabs."] = "Ícones próprios para as três páginas de coleção e ícones de classe nas abas de classe.",
    ["Anchor a window to another one's edge (left/right/top/bottom) — the gap is kept edge-to-edge, so it survives either window being resized."] = "Ancore uma janela à borda de outra (esquerda/direita/topo/base) — o espaçamento é mantido de borda a borda, então sobrevive ao redimensionamento de qualquer uma delas.",
    ["Click-to-anchor: press \"Anchor to window...\" in a window's panel, then click the target window. Loop and self-anchor are blocked."] = "Ancoragem por clique: pressione “Ancorar à janela...” no painel de uma janela e depois clique na janela alvo. Laços e ancoragem em si mesma são bloqueados.",
    ["While dragging, alignment lines now also show the pixel distance to the window you line up with."] = "Ao arrastar, as linhas de alinhamento agora também mostram a distância em pixels até a janela com a qual você se alinha.",
    ["Discard button — snapshots the layout when you open Edit Mode and restores it (positions, scale, anchors and links) if you discard."] = "Botão Descartar — captura o layout quando você abre o Modo de Edição e o restaura (posições, escala, ancoragens e vínculos) se você descartar.",
    ["The drag area now covers the whole dark chat panel down to the edit box, not just the narrow message strip."] = "A área de arrastar agora cobre todo o painel escuro do bate-papo até a linha de digitação, não só a faixa estreita de mensagens.",
    ["Fixed right-click on the chat window not opening its settings panel in Edit Mode."] = "Corrigido o clique direito na janela de bate-papo que não abria seu painel de configurações no Modo de Edição.",
    ["Interrupt help on the cast bar: own colours while your interrupt is on cooldown or ready, a tick marking where it comes back mid-cast, a shield on uninterruptible casts and an interrupt flash that can show who landed the kick."] = "Ajuda de interrupção na barra de conjuração: cores próprias enquanto sua interrupção está em recarga ou pronta, uma marca indicando onde ela volta no meio da conjuração, um escudo em conjurações não interrompíveis e um lampejo de interrupção que pode mostrar quem acertou a interrupção.",
    ["Cast bar suite: icon side and scale, remaining time, own background, channel colour, a warning colour when the cast aims at YOU — and on your target the cast bar lines up flush with the health bar including its border."] = "Conjunto da barra de conjuração: lado e escala do ícone, tempo restante, fundo próprio, cor de canalização, uma cor de alerta quando a conjuração mira em VOCÊ — e no seu alvo a barra de conjuração se alinha rente à barra de vida, incluindo a borda.",
    ["Execute line, target and mouseover effects, crowd control section, combo point shapes and placement, per-element position, size and text-size controls plus a font picker."] = "Linha de execução, efeitos de alvo e de passar o mouse, seção de controle de multidão, formas e posicionamento dos pontos de combo, controles de posição, tamanho e tamanho de texto por elemento, além de um seletor de fonte.",
    ["The options page carries a clickable live preview that stays pinned while you scroll — click any element to jump to its settings."] = "A página de opções traz uma prévia ao vivo clicável que permanece fixada enquanto você rola — clique em qualquer elemento para ir às configurações dele.",
    ["Smooth health movement with a damage trail, value plus percent text layouts with short numbers, and a decimal toggle for aura timers."] = "Movimento suave da vida com um rastro de dano, formatos de texto de valor e porcentagem com números curtos, e uma opção de decimais para os temporizadores de auras.",
    ["Per-bar visibility conditions (instances, mounted, target, group), modifier paging, quick keybind mode (/vkb), a sixth bar, growth directions, button text styling and cooldown look options."] = "Condições de visibilidade por barra (instâncias, montado, alvo, grupo), troca de página por modificador, modo rápido de atalhos (/vkb), uma sexta barra, direções de crescimento, estilo do texto dos botões e opções de aparência das recargas.",
    ["Micro menu and bag bar modern style: flat dark strips with an own monochrome icon set, plus world map, friends list, group finder, shop and key ring buttons."] = "Estilo moderno do micromenu e da barra de mochilas: faixas escuras e chapadas com um conjunto próprio de ícones monocromáticos, além de botões de mapa-múndi, lista de amigos, busca de grupos, loja e chaveiro.",
    ["The experience bar width now adjusts in single steps."] = "A largura da barra de experiência agora se ajusta em passos de um em um.",
    ["Visibility conditions, colour modes with gradient, background and border colours, smooth value changes, hash marks and threshold colouring."] = "Condições de visibilidade, modos de cor com gradiente, cores de fundo e de borda, mudanças suaves de valor, marcas de divisão e coloração por limite.",
    ["Character sheet stats panel no longer bleeds into other tabs; loadout sidebar aligns with the modern character sheet."] = "O painel de atributos da ficha do personagem não vaza mais para outras abas; a barra lateral de conjuntos se alinha com a ficha do personagem moderna.",
    ["Arena points calculator panel and button wear the addon look and dock beside the character sheet."] = "O painel e o botão da calculadora de pontos de arena usam o visual do addon e se encaixam ao lado da ficha do personagem.",
    ["The Escape menu now wears the dark addon look — flat buttons, accent title — and gains a VuloClassicUI button that opens the options window. Both have their own toggles under General."] = "O menu de Escape agora usa o visual escuro do addon — botões chapados, título com cor de destaque — e ganha um botão VuloClassicUI que abre a janela de opções. Ambos têm suas próprias opções em Geral.",
    ["The add friend dialog is skinned to match: dark panel, accent headline, dark input field and flat buttons."] = "A caixa de diálogo de adicionar amigo recebe o mesmo visual: painel escuro, título com cor de destaque, campo de digitação escuro e botões chapados.",
    ["Guild roster column header hover and click no longer stick out past the flat header row."] = "O destaque e o clique nos cabeçalhos das colunas da lista de membros da guilda não ultrapassam mais a linha chapada de cabeçalho.",
    ["The combat log filter bar now shares the exact width and height of the chat tab row, flush with the panel edge."] = "A barra de filtros do registro de combate agora tem exatamente a mesma largura e altura da fileira de abas do bate-papo, rente à borda do painel.",
    ["After an update, a pulsing dot on the \"Patch Notes\" entry points at the new notes until you open them once — account wide, per version."] = "Após uma atualização, um ponto pulsante na entrada “Notas de Atualização” aponta para as novas notas até você abri-las uma vez — para a conta toda, por versão.",
    ["With the Modern style, the equipment set sidebar now docks to the right of the stats panel at exactly the window's height, instead of overlapping it. Switching styles with the window open moves it immediately."] = "Com o estilo Moderno, a barra lateral de conjuntos de equipamento agora se encaixa à direita do painel de atributos exatamente na altura da janela, em vez de sobrepô-lo. Trocar de estilo com a janela aberta a move imediatamente.",
    ["Micro menu buttons that the game hides situationally are shown again, so the row no longer has a gap."] = "Os botões do micromenu que o jogo oculta em certas situações voltam a ser mostrados, então a fileira não fica mais com um buraco.",
    ["The default nameplate no longer shows through as a faint transparent bar under the custom plate — it is now hidden outright and kept hidden while the custom plate is active."] = "A placa de nome padrão não aparece mais como uma barra transparente e fraca sob a placa personalizada — agora ela é ocultada de vez e mantida oculta enquanto a placa personalizada está ativa.",
    ["All micro menu buttons open their windows again — the emptied default micro menu shell was invisibly swallowing clicks on the relocated buttons."] = "Todos os botões do micromenu abrem suas janelas novamente — a estrutura esvaziada do micromenu padrão estava engolindo invisivelmente os cliques nos botões realocados.",
    ["Fixed a blocked-action error when the stance bar updated during combat; stance button visibility now only changes out of combat, while icon tint, cooldown and the active marker keep updating live."] = "Corrigido um erro de ação bloqueada quando a barra de posturas se atualizava durante o combate; a visibilidade dos botões de postura agora só muda fora de combate, enquanto a tonalidade do ícone, a recarga e o marcador de ativo continuam se atualizando ao vivo.",
    ["An Action Bars module puts every action bar on its own movable frame — action bars 1 to 5, the stance bar and the pet bar — each placed and scaled in Edit Mode and configured on its own."] = "Um módulo de Barras de Ação coloca cada barra de ação em seu próprio quadro móvel — barras de ação 1 a 5, a barra de posturas e a barra do mascote — cada uma posicionada e escalada no Modo de Edição e configurada individualmente.",
    ["The main bar pages correctly with druid, rogue, warrior and priest forms, and your keybinds keep working on every bar, with the key shown on the buttons."] = "A barra principal troca de página corretamente com as formas de druida, ladino, guerreiro e sacerdote, e seus atalhos continuam funcionando em todas as barras, com a tecla exibida nos botões.",
    ["Per bar: visibility (always, mouseover, in or out of combat), opacity, icon size, buttons per row, spacing, vertical layout, reverse order, and hiding the keybind or macro text — with adjustable text sizes for keybind, macro, count and cooldown numbers."] = "Por barra: visibilidade (sempre, ao passar o mouse, dentro ou fora de combate), opacidade, tamanho dos ícones, botões por fileira, espaçamento, disposição vertical, ordem invertida e ocultação do texto de atalho ou de macro — com tamanhos de texto ajustáveis para os números de atalho, macro, quantidade e recarga.",
    ["Empty slots can be hidden and reappear automatically while you drag an ability onto the bar, and a bar can be made click-through."] = "Os espaços vazios podem ser ocultados e reaparecem automaticamente enquanto você arrasta uma habilidade para a barra, e uma barra pode ser atravessável por cliques.",
    ["Cooldown and look settings for all bars: cooldown sweep darkness, desaturating icons on cooldown, colouring icons while the target is out of range, and hiding button tooltips always or only in combat."] = "Configurações de recarga e aparência para todas as barras: escuridão da varredura de recarga, dessaturar ícones em recarga, colorir ícones enquanto o alvo está fora de alcance e ocultar as dicas dos botões sempre ou só em combate.",
    ["An own experience bar with adjustable width, height and colour, rested overlay and progress text — it replaces the default bar while enabled and hides at the level cap."] = "Uma barra de experiência própria com largura, altura e cor ajustáveis, sobreposição de descanso e texto de progresso — ela substitui a barra padrão enquanto ativada e se oculta no nível máximo.",
    ["The micro menu, the bag bar and the performance bar sit on movable holders, and each of them can be hidden — as can the default experience bar."] = "O micromenu, a barra de mochilas e a barra de desempenho ficam em suportes móveis, e cada um deles pode ser ocultado — assim como a barra de experiência padrão.",
    ["Off by default: the standard bars stay untouched until you enable the module, and disabling hands everything back (a reload fully restores the default bars)."] = "Desligado por padrão: as barras padrão permanecem intactas até você ativar o módulo, e desativá-lo devolve tudo (um reload restaura totalmente as barras padrão).",
    ["The dark button skin now also covers the new action-bar buttons."] = "O visual escuro de botões agora também cobre os novos botões das barras de ação.",
    ["A custom Nameplates module draws its own health bar, cast bar, name and health text over enemy and NPC nameplates — fully configurable, with a live preview that updates as you change each option."] = "Um módulo personalizado de Placas de Nome desenha sua própria barra de vida, barra de conjuração, texto de nome e de vida sobre as placas de nome de inimigos e NPCs — totalmente configurável, com uma prévia ao vivo que se atualiza conforme você altera cada opção.",
    ["Health bar with your choice of texture, width, height, background, and a border drawn as thin lines or a texture, all in your own colours."] = "Barra de vida com textura, largura, altura e fundo à sua escolha, e uma borda desenhada como linhas finas ou textura, tudo nas suas próprias cores.",
    ["Colouring by reaction (hostile, neutral, friendly, tapped) and by class for players, plus role-based threat colouring for tanks and damage dealers."] = "Coloração por reação (hostil, neutro, amistoso, marcado) e por classe para jogadores, além de coloração de ameaça por função para tanques e causadores de dano.",
    ["Target and focus highlight rings, and an optional fade for plates that are not your target."] = "Anéis de destaque de alvo e de foco, e um esmaecimento opcional para as placas que não são seu alvo.",
    ["Cast bar with spell icon, spell name, and a separate colour for casts that cannot be interrupted."] = "Barra de conjuração com ícone da magia, nome da magia e uma cor separada para conjurações que não podem ser interrompidas.",
    ["Aura rows: your debuffs (or all of them), enemy buffs, and a separate prominent row for crowd control such as Polymorph, Fear and Sap. A glow marks enemy buffs you can steal or dispel."] = "Linhas de auras: suas penalidades (ou todas elas), benefícios inimigos e uma linha separada e destacada para controle de multidão como Polimorfia, Medo e Sedar. Um brilho marca os benefícios inimigos que você pode roubar ou dissipar.",
    ["Combo point pips on your target for Rogues and Druids in cat form."] = "Indicadores de pontos de combo no seu alvo para Ladinos e Druidas em forma felina.",
    ["Raid target markers (skull, cross, and the rest) with adjustable size and position."] = "Marcadores de alvo de raide (caveira, cruz e os demais) com tamanho e posição ajustáveis.",
    ["Friendly plates can show name only, the full plate, or nothing — set separately for players and NPCs — and can show a friendly NPC's subtitle under its name."] = "As placas amistosas podem mostrar somente o nome, a placa completa ou nada — definido separadamente para jogadores e NPCs — e podem mostrar o subtítulo de um NPC amistoso sob o nome.",
    ["A single \"Dark Skin\" module now covers the dark action-button and WeakAuras skin plus the optional Dark Mode that darkens Blizzard's default frames — those used to be two separate modules. Your existing settings carry over."] = "Um único módulo “Visual Escuro” agora cobre o visual escuro dos botões de ação e do WeakAuras, além do Modo Escuro opcional que escurece os quadros padrão da Blizzard — antes eram dois módulos separados. Suas configurações existentes são mantidas.",
    ["The reskin modules (skins, character panel, chat, friends list, minimap) are now one tabbed entry, matching how the other groups are already organised."] = "Os módulos de visual (visuais, painel do personagem, bate-papo, lista de amigos, minimapa) agora são uma única entrada com abas, seguindo como os outros grupos já estão organizados.",
    ["Consolidated groups now list their modules as a vertical, icon-labelled column instead of a wrapping row of tabs — easier to scan when there are many."] = "Os grupos consolidados agora listam seus módulos como uma coluna vertical com ícones, em vez de uma fileira de abas que quebra linha — mais fácil de percorrer quando há muitos.",
    ["A \"Patch Notes\" page under Overview shows every version's changes right in the game."] = "Uma página “Notas de Atualização” em Visão Geral mostra as mudanças de cada versão direto no jogo.",
    ["Cleaner tab names for a few tools: Training, Leisten-Profile, Apexis-Minispiel, Gruppensuche."] = "Nomes de abas mais limpos para algumas ferramentas: Training, Leisten-Profile, Apexis-Minispiel, Gruppensuche.",
    ["The target-frame extras and the elite player-frame border are now a single module called \"Player & Target Frame\". Your existing settings and per-character on and off state carry over automatically."] = "Os extras do quadro do alvo e a borda de elite do quadro do jogador agora são um único módulo chamado “Quadro do Jogador e do Alvo”. Suas configurações existentes e o estado ligado/desligado por personagem são mantidos automaticamente.",
    ["Settings now default to a separate profile per class, so what you set on one class no longer changes another. Your current settings are copied into each class profile, and you can still share or pin profiles as before."] = "As configurações agora usam por padrão um perfil separado por classe, então o que você define em uma classe não altera mais outra. Suas configurações atuais são copiadas para cada perfil de classe, e você ainda pode compartilhar ou fixar perfis como antes.",
    ["Scrolling messages that fire at the same moment now stack with a gap instead of overlapping."] = "As mensagens rolantes que disparam no mesmo instante agora se empilham com um espaçamento em vez de se sobrepor.",
    ["Fixed an error that could appear when combat started while your line was cast. The sound and interact settings now restore after combat ends instead."] = "Corrigido um erro que podia aparecer quando o combate começava com sua linha lançada. As configurações de som e de interação agora são restauradas depois que o combate termina.",
    ["Lighter cast bar time text, cooldown bars that batch their refreshes during busy moments, a cheaper combat-log check for the cooldown pulse, and a lighter minimap hover check."] = "Texto de tempo da barra de conjuração mais leve, barras de recarga que agrupam suas atualizações em momentos agitados, uma verificação do registro de combate mais barata para o pulso de recarga e uma verificação mais leve do mouse sobre o minimapa.",
    ["The spell stats are ordered spell power, healing, spell crit, then spell hit."] = "Os atributos de magia são ordenados como poder mágico, cura, crítico de magia e depois acerto de magia.",
    ["The Fishing and Mail tabs now read \"Angeln\" and \"Post\"."] = "As abas de Pesca e Correio agora exibem “Angeln” e “Post”.",
    ["A style dropdown at the top of the module options. Classic+ keeps the current look; Modern is a new dark, single-window style."] = "Um menu suspenso de estilo no topo das opções do módulo. Classic+ mantém o visual atual; Moderno é um novo estilo escuro de janela única.",
    ["Modern reskins the whole character window dark with an accent border and a stats panel on the right: a big equipped item level, then collapsible categories — attributes, melee, spell, defense and resistances — with per-stat hover breakdowns and mouse-wheel scrolling."] = "O Moderno aplica um visual escuro a toda a janela do personagem, com borda de destaque e um painel de atributos à direita: um nível de item equipado em destaque, depois categorias recolhíveis — atributos, corpo a corpo, magia, defesa e resistências — com detalhamento por atributo ao passar o mouse e rolagem com a roda do mouse.",
    ["Under Modern the built-in stats, resistance icons and the model rotate arrows are hidden, and the reputation, skills and player-versus-player sub-tabs plus the bottom tabs are skinned to match. Everything switches back to Classic+ live, and adapts per client (rating stats only where they exist)."] = "No Moderno, os atributos originais, os ícones de resistência e as setas de girar o modelo ficam ocultos, e as subabas de reputação, perícias e jogador contra jogador, além das abas inferiores, recebem o mesmo visual. Tudo volta ao Classic+ ao vivo e se adapta a cada cliente (atributos de índice só onde existem).",
    ["Dark skin for a world-map options window, with its own on and off switch in the Addon Skins options."] = "Visual escuro para uma janela de opções do mapa-múndi, com seu próprio interruptor de ligar e desligar nas opções de Visual de Addons.",
    ["The clock now sits on the same line as the date and zone instead of floating higher."] = "O relógio agora fica na mesma linha da data e da zona, em vez de flutuar mais acima.",
    ["Dark skin for a loot-distribution addon — its award and roll windows, its settings and overview windows, and the two always-visible roll and bid bars get the house panel, accent border and flat close button."] = "Visual escuro para um addon de distribuição de saque — suas janelas de premiação e de rolagem, suas janelas de configurações e de visão geral, e as duas barras sempre visíveis de rolagem e de lance recebem o painel da casa, a borda de destaque e o botão chapado de fechar.",
    ["Dark skin for an attunement tracker — the main window and its buttons match the dark look; the colored status rows stay as they are so the state colors remain readable."] = "Visual escuro para um rastreador de sintonização — a janela principal e seus botões seguem o visual escuro; as linhas coloridas de status permanecem como estão para que as cores de estado continuem legíveis.",
    ["Both are separate on and off switches in the Addon Skins options, next to the others."] = "Ambos são interruptores separados de ligar e desligar nas opções de Visual de Addons, ao lado dos outros.",
    ["NEW:"] = "NOVO:",
    ["A single unified inventory window: all bags in one grid, with quality borders, counts, cooldowns, money and free slots. Movable and scalable."] = "Uma única janela de inventário unificada: todas as mochilas em uma grade, com bordas de qualidade, quantidades, recargas, dinheiro e espaços livres. Móvel e escalável.",
    ["Fixes stuck inspect bugs (no player inspect possible after a faulty close/timeout). Auto-reset after a timeout, auto-retry when the window stays empty, cleanup when InspectFrame closes + /inspectreset slash command."] = "Corrige bugs de inspeção travada (nenhuma inspeção de jogador possível após um fechamento com falha ou tempo esgotado). Redefinição automática após o tempo esgotar, nova tentativa automática quando a janela fica vazia, limpeza quando o InspectFrame fecha + comando /inspectreset.",
    ["A modern minimap: round with a clean dark ring and accent line, zone text and clock in a slim panel, mouse-wheel zoom, movable and scalable. Optionally hides other addons' buttons until mouseover."] = "Um minimapa moderno: redondo, com um anel escuro limpo e linha de destaque, texto de zona e relógio em um painel fino, zoom com a roda do mouse, móvel e escalável. Opcionalmente oculta os botões de outros addons até passar o mouse.",
    ["Custom enemy & NPC nameplates with a live preview: health bar, cast bar, name and health text, reaction / class colours, target highlight and threat colouring."] = "Placas de nome personalizadas de inimigos e NPCs com prévia ao vivo: barra de vida, barra de conjuração, texto de nome e de vida, cores de reação / classe, destaque do alvo e coloração de ameaça.",
    ["Hover an equipment slot for a compact flyout of compatible bag items, or modifier-click for a larger picker. Click an item to equip it."] = "Passe o mouse sobre um espaço de equipamento para ver um painel rápido e compacto de itens compatíveis das mochilas, ou clique com um modificador para um seletor maior. Clique em um item para equipá-lo.",
    ["Move every VuloUI window and Blizzard's default frames in one editor."] = "Mova todas as janelas do VuloUI e os quadros padrão da Blizzard em um único editor.",
    ["One-key fishing: one key casts, reels and applies a lure, and auto-loots your catch."] = "Pesca com uma tecla: uma tecla lança, recolhe e aplica uma isca, e coleta automaticamente sua pescaria.",
    ["Adds an 'Open All' button to your mailbox that collects every attachment and coin in one click."] = "Adiciona um botão “Abrir Tudo” à sua caixa de correio que coleta todos os anexos e moedas em um clique.",
    ["Top"] = "Topo",
    ["Bottom"] = "Base",
    ["Top-Left"] = "Superior esquerdo",
    ["Top-Right"] = "Superior direito",
    ["Bottom-Left"] = "Inferior esquerdo",
    ["Bottom-Right"] = "Inferior direito",
    ["Trinkets: Cleared all ignored/hidden trinkets."] = "Trinkets: todos os berloques ignorados/ocultos foram limpos.",
    ["Trinkets usage:"] = "Uso de Trinkets:",
    ["/trinket or /Trinkets : toggle the window"] = "/trinket or /Trinkets : alterna a janela",
    ["/trinket reset : reset all settings"] = "/trinket reset : redefine todas as configurações",
    ["/trinket clear : clear all ignored/hidden trinkets"] = "/trinket clear : limpa todos os berloques ignorados/ocultos",
    ["/trinket opt : summon options window"] = "/trinket opt : abre a janela de opções",
    ["/trinket lock|unlock : toggles window lock"] = "/trinket lock|unlock : alterna a trava da janela",
    ["/trinket scale main|menu (number) : sets an exact scale"] = "/trinket scale main|menu (number) : define uma escala exata",
    ["/trinket load top|bottom profilename : loads a profile to top or bottom trinket"] = "/trinket load top|bottom profilename : carrega um perfil no berloque de cima ou de baixo",
    ["Are you sure you want to reset Trinkets to default state and reload the UI?"] = "Tem certeza de que deseja redefinir o Trinkets para o estado padrão e recarregar a interface?",
    ["Queued: %s"] = "Na fila: %s",
    ["Priority"] = "Prioridade",
    ["Pause Queue"] = "Pausar Fila",
    ["Parameter must be 0 for top trinket or 1 for bottom."] = "O parâmetro deve ser 0 para o berloque de cima ou 1 para o de baixo.",
    ["No profiles saved yet."] = "Nenhum perfil salvo ainda.",
    -- Patch notes 1.37.1
    ["Visuals"] = "Visual",
    ["The language option under General now actually applies. It silently never took effect — the addon read the client language before your saved choice was loaded. After a /reload every label, dropdown and popup follows your choice."] = "A opção de idioma em Geral agora é aplicada de verdade. Ela silenciosamente nunca tinha efeito: o addon lia o idioma do cliente antes de a sua escolha salva ser carregada. Após um /reload, todos os rótulos, listas suspensas e janelas seguem a sua escolha.",
    ["The Patch Notes page is translated into all languages, including every past version."] = "A página de notas de atualização está traduzida em todos os idiomas, incluindo todas as versões anteriores.",
    ["The trinket panel, its queue window and the /trinket help are translated too."] = "O painel de berloques, sua janela de fila e a ajuda do /trinket também estão traduzidos.",
    ["German: sixteen duplicated translations cleaned up, five of which contradicted each other."] = "Alemão: dezesseis traduções duplicadas limpas, cinco delas contraditórias.",
    ["Third pass over the busiest code paths: nameplate auras scan once instead of four times, combat-log and aura events skip a safety wrapper, timer texts only redraw when the shown number changes, and several background listeners now sleep while their feature is off or hidden. Less stutter in raids and arenas."] = "Terceira passada pelos caminhos de código mais exigidos: as auras das placas de nome são examinadas uma vez em vez de quatro, os eventos do registro de combate e de auras dispensam um invólucro de segurança, os textos dos temporizadores só são redesenhados quando o número exibido muda e vários ouvintes em segundo plano dormem enquanto sua função está desligada ou oculta. Menos engasgos em raides e arenas.",
    ["The frames can be turned off again without leftovers."] = "As janelas podem ser desativadas novamente sem sobras.",
    ["An interrupted enemy cast now shows INTERRUPTED briefly — it used to vanish the same instant."] = "Um feitiço inimigo interrompido agora mostra INTERROMPIDO por um instante — antes ele sumia no mesmo momento.",
    ["Diminishing-returns icons clean up correctly after toggling the tracker mid-arena."] = "Os ícones de retornos decrescentes se limpam corretamente ao alternar o rastreador no meio da arena.",
    ["Seven working settings that were invisible in the options are shown again, and several switches that did nothing are wired up."] = "Sete configurações funcionais que estavam invisíveis nas opções voltam a aparecer, e vários interruptores que não faziam nada agora estão ligados.",
    ["Modules tidy up after themselves when disabled: totem range dimming, the inspect window, queue timer, quest log and font bars no longer leave stale pieces behind."] = "Os módulos arrumam tudo ao serem desativados: o escurecimento por alcance dos totens, a janela de inspeção, o temporizador de fila, o registro de missões e as barras de fonte não deixam mais peças obsoletas.",
    ["Three modules got their own sidebar icons instead of the placeholder, and Reminders got a nicer bell."] = "Três módulos ganharam ícones próprios na barra lateral em vez do provisório, e os Lembretes ganharam um sino mais bonito.",
    -- Bags: quest starter marker
    ["Quest starter marker (!)"] = "Marcador de início de missão (!)",
    ["Overlays a yellow exclamation mark on items that start a quest you have not accepted yet."] = "Sobrepõe um ponto de exclamação amarelo aos itens que iniciam uma missão que você ainda não aceitou.",
    -- Options page build failure
    ["|cffff5555Options page '%s' failed to build:|r %s"] = "|cffff5555Não foi possível montar a página de opções '%s':|r %s",
    ["|cffff5555This page could not be built. /reload, and report it if it persists.|r"] = "|cffff5555Não foi possível montar esta página. Use /reload e relate se persistir.|r",
    ["|cff888888%.2f ms/frame |cff666666(%.1f%% of ours, peak %.1f ms)|r|r"] = "|cff888888%.2f ms/quadro |cff666666(%.1f%% nosso, pico %.1f ms)|r|r",
    ["|cffaaaaaaThe header shows how much frame time VuloClassicUI costs. Your client measures this on its own, all the time — no setting and no reload needed.|r"] = "|cffaaaaaaO cabeçalho mostra quanto tempo de quadro o VuloClassicUI custa. Seu cliente mede isso sozinho, o tempo todo, sem ajustes nem recarregar.|r",
    -- Patch notes 1.37.2
    ["Classic Era, Hardcore and Season of Discovery"] = "Classic Era, Hardcore e Season of Discovery",
    ["Under the hood"] = "Nos bastidores",
    ["The addon loads again without ticking \"Load out of date AddOns\". Blizzard's July interface update moved these realms to a new version number."] = "O addon carrega novamente sem marcar «Carregar AddOns desatualizados». A atualização de interface da Blizzard em julho levou esses reinos a um novo número de versão.",
    ["Fixed a crash that switched the whole Class Trainer page off on Season of Discovery: one ability the realm does not know took the entire module down with it."] = "Corrigida uma falha que desligava a página inteira do Treinador de classe no Season of Discovery: uma única habilidade que o reino não conhece derrubava o módulo todo.",
    ["The elite border on your player frame sits correctly again. It was placed against the old frame layout, which that same update replaced."] = "A borda de elite do seu quadro de jogador está no lugar certo de novo. Ela era posicionada pelo layout antigo do quadro, que essa mesma atualização substituiu.",
    ["Fixed a rare error storm at the end of a fight. Cleanup work in nineteen files could be skipped and the chat filled with error lines."] = "Corrigida uma rara enxurrada de erros no fim de um combate. A limpeza em dezenove arquivos podia ser pulada e o chat enchia de linhas de erro.",
    ["Combat log features (swing timer, cooldown pulse, combat text, arena tracker, nameplates, mana display) no longer depend on a setting a player can switch off."] = "Os recursos do registro de combate (temporizador de golpe, pulso de recarga, textos de combate, rastreador de arena, placas de nome, indicador de mana) não dependem mais de uma opção que pode ser desligada.",
    ["An interrupted enemy cast now really shows INTERRUPTED for a moment."] = "Um feitiço inimigo interrompido agora mostra mesmo a interrupção por um instante.",
    ["Items that start a quest you have not accepted yet are marked with a yellow exclamation mark, in bags, bank and keyring."] = "Itens que iniciam uma missão que você ainda não aceitou recebem um ponto de exclamação amarelo, nas bolsas, no banco e no chaveiro.",
    ["Seven of the eight shipped translations no longer build their lookup table at all. Only the language you actually read is assembled, which frees about a megabyte on every login."] = "Sete das oito traduções incluídas não montam mais a sua tabela de consulta. Só o idioma que você realmente lê é montado, o que libera cerca de um megabyte a cada login.",
    ["Edit Mode: three background drivers no longer run permanently, dragging a window allocates far less, and finding a window is a direct lookup instead of a search."] = "Modo de edição: três controladores em segundo plano não rodam mais o tempo todo, arrastar uma janela gera bem menos desperdício e localizar uma janela é uma consulta direta em vez de uma busca.",
    ["Disabling a module now detaches it completely — several used to leave listeners running for the rest of the session."] = "Desativar um módulo agora o desconecta por completo: vários deixavam ouvintes ativos pelo resto da sessão.",
    ["The performance readout in the header uses your client's own always-on measurement, so it needs no setting and no reload."] = "O indicador de desempenho no cabeçalho usa a medição sempre ativa do seu cliente, então não precisa de ajuste nem de recarregar.",
    -- Patch notes 1.37.2
    -- Built-in profiler
    ["Nothing measured yet. Play for a bit, then read it again."] = "Nada medido ainda. Jogue um pouco e leia de novo.",
    ["Measured over %.1f s -- %.1f ms total, %.2f%% of it ours:"] = "Medido ao longo de %.1f s: %.1f ms no total, dos quais %.2f%% são nossos:",
    ["Measurement off."] = "Medição desligada.",
    ["Measurement reset."] = "Medição zerada.",
    ["Measurement on. Play, then type /vcuiprof again to read it."] = "Medição ligada. Jogue um pouco e digite /vcuiprof novamente para ler.",
    -- Patch notes 1.37.3
    ["Class Trainer page"] = "Página do Treinador de classe",
    ["Fixed the page being thrown away again a moment after you opened it, dropping you back on a class tab. The spell book resets its own page whenever your spells change, and our page sits past the last real tab, so it was always the one discarded. Most noticeable on Season of Discovery, where engraving changes spells constantly."] = "Corrigido o descarte da página logo após você abri-la, jogando você de volta em uma aba de classe. O grimório reinicia a própria página sempre que seus feitiços mudam, e a nossa fica além da última aba real — então era sempre ela a descartada. Mais perceptível no Season of Discovery, onde a gravação muda feitiços o tempo todo.",
    ["`/vcuiprof` measures how much frame time each part of the addon costs, then prints a list. It ships switched off and costs nothing while it is — the measuring code is only put in place when you turn it on. Type it once to start, once more to read."] = "`/vcuiprof` mede quanto tempo de quadro cada parte do addon custa e imprime uma lista. Ele vem desligado e, nesse estado, não custa nada: o código de medição só entra quando você o liga. Digite uma vez para começar e outra para ler.",
    -- Patch notes 1.37.4
    ["Clicking a trinket button while that trinket slot is empty no longer throws an error. The game's own shortcut for \"use the item in slot N\" stopped tolerating an empty slot with July's interface update, so the button now takes a different route to the same action."] = "Clicar em um botão de berloque com o espaço vazio não gera mais um erro. O atalho do próprio jogo para «usar o item no espaço N» deixou de tolerar um espaço vazio com a atualização de interface de julho, então o botão agora segue outro caminho para a mesma ação.",
    ["Fixed a stutter of almost two frames every time you entered or left combat, if you use WeakAuras and have the WeakAuras skin switched on. Every combat change repainted every aura you have ever saved — including the ones not on screen — with a look that had not changed. Auras are now only repainted when the settings or their size actually changed. Measured: 28 ms down to under 2 ms. The skin itself is unchanged."] = "Corrigido um engasgo de quase dois quadros a cada início e fim de combate, se você usa WeakAuras e tem o nosso visual para WeakAuras ligado. Cada mudança de combate repintava todas as auras já salvas — inclusive as que não estão na tela — com uma aparência que não havia mudado. Agora as auras só são repintadas quando as configurações ou o tamanho realmente mudam. Medido: de 28 ms para menos de 2 ms. O visual em si não muda.",
    -- Patch notes 1.39.0
    ["Download"] = "Download",
    ["Diminishing Returns Position – Put the DR row on either side of the frame, with its own X and Y offset"] = "Posição da redução de efeitos – Coloca a fileira em qualquer lado do quadro, com deslocamento X e Y próprios",
    ["The DR row no longer lands on top of the trinket or racial icon. It used to hang at a fixed distance on the right edge, exactly where the side icon sits, so switching it on stacked the two. The new default clears it, and on the left edge the row grows outward instead of across the frame."] = "A fileira de redução de efeitos não cai mais sobre o ícone de berloque ou de habilidade racial. Ela ficava a uma distância fixa da borda direita, exatamente onde está o ícone lateral, então ligá-la empilhava os dois. O novo padrão a afasta, e na borda esquerda a fileira cresce para fora em vez de atravessar o quadro.",
    ["The trinket and racial icons sit further out from the enemy frame and are a little smaller, so the health and mana bars read as the middle of the frame instead of competing with an icon at each shoulder. Both are sliders, so your own values are kept."] = "Os ícones de berloque e de habilidade racial ficam mais afastados do quadro do inimigo e são um pouco menores, de modo que as barras de vida e mana se leem como o centro do quadro em vez de disputar espaço com um ícone em cada ombro. Ambos são controles deslizantes, então os seus próprios valores são mantidos.",
    ["The addon folder no longer ships build tools and source files that no player needs. The licence files stay where they are."] = "A pasta do addon não traz mais ferramentas de compilação e arquivos-fonte que nenhum jogador precisa. Os arquivos de licença continuam onde estão.",
    ["The release notes on the distribution pages are written in English now."] = "As notas de versão nas páginas de distribuição agora são escritas em inglês.",
    ["Six languages were missing seven texts that existed in German only. All nine are complete again."] = "Faltavam a seis idiomas sete textos que só existiam em alemão. Os nove estão completos de novo.",
    ["The keyword help for the item search was misleading in Chinese: it gave an English type name as the example, which a Chinese client would never have matched. The example is written in the reader's own language now."] = "A ajuda de palavras-chave da busca de itens era enganosa em chinês: dava como exemplo um nome de tipo em inglês que um cliente chinês nunca teria encontrado. Agora o exemplo é escrito no idioma de quem lê.",
    ["Seal Twist Helper – A swing bar with the twist window marked, plus the next sensible action"] = "Auxiliar de troca de selos – Uma barra de golpe com a janela de troca marcada e a próxima ação sensata",
    ["The bar counts down to your next auto attack with two marks: green is the last moment the second seal can still land, purple is how long a Judgement still fits in front of it. The next action is worked out live from your swing timer, the global cooldown and the seals actually on you — not from a fixed rotation. Crusader Strike is only suggested while there is room for it and the holding seal afterwards. Judgement deliberately gets none: it consumes the seal, and a wrong hint costs more there than no hint. Off by default."] = "A barra faz a contagem regressiva até seu próximo ataque automático com duas marcas: a verde é o último momento em que o segundo selo ainda consegue entrar, e a roxa mostra quanto tempo um Julgamento ainda cabe antes dela. A próxima ação é calculada ao vivo a partir do seu ritmo de golpe, do tempo de recarga global e dos selos realmente ativos em você — e não de uma rotação fixa. Golpe do Cruzado só é sugerido enquanto houver espaço para ele e para o selo que você mantém depois. O Julgamento não recebe nenhuma de propósito: ele consome o selo, e ali um aviso errado custa mais do que nenhum. Desativado por padrão.",
    -- Sidebar groups (QoL split, 1.40.0)
    ["Bags & Items"] = "Bolsas e itens",
    ["Chat & Social"] = "Bate-papo e social",
    ["Extras"] = "Extras",
    ["Tools"] = "Ferramentas",
    -- Overview page
    ["peak %.1f ms"] = "pico %.1f ms",
    ["%.2f ms"] = "%.2f ms",
    ["%.1f MB"] = "%.1f MB",
    ["%d KB"] = "%d KB",
    ["%d of %d"] = "%d de %d",
    ["moved"] = "movidas",
    ["Modules"] = "Módulos",
    ["Frame time"] = "Tempo por quadro",
    ["Memory"] = "Memória",
    ["Windows"] = "Janelas",
    ["%d modules are switched off."] = "%d módulos estão desligados.",
    ["The edit mode grid is switched on."] = "A grade do modo de edição está ligada.",
    ["There are patch notes you have not read yet."] = "Há notas de versão que você ainda não leu.",
    ["What would you like to change?"] = "O que você quer ajustar?",
    ["Worth knowing"] = "Vale saber",
    ["Recently visited"] = "Visitados recentemente",
    -- Talent overrides
    ["active"] = "ativos",
    ["Talent Overrides"] = "Ajustes por grupo de talentos",
    ["Talent group %d"] = "Grupo de talentos %d",
    ["%d settings overridden"] = "%d ajustes substituídos",
    ["Forget all overrides for this talent group"] = "Esquecer todos os ajustes deste grupo de talentos",
    ["Overrides apply on their own when you switch talent groups. This client has no specialisations, so the dual talent system is the axis."] = "Os ajustes se aplicam sozinhos ao trocar de grupo de talentos. Este cliente não tem especializações, então o eixo é o sistema de talento duplo.",
    -- Override groups
    ["Talent group %d (%s)"] = "Grupo de talentos %d (%s)",
    ["Name for the new group"] = "Nome do novo grupo",
    ["Editing as"] = "Editando como",
    ["Yourself"] = "Você mesmo",
    ["Manage groups..."] = "Gerenciar grupos...",
    ["Owns the current talent group"] = "Vale para o grupo de talentos atual",
    ["Delete this group"] = "Excluir este grupo",
    ["No groups yet."] = "Nenhum grupo ainda.",
    -- Anchor points
    ["Centre"] = "Centro",
    ["Thin outline"] = "Contorno fino",
    ["Bar Setups"] = "Configurações de barra",
    -- Patch notes 1.40.0
    ["Moved out of the sidebar into Global Settings, as its own tab beside Profiles. Your saved setups were kept."] = "Saiu da barra lateral e foi para as Configurações globais, como aba própria ao lado de Perfis. Suas configurações salvas foram mantidas.",
    ["They were stored once per class profile — seven copies of one macro library. Stored once now, which cut the settings file by a third. Identical copies are merged, ones that differ are kept side by side."] = "Ficavam armazenadas uma vez por perfil de classe: sete cópias da mesma biblioteca de macros. Agora ficam apenas uma vez, o que reduziu o arquivo de configurações em um terço. Cópias idênticas são unidas e as diferentes são mantidas lado a lado.",
    ["The chat window no longer jumps back the moment you open the edit mode. Switching layouts re-anchors every window the game knows about, including ones we place ourselves."] = "A janela de bate-papo não volta mais para trás assim que você abre o modo de edição. Trocar de layout reancora todas as janelas que o jogo conhece, inclusive as que nós mesmos posicionamos.",
    ["A dropdown with a long entry no longer wraps into the row below it."] = "Um menu suspenso com uma entrada longa não quebra mais para a linha de baixo.",
    ["The first page is a picture of your interface instead of a second sidebar: modules running, frame time and memory, windows you moved, pages you last visited."] = "A primeira página mostra o estado da sua interface em vez de uma segunda barra lateral: módulos em execução, tempo de quadro e memória, janelas que você moveu e as últimas páginas visitadas.",
    ["Talent Overrides – Named groups hold their own value for individual settings and apply when you switch talent specs"] = "Substituições de talentos – Grupos nomeados guardam valores próprios para configurações individuais e são aplicados ao trocar de escolha de talentos",
    ["A group can also name a situation — raid, dungeon, arena, battleground, in a group, alone. Anything you change while a group is active is recorded into it, and every overridden row is marked."] = "Um grupo também pode indicar uma situação: raide, masmorra, arena, campo de batalha, em grupo ou sozinho. Tudo o que você mudar com um grupo ativo é registrado nele, e cada linha substituída fica marcada.",
    ["Sliders are one row like every other setting, their number can be typed into, and labels line up in a measured column across the page. A long translation no longer pushes a value box into the next column or a button off its card."] = "Os deslizadores ocupam uma linha como qualquer outra configuração, o número pode ser digitado e os rótulos se alinham em uma coluna medida ao longo da página. Uma tradução longa não empurra mais um bloco de valor para a coluna vizinha nem um botão para fora do cartão.",
    ["Every section starts closed, so a long page opens as a list of headings."] = "Cada seção começa recolhida, então uma página longa abre como uma lista de títulos.",
    ["The automatic swap queue has controls again — order, delay and the stop marker, on the trinket page. They only ever existed in a window this addon hides."] = "A fila de troca automática voltou a ter controles: ordem, atraso e a marca de parada, na página de berloques. Eles só existiam em uma janela que este complemento esconde.",
    ["Trinket icons show up again: on the buttons, on the queue marker, and on your worn trinkets right after login instead of only once you click them."] = "Os ícones de berloques aparecem de novo: nos botões, na marca da fila e nos berloques equipados logo após entrar, em vez de somente ao clicar.",
    -- Befehlsregistratur
    ["%s has no handler yet — this is a bug, please report it."] = "%s ainda não tem um manipulador — isso é um erro, por favor relate.",
    ["%s belongs to %s, which is switched off."] = "%s pertence a %s, que está desativado.",
    ["|cff9b6cffCommands|r — %d in total. Grey ones belong to a module that is switched off."] = "|cff9b6cffComandos|r — %d no total. Os cinzentos pertencem a um módulo desativado.",
    ["%s is also claimed by another addon (%s) — one of the two wins."] = "%s também é reivindicado por outro complemento (%s) — apenas um dos dois vence.",
    -- v1.40.0 nachgezogen
    ["|cffff5555Bar setups module not loaded.|r"] = "|cffff5555O módulo de configurações de barra não está carregado.|r",
    ["Bar setup '%s' saved."] = "Configuração de barra '%s' salva.",
    ["Bar setup '%s' deleted."] = "Configuração de barra '%s' excluída.",
    ["Not in combat — bars can't be changed while fighting."] = "Fora de combate — as barras não podem ser alteradas durante a luta.",
    ["Bar setup '%s' loaded: %d slots set, %d cleared, |cffff8800%d skipped|r (unknown spell / missing item or macro)."] = "Configuração de barra '%s' carregada: %d espaços preenchidos, %d esvaziados, |cffff8800%d ignorados|r (magia desconhecida / item ou macro ausente).",
    ["Bar setup '%s' loaded: %d slots set, %d cleared."] = "Configuração de barra '%s' carregada: %d espaços preenchidos, %d esvaziados.",
    ["on"] = "ligado",
    ["Overridden settings: %s"] = "Configurações substituídas: %s",
    ["Situation"] = "Situação",
    ["Everywhere"] = "Em toda parte",
    ["Raid instance"] = "Raide",
    ["5-player instance"] = "Masmorra (5 jogadores)",
    ["Battleground"] = "Campo de batalha",
    ["In a group"] = "Em grupo",
    ["Alone"] = "Sozinho",
    ["Applies only in this situation. Combined with a talent group, both have to be true - and that group then overrides one that names only the talent group."] = "Vale apenas nesta situação. Junto com uma escolha de talentos, as duas precisam ser verdadeiras — e esse grupo então prevalece sobre um que indique somente a escolha de talentos.",
    ["Icon"] = "Ícone",
    ["No icon"] = "Sem ícone",
    ["Shown in front of the group name in the menu and on the header button."] = "Aparece antes do nome do grupo no menu e no botão de cabeçalho.",
    ["Switch off to drop this one override. The setting then follows the profile again."] = "Desligar remove apenas esta substituição. A configuração volta a seguir o perfil.",
    ["Bar setups are now stored once for the whole account: %d kept, %d duplicates merged."] = "As configurações de barra agora ficam guardadas uma única vez para toda a conta: %d mantidas, %d duplicadas unidas.",
    ["Trinket window settings now live in this addon's own database."] = "As configurações da janela de berloques agora ficam no banco de dados deste complemento.",
    ["Auto queue: top slot"] = "Fila automática: espaço de cima",
    ["Auto queue: bottom slot"] = "Fila automática: espaço de baixo",
    ["Auto queue for this slot"] = "Fila automática para este espaço",
    ["Same switch as alt-clicking the slot. While on, the queue swaps this trinket in combat, following the order below."] = "O mesmo interruptor de um alt-clique no espaço. Ligada, a fila troca este berloque em combate seguindo a ordem abaixo.",
    ["Order"] = "Ordem",
    ["The queue works through this list from the top. Pick an entry to move it or to change its settings."] = "A fila percorre esta lista de cima para baixo. Escolha uma entrada para movê-la ou mudar suas configurações.",
    ["- empty -"] = "- vazio -",
    ["— queue stops here —"] = "— a fila para aqui —",
    ["Add from bags"] = "Adicionar das bolsas",
    ["Adds a trinket you are carrying to the end of this list."] = "Adiciona ao fim desta lista um berloque que você esteja carregando.",
    ["Swap delay"] = "Atraso de troca",
    ["Seconds this trinket stays equipped before the queue swaps it out again. 0 = no wait."] = "Segundos que este berloque fica equipado antes de a fila trocá-lo de novo. 0 = sem espera.",
    ["This trinket is swapped in ahead of the ones above it once it is ready."] = "Este berloque é equipado antes dos que estão acima assim que ficar pronto.",
    ["Pause while equipped"] = "Pausar enquanto equipado",
    ["While this trinket is worn the queue holds still - for a trinket whose effect you do not want cut short."] = "Enquanto este berloque estiver equipado a fila fica parada — para um berloque cujo efeito você não quer interromper.",
    ["|cffaaaaaaTip: left click a slot to use the trinket, right click for the list. Alt-click arms the auto queue for that slot.|r"] = "|cffaaaaaaDica: clique esquerdo em um espaço usa o berloque, clique direito abre a lista. Alt-clique arma a fila automática daquele espaço.|r",
    ["%d snapshot(s) had the same name but different contents and were kept under a new name."] = "%d instantâneo(s) tinham o mesmo nome, mas conteúdo diferente, e foram mantidos com um novo nome.",
    ["GAP"] = "ESPAÇAMENTO",
    ["Distance from that edge, in pixels. 0 is flush."] = "Distância até essa borda, em pixels. 0 é rente.",
    ["Docks this window to that side of the target and centres it there. 'Centered' does not move it - it only travels along. The gap is kept edge-to-edge, so it survives either window being resized."] = "Encaixa esta janela naquele lado da janela alvo e a centraliza ali. 'Centralizado' não a move — ela apenas acompanha. O espaçamento é mantido de borda a borda, então sobrevive ao redimensionamento de qualquer uma das janelas.",
    ["waiting for a swing"] = "aguardando um golpe",
    ["  -  lag %.0fms"] = "  -  latência %.0fms",
    ["|cffff8800No seal to twist out of. Only Seal of Command and Seal of Righteousness carry over to a swing after being replaced, so one of the two has to be learned.|r"] = "|cffff8800Nenhum selo do qual trocar. Só o Selo de Comando e o Selo de Retidão continuam valendo em um golpe depois de serem substituídos, então um dos dois precisa estar aprendido.|r",
    ["|cffff8800Only one seal learned. A second one is needed to twist into.|r"] = "|cffff8800Apenas um selo aprendido. É preciso um segundo para trocar.|r",
    ["|cffff8800The seal you hold cannot be twisted out of. Only Seal of Command and Seal of Righteousness carry over to the swing that replaces them.|r"] = "|cffff8800Não dá para trocar a partir do selo que você mantém. Só o Selo de Comando e o Selo de Retidão continuam valendo no golpe que os substitui.|r",
    ["Only Seal of Command and Seal of Righteousness work here: they are the two whose effect still lands on the swing that replaces them."] = "Aqui só servem o Selo de Comando e o Selo de Retidão: são os dois cujo efeito ainda vale no golpe que os substitui.",
    -- Namensplaketten-Vorlage
    ["Nameplate settings replaced. Switch profile to get the old ones back."] = "As configurações das placas de nome foram substituídas. Troque de perfil para recuperar as anteriores.",
    ["Overwrites this profile's nameplate settings with a wide, flat, dark look. Other profiles are untouched."] = "Sobrescreve as configurações de placas de nome deste perfil com um visual largo, plano e escuro. Os outros perfis não são alterados.",
    ["|cffaaaaaaOverwrites this profile's nameplate settings with a wide, flat, dark look. Other profiles are untouched.|r"] = "|cffaaaaaaSobrescreve as configurações de placas de nome deste perfil com um visual largo, plano e escuro. Os outros perfis não são alterados.|r",
    ["Apply the wide, flat look"] = "Aplicar o visual largo e plano",
    -- Plaetze der Namensplaketten
    ["Main positions"] = "Posições principais",
    ["|cffaaaaaaOne thing per slot. Giving a slot something takes it away from the slot that had it.|r"] = "|cffaaaaaaUma coisa por espaço. O que você colocar em um espaço é retirado de quem o tinha.|r",
    ["Debuffs"] = "Perdas",
    ["Buffs"] = "Ganhos",
    ["Crowd control"] = "Controle de grupo",
    ["Your own debuffs"] = "Suas próprias perdas",
    -- Leuchten bei wenig Leben, Entzauber-Leuchten
    ["Glow when low on health"] = "Brilho com pouca vida",
    ["A coloured ring around the bar once the unit drops below the mark."] = "Um anel colorido ao redor da barra assim que o alvo cai abaixo da marca.",
    ["Glow below (%)"] = "Brilho abaixo de (%)",
    ["Low health colour"] = "Cor de pouca vida",
    ["Glow in the aura's own school colour"] = "Brilhar na cor de escola da aura",
    ["Magic blue, curse purple, disease orange, poison green — instead of one colour for everything."] = "Magia azul, maldição roxo, doença laranja, veneno verde — em vez de uma cor para tudo.",
    -- Absorptionsstil
    ["Absorb style"] = "Estilo de absorção",
    ["Flat colour"] = "Cor sólida",
    -- Zauberziel
    ["Show who the cast is aimed at"] = "Mostrar em quem a magia é lançada",
    ["The caster's current target, beside the cast bar. Your own name is coloured."] = "O alvo atual de quem conjura, ao lado da barra de conjuração. Seu próprio nome fica colorido.",
    ["Cast target size"] = "Tamanho do alvo da magia",
    -- Zielpfeile
    ["Arrows beside your target"] = "Setas ao lado do seu alvo",
    ["Two arrows pointing in at the target's bar, one on each side."] = "Duas setas apontando para a barra do alvo, uma de cada lado.",
    ["Arrow size"] = "Tamanho da seta",
    ["Arrow distance"] = "Distância da seta",
    ["Arrow colour"] = "Cor da seta",
    -- Fokus-Merkzeichen
    ["Mark on the focus plate"] = "Marca na placa do foco",
    ["A short text on your focus target's plate. A ring says this one is special; the mark says which."] = "Um texto curto na placa do seu alvo de foco. Um anel diz que aquela é especial; a marca diz qual.",
    ["Mark text"] = "Texto da marca",
    ["Mark position"] = "Posição da marca",
    ["Mark size"] = "Tamanho da marca",
    -- Kleine Plaketten
    ["Back to the small plates"] = "Voltar às placas pequenas",
    ["Puts the same settings back to the small plates this addon ships with."] = "Devolve as mesmas configurações às placas pequenas que este complemento traz.",
    ["|cffaaaaaaHold Seal of Command, then cast the second seal in the last fraction of a second before your auto-attack: that swing carries both. Below level 64 the second seal is Righteousness; Blood and the Martyr replace it from there.|r"] = "|cffaaaaaaMantenha o Selo de Comando e lance o segundo selo na última fração de segundo antes do seu ataque automático: aquele golpe carrega os dois. Abaixo do nível 64 o segundo selo é o da Retidão; a partir daí Sangue e Mártir o substituem.|r",
    ["|cffaaaaaaThe bar counts down to the swing in zones: |cff5c8aebblue|r is free for a filler, |cffd93636red|r is the stretch where a cast would still be on the global cooldown when the window opens, and |cff33ff66green|r is the twist window. The last mark inside the green is the late twist, which leaves room for a judgement in front of the seal.|r"] = "|cffaaaaaaA barra faz a contagem até o golpe em zonas: |cff5c8aebazul|r está livre para um complemento, |cffd93636vermelho|r é o trecho em que um lançamento ainda estaria no tempo de recarga global quando a janela abrir, e |cff33ff66verde|r é a janela de troca. A última marca dentro do verde é a troca tardia, que deixa espaço para um julgamento antes do selo.|r",
    ["Late twist window (seconds)"] = "Janela de troca tardia (segundos)",
    ["The tail of the twist window, marked separately. Twisting that late still leaves room for a judgement in front of the seal. Set it as long as the twist window to hide the mark."] = "O fim da janela de troca, marcado à parte. Trocar tão tarde ainda deixa espaço para um julgamento antes do selo. Deixe do mesmo tamanho da janela de troca para esconder a marca.",
    ["Second cue for the late window"] = "Segundo aviso para a janela tardia",
    ["A different sound at the late twist mark, so the two ends of the window can be told apart without looking at the bar."] = "Um som diferente na marca da troca tardia, para distinguir as duas pontas da janela sem olhar a barra.",
    ["Shade the zones"] = "Colorir as zonas",
    ["Tints the part of the swing still to come in the colour of the zone it runs into."] = "Tinge a parte do golpe que ainda falta com a cor da zona em que ela cai.",
    ["Show the marks"] = "Mostrar as marcas",
    ["The three boundary lines: danger zone, twist window, late twist."] = "As três linhas de limite: zona de perigo, janela de troca, troca tardia.",
    ["Show seal indicators"] = "Mostrar indicadores de selo",
    ["The seals currently on you and how long they last, right of the bar. Both show while the twist is in -- that overlap is the pay-off."] = "Os selos que estão em você e quanto duram, à direita da barra. Os dois aparecem enquanto a troca está feita: essa sobreposição é o ganho.",
    ["Seal icon size"] = "Tamanho dos ícones de selo",
    ["Head start for the prompt (ms)"] = "Antecipação do aviso (ms)",
    ["Shows the twist prompt and plays its cue this far before the window actually opens, so there is time to see it and press. The colours on the bar stay exact."] = "Mostra o aviso de troca e toca o som este tanto antes de a janela abrir de fato, para dar tempo de ver e apertar. As cores da barra continuam exatas.",
    ["auto"] = "Auto",
    ["Twist only"] = "Só a troca",
    ["Rotation"] = "Rotação",
    ["Show the rotation helper"] = "Mostrar o auxílio de rotação",
    ["A row of steps above the bar: which sequence fits your weapon and haste, and where in it you are. It steps forward on what you actually cast and on your swings."] = "Uma fileira de passos acima da barra: qual sequência combina com sua arma e sua aceleração, e em que ponto dela você está. Ela avança pelo que você realmente lança e pelos seus golpes.",
    ["Sequence"] = "Sequência",
    ["Automatic follows your attack speed and spell haste, which is what decides how many twists fit between two strikes. Pick one by hand to drill a single sequence."] = "Automática segue sua velocidade de ataque e sua aceleração de magia, que são o que decide quantas trocas cabem entre dois golpes. Escolha uma na mão para treinar uma sequência só.",
    ["Rotation icon size"] = "Tamanho do ícone",
    ["Sound when the twist lands"] = "Som quando a troca acerta",
    ["Hit sound"] = "Som de acerto",
    ["Listen"] = "Ouvir",
    ["Chime"] = "Sino",
    ["Raid warning"] = "Aviso de raide",
    ["Ready check"] = "Verificação de prontidão",
    ["Click"] = "Clique",
    -- Patch notes 1.41.0
    ["Moving a frame could throw a blocked-action error if you happened to be in combat while the frames were built. The keyboard is only taken over once a mover is on screen."] = "Mover uma janela podia gerar um erro de ação bloqueada se você estivesse em combate enquanto as janelas eram construídas. O teclado só é assumido quando um movedor está na tela.",
    ["The trinket window's settings were being written to the saved file a second time under their old names. They are stored once now."] = "As configurações da janela de berloques eram gravadas uma segunda vez no arquivo salvo com os nomes antigos. Agora ficam guardadas uma única vez.",
    ["42 texts existed in German only, among them the whole talent override interface and the trinket queue. All nine languages are complete again."] = "42 textos existiam só em alemão, entre eles toda a interface de substituições de talentos e a fila de berloques. Os nove idiomas estão completos de novo.",
    ["Main positions – Six slots around the plate, each holding one thing: debuffs, buffs, crowd control or your own damage-over-time"] = "Posições principais – Seis espaços em volta da placa, cada um com uma só coisa: perdas, ganhos, controle de grupo ou seus próprios danos ao longo do tempo",
    ["Glow when low on health – A coloured ring once the unit drops past your mark"] = "Brilho com pouca vida – Um anel colorido assim que o alvo cai abaixo da sua marca",
    ["Arrows beside your target – Two arrows pointing in at the bar"] = "Setas ao lado do seu alvo – Duas setas apontando para a barra dos dois lados",
    ["Mark on the focus plate – A short text, so target and focus stay apart at a glance"] = "Marca na placa do foco – Um texto curto para separar alvo e foco num relance",
    ["Preset – One click for a wide, flat, dark look, and one to put the small plates back"] = "Modelo – Um clique para um visual largo, plano e escuro, e outro para voltar às placas pequenas",
    ["Two of the six slots sit beside the plate as a column, which was not possible before. And two rows can no longer land on top of each other: giving a slot something takes it away from the slot that had it."] = "Dois dos seis espaços ficam ao lado da placa como coluna, o que antes não era possível. E duas fileiras não podem mais se sobrepor: o que você coloca em um espaço é retirado de quem o tinha.",
    ["The cast bar can name who the cast is aimed at, your own name coloured."] = "A barra de conjuração pode dizer em quem a magia é lançada, com seu próprio nome colorido.",
    ["Twist zones – The swing bar answers what you may press now instead of counting down"] = "Zonas de troca – A barra de golpe responde o que você pode apertar agora em vez de contar o tempo",
    ["Rotation helper – A short sequence rather than a single next step, worked out from your weapon and cast speed"] = "Ajuda de rotação – Uma sequência curta em vez de um único próximo passo, calculada pela velocidade de arma e de conjuração",
    ["The seal you twist into may be any other seal, not only the two that arrive at level 64."] = "O selo para o qual você troca pode ser qualquer outro selo, não apenas os dois que chegam no nível 64.",
    ["Sections no longer fold away. Long pages fold at the gear on a row instead, which says something a section expander never could: the rows behind it belong to the switch it sits on."] = "As seções não se recolhem mais. Páginas longas se recolhem na engrenagem de uma linha, que diz algo que um recolhimento de seção nunca disse: as linhas atrás dela pertencem ao interruptor em que ela está.",
    ["Controls line up down a page now, and a switch sits in the middle of its row."] = "Os controles ficam alinhados ao longo da página e um interruptor fica no meio da sua linha.",
    -- Vier Nachzuegler
    ["Darken enemies out of combat"] = "Escurecer inimigos fora de combate",
    ["Dims enemies that are not fighting anyone, so the ones that are stand out. Never your own target."] = "Atenua os inimigos que não estão lutando com ninguém, para destacar os que estão. Nunca o seu alvo.",
    ["Darken to (%)"] = "Escurecer para (%)",
    ["Cast bars in front of other plates"] = "Barras de conjuração à frente das outras placas",
    ["In a pull the plates overlap and a cast bar can end up behind the plate in front of it."] = "Num pull as placas se sobrepõem e uma barra de conjuração pode ficar atrás da placa da frente.",
    ["Highlight strength"] = "Intensidade do destaque",
    ["Hitbox width (%)"] = "Largura da área clicável (%)",
    ["Clickable plate area. 100 leaves the game's own size untouched. Stored in the profile."] = "Área clicável da placa. 100 deixa o tamanho do jogo intacto. Fica guardado no perfil.",
    ["Hitbox height (%)"] = "Altura da área clicável (%)",
    -- Wechsel verloren
    -- Gewehrschuss
    ["Rifle"] = "Tiro de rifle",
    -- Aktionszeile
    ["Action text size"] = "Tamanho do texto de ação",
    ["The line that names what to press. 0 follows the general text size."] = "A linha que diz o que apertar. 0 segue o tamanho de texto geral.",
    -- Tempo- und Siegel-Timer-Groesse
    ["Seal timer text size"] = "Tamanho do temporizador do selo",
    ["The countdown on the seal icons. 0 scales it with the icon."] = "A contagem nos ícones de selo. 0 ajusta ao tamanho do ícone.",
    -- Warnzeile
    ["Warning text size"] = "Tamanho do texto de aviso",
    ["The red and yellow warnings on the bar. 0 follows the action text size."] = "Os avisos vermelhos e amarelos na barra. 0 segue o tamanho do texto de ação.",
    -- Bedingungen je Eintrag
    ["Narrows this icon to a number of stacks, or to the last seconds before it runs out."] = "Limita este ícone a um número de acúmulos, ou aos últimos segundos antes de acabar.",
    ["Only from stacks"] = "Apenas a partir de acúmulos",
    ["0 = any number of stacks."] = "0 = qualquer número de acúmulos.",
    ["Only in the last seconds"] = "Apenas nos últimos segundos",
    ["0 = at any time. Otherwise the icon appears only this close to running out."] = "0 = a qualquer momento. Caso contrário o ícone aparece só tão perto de acabar.",
    -- Einheit je Gruppe
    ["Watch this unit"] = "Observar esta unidade",
    ["Whose auras this group reads. The default is what the group type has always used."] = "De quem este grupo lê as auras. O padrão é o que o tipo de grupo sempre usou.",
    ["You"] = "Você",
    ["Target"] = "Alvo",
    ["Focus"] = "Foco",
    -- Nur eigene Auren
    ["Only what I cast myself"] = "Apenas o que eu mesmo lanço",
    ["Off counts the aura no matter who put it there - for a raid debuff that anyone may apply."] = "Desligado conta a aura independentemente de quem a colocou — para um efeito de raide que qualquer um pode aplicar.",
    -- Sortierung
    ["Fixed keeps the order you added them in. The other two reorder live by what is left."] = "Fixo mantém a ordem em que você os adicionou. Os outros dois reordenam ao vivo pelo tempo restante.",
    ["As added"] = "Como foram adicionados",
    ["Least time left first"] = "Menor tempo restante primeiro",
    ["Most time left first"] = "Maior tempo restante primeiro",
    ["Practice"] = "Prática",
    ["|cffaaaaaaA swing clock that runs on its own, with no target and nothing spent. Press your bound keys against it and every swing is graded: the twist landed, it was too early, or nothing was attempted. The seal model is the real one -- a replaced seal keeps resolving for 0.4 seconds -- so the timing you learn here is the timing that works.|r"] = "|cffaaaaaaUm relógio de golpe que corre sozinho, sem alvo e sem gastar nada. Pressione suas teclas contra ele e cada golpe recebe uma nota: o twist deu certo, foi cedo demais ou nada foi tentado. O modelo de selos é o real -- um selo substituído continua resolvendo por 0,4 segundos -- então o tempo que você aprende aqui é o tempo que funciona.|r",
    ["Start / stop practice"] = "Iniciar / parar prática",
    ["Stop practice"] = "Parar prática",
    ["Simulated weapon speed"] = "Velocidade de arma simulada",
    ["0 uses whatever you have equipped. Any other value drills a speed you do not own yet, which is how you find out that the weapon you are saving for needs a different sequence."] = "0 usa o que você tiver equipado. Qualquer outro valor treina uma velocidade que você ainda não possui, que é como se descobre que a arma pela qual você está juntando ouro pede uma sequência diferente.",
    ["Spell queue window (ms)"] = "Janela de fila de magias (ms)",
    ["A key pressed this far before the global cooldown ends is held and fires the moment it does, exactly as the client does it. Practising without it teaches a rhythm the game never asks for."] = "Uma tecla pressionada até este tanto antes de a recarga global terminar fica retida e dispara no instante em que ela acaba, exatamente como o cliente faz. Praticar sem isso ensina um ritmo que o jogo nunca pede.",
    ["Result text size"] = "Tamanho do texto de resultado",
    ["Result text duration (seconds)"] = "Duração do texto de resultado (segundos)",
    ["Landed colour"] = "Cor de acerto",
    ["Missed colour"] = "Cor de erro",
    ["Show the fight timeline"] = "Exibir a linha do tempo do combate",
    ["Every swing and every cast on one strip against a ruler. The ruler is the point: without it you can see that two swings were close together but not how close, which is the only number practice is about."] = "Cada golpe e cada conjuração numa única faixa, sobre uma régua. A régua é o ponto: sem ela você vê que dois golpes ficaram próximos, mas não o quanto, e esse é o único número de que a prática trata.",
    ["Timeline width"] = "Largura da linha do tempo",
    ["Timeline pixels per second"] = "Pixels por segundo da linha do tempo",
    ["TWIST"] = "TWIST",
    ["MISS"] = "ERRO",
    ["TOO EARLY"] = "CEDO DEMAIS",
    ["speed %.2fs  -  GCD %.2fs  -  %d of %d"] = "veloc. %.2fs  -  GCD %.2fs  -  %d de %d",
    ["|cffffffffPRACTICE|r"] = "|cffffffffPRÁTICA|r",
    ["|cffffffffRESULT|r"] = "|cffffffffRESULTADO|r",
    ["|cffffffffTIMELINE|r"] = "|cffffffffLINHA DO TEMPO|r",
    ["|cffffcc33Twist practice|r"] = "|cffffcc33Prática de twist|r",
    ["Practice needs two seals: pick them under Seals first."] = "A prática precisa de dois selos: escolha-os em Selos primeiro.",
    ["Practice mode on. Press your bound keys; the swing runs on its own."] = "Modo de prática ligado. Pressione suas teclas; o golpe corre sozinho.",
    ["Practice mode off. %d of %d swings carried the twist."] = "Modo de prática desligado. %d de %d golpes levaram o twist.",
    ["Bloodlust"] = "Sede de Sangue",
    ["Haste potion"] = "Poção de aceleração",
    ["Abacus"] = "Ábaco",
    ["Time warp"] = "Distorção temporal",
    ["Crusader Strike"] = "Golpe do Cruzado",
    ["Judgement"] = "Julgamento",
    ["Cast the held seal"] = "Conjurar o selo mantido",
    ["Cast the twist seal"] = "Conjurar o selo do twist",
    ["Filler"] = "Preenchimento",
    ["Start / stop attack"] = "Iniciar / parar ataque",
    ["wait"] = "aguardar",
    ["Next action"] = "Próxima ação",
    ["|cffffffffNEXT ACTION|r"] = "|cffffffffPRÓXIMA AÇÃO|r",
    ["Next action mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Movedor da próxima ação ativo. |cff9b6cffArraste a caixa roxa|r ou use as |cff9b6cffteclas de seta|r (SHIFT = 5px). Clique em 'Destravar / Testar' novamente para concluir.",
    ["Next action mover disabled."] = "Movedor da próxima ação desativado.",
    ["|cffaaaaaaAn icon of the one thing to press, wherever you want it. It answers the same question as the line under the bar -- the three switches below feed both, so the word and the picture can never disagree.|r"] = "|cffaaaaaaUm ícone da única coisa a pressionar, onde você quiser. Ele responde à mesma pergunta que a linha embaixo da barra -- os três interruptores abaixo alimentam os dois, então a palavra e a imagem nunca podem se contradizer.|r",
    ["Show the next action guide"] = "Exibir o guia de próxima ação",
    ["When to show it"] = "Quando exibi-lo",
    ["Show a hold instead of nothing"] = "Exibir uma espera em vez de nada",
    ["While the right move is to press nothing on purpose -- the twist is coming and anything else would cost it -- the guide keeps showing the seal, drained and outlined. An empty box says the same thing much less clearly."] = "Enquanto a jogada certa for não pressionar nada de propósito -- o twist está chegando e qualquer outra coisa o custaria -- o guia continua mostrando o selo, esmaecido e contornado. Uma caixa vazia diz a mesma coisa de forma muito menos clara.",
    ["Suggest Judgement"] = "Sugerir Julgamento",
    ["Judging consumes the seal, so it is only ever offered with room to re-seal afterwards. Off by default: a mistimed judgement costs more than no suggestion at all."] = "Julgar consome o selo, então ele só é oferecido quando há espaço para selar de novo depois. Desligado por padrão: um julgamento na hora errada custa mais do que sugestão nenhuma.",
    ["Suggest a filler"] = "Sugerir um preenchimento",
    ["Consecration, or Exorcism where the target can take it, in the stretch of the swing that is free for it. Exorcism is offered by asking the client whether the spell can be aimed at your target, which is right in every language."] = "Consagração, ou Exorcismo onde o alvo puder recebê-lo, no trecho do golpe que está livre para isso. Exorcismo é oferecido perguntando ao cliente se a magia pode ser mirada no seu alvo, o que está certo em qualquer idioma.",
    ["Consecration mana floor (%)"] = "Piso de mana para Consagração (%)",
    ["Below this share of your mana the filler is not worth it."] = "Abaixo desta fração da sua mana o preenchimento não compensa.",
    ["Exorcism mana floor (%)"] = "Piso de mana para Exorcismo (%)",
    ["Longest Crusader Strike delay (ms)"] = "Maior atraso do Golpe do Cruzado (ms)",
    ["Once leaving the strike any longer than this would waste it, it stops being a suggestion and becomes the answer. Measured against the earliest moment you could actually cast it, not against now."] = "Assim que segurar o golpe por mais tempo que isso passar a desperdiçá-lo, ele deixa de ser uma sugestão e vira a resposta. Medido a partir do primeiro instante em que você poderia realmente conjurá-lo, não a partir de agora.",
    ["Twist!"] = "Twist!",
    ["|cffffffffTWIST TEXT|r"] = "|cffffffffTEXTO DO TWIST|r",
    ["Twist text mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Movedor do texto do twist ativo. |cff9b6cffArraste a caixa roxa|r ou use as |cff9b6cffteclas de seta|r (SHIFT = 5px). Clique em 'Destravar / Testar' novamente para concluir.",
    ["Twist text mover disabled."] = "Movedor do texto do twist desativado.",
    ["Twist landed"] = "Twist concluído",
    ["|cffaaaaaaAll three cues below wait for PROOF, not for a prediction. A swing has to land with both seals up, and the held seal's own damage has to follow it in the combat log. Nothing fires without that second line -- a confirmation that is right most of the time is one you cannot practise against.|r"] = "|cffaaaaaaOs três avisos abaixo esperam por PROVA, não por previsão. Um golpe precisa acertar com os dois selos ativos, e o dano do próprio selo mantido precisa vir logo depois no registro de combate. Nada dispara sem essa segunda linha -- uma confirmação que acerta na maior parte das vezes é uma contra a qual você não consegue praticar.|r",
    ["Sound channel"] = "Canal de som",
    ["Master"] = "Principal",
    ["Sound effects"] = "Efeitos sonoros",
    ["Master ignores the sound effects slider, which is what a confirmation wants: it is feedback about the fight rather than part of it."] = "Principal ignora o controle de efeitos sonoros, que é o que uma confirmação quer: ela é um retorno sobre o combate, e não parte dele.",
    ["The sniper and rifle cracks are bundled; the rest are the client's own cues. Below them stand any sounds other addons have registered as shared media."] = "Os estalos de franco-atirador e de rifle vêm junto; o resto são avisos do próprio cliente. Abaixo deles ficam os sons que outros AddOns registraram como mídia compartilhada.",
    ["Sniper"] = "Franco-atirador",
    ["Level up"] = "Subir de nível",
    ["Quest complete"] = "Missão concluída",
    ["Bonus objective"] = "Objetivo bônus",
    ["Map ping"] = "Sinal no mapa",
    ["Glow on the bar when the twist lands"] = "Brilho na barra quando o twist dá certo",
    ["Glow style"] = "Estilo de brilho",
    ["Pixel border"] = "Borda de pixel",
    ["Autocast ring"] = "Anel de conjuração automática",
    ["Pixel border traces the bar's own outline at any width. Autocast pins the client's own ring to the four corners, so it stays a ring however wide the bar gets."] = "Borda de pixel traça o contorno da própria barra em qualquer largura. Conjuração automática prende o anel do próprio cliente aos quatro cantos, então ele continua sendo um anel por mais larga que a barra fique.",
    ["Glow colour"] = "Cor do brilho",
    ["Glow duration (seconds)"] = "Duração do brilho (segundos)",
    ["Text when the twist lands"] = "Texto quando o twist dá certo",
    ["A line somewhere on screen, with its own position. Useful where the bar is in the corner of the eye and the confirmation should be in the middle of it."] = "Uma linha em algum lugar da tela, com posição própria. Útil quando a barra fica no canto do olho e a confirmação deveria estar no meio dele.",
    ["Text font"] = "Fonte do texto",
    ["Text outline"] = "Contorno do texto",
    ["Text colour"] = "Cor do texto",
    ["Text duration (seconds)"] = "Duração do texto (segundos)",
    ["|cffffffffSEALS|r"] = "|cffffffffSELOS|r",
    ["Seal indicator mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Movedor do indicador de selos ativo. |cff9b6cffArraste a caixa roxa|r ou use as |cff9b6cffteclas de seta|r (SHIFT = 5px). Clique em 'Destravar / Testar' novamente para concluir.",
    ["Seal indicator mover disabled."] = "Movedor do indicador de selos desativado.",
    ["Match the bar height"] = "Acompanhar a altura da barra",
    ["Sizes the icons to the bar instead of to their own setting, so the pair keeps lining up with it when the bar height changes."] = "Dimensiona os ícones pela barra em vez de pelo ajuste próprio deles, para que o par continue alinhado com ela quando a altura da barra mudar.",
    ["Ignored while the icons match the bar height."] = "Ignorado enquanto os ícones acompanham a altura da barra.",
    ["Seal icon spacing"] = "Espaçamento dos ícones de selo",
    ["Centre the icons"] = "Centralizar os ícones",
    ["Keeps the midpoint of the pair still when the second seal appears or falls off. Left-aligned keeps the first icon still instead, which is what an attached pair wants -- that edge is the bar."] = "Mantém o ponto central do par parado quando o segundo selo aparece ou cai. Alinhado à esquerda mantém parado o primeiro ícone, que é o que um par acoplado quer -- aquela borda é a barra.",
    ["Show the cooldown sweep"] = "Exibir a varredura de recarga",
    ["The client's own sweep across the icon. It says the same thing as the number under it, but it says it without being read."] = "A varredura do próprio cliente sobre o ícone. Ela diz a mesma coisa que o número abaixo dela, mas diz sem precisar ser lida.",
    ["Seal timer colour"] = "Cor do cronômetro de selo",
    ["Detach from the bar"] = "Desacoplar da barra",
    ["Gives the pair its own position anywhere on screen. They stay tied to the bar in every other way: when it is hidden, they are too."] = "Dá ao par uma posição própria em qualquer lugar da tela. Eles continuam presos à barra em todo o resto: quando ela está oculta, eles também estão.",
    ["Twist lost"] = "Twist perdido",
    ["Swing ready -- restart your attack"] = "Golpe pronto -- reinicie seu ataque",
    ["(none available)"] = "(nenhum disponível)",
    ["Solid"] = "Sólido",
    ["Attack speed"] = "Velocidade de ataque",
    ["Swing timer"] = "Cronômetro de golpe",
    ["Latency (ms)"] = "Latência (ms)",
    ["Global cooldown left"] = "Recarga global restante",
    ["Nothing"] = "Nada",
    ["Left readout"] = "Leitura à esquerda",
    ["What the left end of the bar shows. Attack speed turns into the warning colour below two global cooldowns per swing -- under that the twist and the seal going back up no longer both fit, so wait for the cooldown before twisting."] = "O que a extremidade esquerda da barra mostra. A velocidade de ataque assume a cor de aviso abaixo de duas recargas globais por golpe -- abaixo disso o twist e o selo voltando não cabem mais juntos, então espere a recarga antes de fazer twist.",
    ["Right readout"] = "Leitura à direita",
    ["Readout text size"] = "Tamanho do texto das leituras",
    ["The two numbers inside the bar. 0 follows the general text size."] = "Os dois números dentro da barra. 0 acompanha o tamanho geral do texto.",
    ["Global cooldown bar texture"] = "Textura da barra de recarga global",
    ["Border"] = "Borda",
    ["Solid draws four flat edges in the colour below. Texture takes an edge file from shared media, which is what a border from another interface pack looks like."] = "Sólido desenha quatro bordas lisas na cor abaixo. Textura pega um arquivo de borda da mídia compartilhada, que é a aparência de uma borda vinda de outro pacote de interface.",
    ["Only used while the border is set to texture."] = "Usado apenas enquanto a borda estiver definida como textura.",
    ["Border width"] = "Largura da borda",
    ["Marker texture"] = "Textura do marcador",
    ["Marker width"] = "Largura do marcador",
    ["Font colour"] = "Cor da fonte",
    ["Frame strata"] = "Estrato do quadro",
    ["Which layer of the interface the helper sits in. Raise it to lift the bar over another addon that draws in the same place."] = "Em qual camada da interface o assistente fica. Aumente para levantar a barra acima de outro AddOn que desenha no mesmo lugar.",
    ["Draw level"] = "Nível de desenho",
    ["The order inside the chosen layer. Higher draws on top."] = "A ordem dentro da camada escolhida. Mais alto desenha por cima.",
    ["Colour the bar by"] = "Colorir a barra por",
    ["The zone the swing is in"] = "A zona em que o golpe está",
    ["The seal you are carrying"] = "O selo que você está carregando",
    ["Zones colour the fill by the stretch of the swing you are in, which is what this helper is built around. Seal colours it by what you are carrying, which is the faster read once the timing is in your fingers. Either way the special colours below outrank the choice."] = "Zonas colorem a barra pelo trecho do golpe em que você está, que é o eixo em torno do qual este assistente foi feito. Selo a colore pelo que você está carregando, que é a leitura mais rápida quando o tempo já está nos seus dedos. De qualquer forma, as cores especiais abaixo têm precedência sobre a escolha.",
    ["Seal of Command"] = "Selo de Comando",
    ["Seal of Righteousness"] = "Selo de Retidão",
    ["Seal of Blood / the Martyr"] = "Selo de Sangue / do Mártir",
    ["Seal of Vengeance"] = "Selo de Vingança",
    ["Seal of the Crusader"] = "Selo do Cruzado",
    ["Seal of Justice"] = "Selo de Justiça",
    ["Seal of Light"] = "Selo da Luz",
    ["Seal of Wisdom"] = "Selo de Sabedoria",
    ["No twist possible"] = "Nenhum twist possível",
    ["The fill while this swing's twist is already gone, and the tail of the swing a cast can no longer reach."] = "A cor da barra enquanto o twist deste golpe já se perdeu, e a cauda do golpe que uma conjuração não alcança mais.",
    ["Warning"] = "Aviso",
    ["The warnings on the bar, and the attack speed once the weapon is too fast to twist with."] = "Os avisos na barra, e a velocidade de ataque quando a arma fica rápida demais para fazer twist.",
    ["Twisting"] = "Twist em curso",
    ["The fill while both seals are up: the twist is in and this swing carries it."] = "A cor da barra enquanto os dois selos estão ativos: o twist está feito e este golpe o leva.",
    ["Default"] = "Padrão",
    ["The fill with no seal up and between swings."] = "A cor da barra sem nenhum selo ativo e entre golpes.",
    ["Global cooldown"] = "Recarga global",
    ["Deadzone"] = "Zona morta",
    ["Twist window padding"] = "Margem da janela de twist",
    ["Pulls the twist window earlier so the cast still reaches the server inside it. Dynamic follows your calibrated latency; fixed is a number you choose yourself."] = "Puxa a janela de twist para mais cedo, para que a conjuração ainda chegue ao servidor dentro dela. Dinâmica acompanha sua latência calibrada; fixa é um número que você mesmo escolhe.",
    ["Fixed twist padding (ms)"] = "Margem fixa do twist (ms)",
    ["Only used while the padding mode is set to fixed."] = "Usado apenas enquanto o modo de margem estiver definido como fixo.",
    ["Dynamic (follows latency)"] = "Dinâmica (acompanha a latência)",
    ["Fixed"] = "Fixa",
    ["Latency"] = "Latência",
    ["|cffaaaaaaThe round trip your client reports is not the delay a twist has to beat: the client adds a slice of its own, so the figure everything below works from is (world latency x multiplier) + offset. Raise the multiplier if you keep missing twists that looked in time.|r"] = "|cffaaaaaaO tempo de ida e volta que seu cliente informa não é o atraso que um twist precisa vencer: o cliente acrescenta uma fatia própria, então o valor com que tudo abaixo trabalha é (latência do mundo x multiplicador) + deslocamento. Aumente o multiplicador se você continuar errando trocas que pareciam estar no tempo certo.|r",
    ["Latency multiplier"] = "Multiplicador de latência",
    ["Latency offset (ms)"] = "Deslocamento de latência (ms)",
    ["Shade the deadzone"] = "Sombrear a zona morta",
    ["The tail of the swing a cast can no longer cross, shaded at the end of the bar. Its size follows your raw world latency rather than the calibrated figure, because this one is the wire and not a prediction. This switch only draws it -- the timing itself always accounts for it, so set the scale to 0 if you want no compensation at all."] = "A cauda do golpe que uma conjuração não consegue mais cruzar, sombreada no fim da barra. O tamanho dela segue sua latência bruta do mundo em vez do valor calibrado, porque esta aqui é o fio e não uma previsão. Este interruptor apenas a desenha -- o cálculo do tempo sempre a leva em conta, então defina a escala como 0 se você não quiser compensação nenhuma.",
    ["Deadzone scale"] = "Escala da zona morta",
    ["Multiplies your world latency. Raise it if you cannot twist just outside the shaded stretch, lower it if you still can inside it. 0 switches the compensation off entirely."] = "Multiplica sua latência do mundo. Aumente se você não conseguir fazer twist logo fora do trecho sombreado, diminua se você ainda conseguir dentro dele. 0 desliga a compensação por completo.",
    ["Deadzone texture"] = "Textura da zona morta",
    ["Deadzone transparency"] = "Transparência da zona morta",
    ["Global cooldown padding"] = "Margem da recarga global",
    ["Pulls the global cooldown boundary earlier by part of your latency, so a cast started right at the mark still clears the cooldown in time."] = "Puxa o limite da recarga global para mais cedo por uma parte da sua latência, para que uma conjuração iniciada bem na marca ainda saia da recarga a tempo.",
    ["Fixed global cooldown padding (ms)"] = "Margem fixa da recarga global (ms)",
    ["Show the judgement mark"] = "Exibir a marca de julgamento",
    ["A fourth line where Judgement comes off cooldown during this swing, so a judgement can be put in front of the twist instead of on top of it. Only drawn while a seal is up."] = "Uma quarta linha onde o Julgamento sai da recarga durante este golpe, para que um julgamento possa ser colocado antes do twist em vez de em cima dele. Desenhada apenas enquanto houver um selo ativo.",
    ["Show the global cooldown bar"] = "Exibir a barra de recarga global",
    ["A strip along the bottom of the bar reaching to the moment the global cooldown frees up, so you can see how much of this swing is already spoken for."] = "Uma faixa ao longo da base da barra que vai até o instante em que a recarga global libera, para você ver o quanto deste golpe já está comprometido.",
    ["Global cooldown bar height"] = "Altura da barra de recarga global",
    ["When to show the bar"] = "Quando exibir a barra",
    ["Always keeps it on screen, which is the easier way to practise the timing on a dummy. Seal active shows it whenever you are carrying a seal, in or out of a fight."] = "Sempre mantém a barra na tela, que é o jeito mais fácil de praticar o tempo num boneco de treino. Selo ativo a exibe sempre que você estiver carregando um selo, dentro ou fora de combate.",
    ["Seal active"] = "Selo ativo",
    ["In combat or seal active"] = "Em combate ou selo ativo",
    ["Only with Two-Handed Weapon Specialization"] = "Somente com Especialização em Armas de Duas Mãos",
    ["Hides the helper unless you have a point in the talent. Twisting works without it, but the slow swing it is built around is what makes the whole habit pay."] = "Oculta o assistente a menos que você tenha um ponto no talento. O twist funciona sem ele, mas o golpe lento em torno do qual ele foi construído é o que faz todo o hábito valer a pena.",
    ["Neck"] = "Pescoço",
    ["Shoulder"] = "Ombros",
    ["Waist"] = "Cintura",
    ["Legs"] = "Pernas",
    ["Wrist"] = "Pulsos",
    ["Hands"] = "Mãos",
    ["Finger 2"] = "Dedo 2",
    ["Trinket 2"] = "Berloque 2",
    ["Off Hand"] = "Mão Secundária",
    ["Ranged"] = "À Distância",
    -- Patch notes 1.42.0
    ["Practice – A swing clock that runs on its own, with your own keys and a verdict on every swing"] = "Prática – Um relógio de golpe que corre sozinho, com suas próprias teclas e uma nota em cada golpe",
    ["Next action – An icon of the one thing to press, wherever you put it"] = "Próxima ação – Um ícone da única coisa a pressionar, onde você quiser",
    ["Latency – Calibrate the delay a twist has to beat, with its own multiplier and offset"] = "Latência – Calibre o atraso que um twist precisa vencer, com multiplicador e deslocamento próprios",
    ["Shade the deadzone – The tail of the swing a cast can no longer cross"] = "Sombrear a zona morta – A cauda do golpe que uma conjuração não consegue mais atravessar",
    ["Show the global cooldown bar – A strip reaching to the moment the cooldown frees up"] = "Exibir a barra de recarga global – Uma faixa até o momento em que a recarga fica livre",
    ["When to show the bar – Always, in combat, while a seal is up, or either"] = "Quando exibir a barra – Sempre, em combate, enquanto houver um selo ativo, ou ambos",
    ["Colour the bar by – The zone the swing is in, or the seal you are carrying"] = "Colorir a barra por – A zona em que o golpe está, ou o selo que você carrega",
    ["Detach from the bar – The seal icons take their own position, with a cooldown sweep"] = "Desacoplar da barra – Os ícones de selo assumem posição própria, com varredura de recarga",
    ["Suggest Judgement – Offered only with room to re-seal afterwards, and off until you ask"] = "Sugerir Julgamento – Oferecido só se sobrar espaço para selar de novo, e desligado até você pedir",
    ["Textures, border, font, frame layer, marker width and the two readouts inside the bar are yours to set, and every seal has its own colour."] = "Texturas, borda, fonte, camada do quadro, largura dos marcadores e os dois indicadores dentro da barra são seus para ajustar, e cada selo tem a própria cor.",
    -- Patch notes 1.42.0
    ["The twist is now called twist in every language, the word paladins use themselves. German called it Siegelwechsel; the helper and its window are named after the twist instead."] = "O twist se chama twist em todos os idiomas, a palavra que os próprios paladinos usam. Em alemão era Siegelwechsel; o assistente e sua janela agora levam o nome do twist.",
    ["The cue for a landed twist no longer guesses. It used to fire the moment a seal went out inside the window, which is a prediction the server can disagree with. Now the combat log has to show a swing landing with both seals up and the held seal's own damage behind it. Without that, nothing sounds."] = "O aviso de um twist bem-sucedido não adivinha mais. Antes disparava assim que um selo saía dentro da janela, uma previsão com a qual o servidor pode discordar. Agora o registro de combate precisa mostrar um golpe acertando com os dois selos ativos e, atrás dele, o dano do próprio selo mantido. Sem isso, nada toca.",
    -- Patch notes 1.42.0
    ["Switching the module off used to leave the bag bar, the latency bar and Action Bar 1's twelve buttons behind until a /reload. All three come back on their own now."] = "Desligar o módulo deixava para trás a barra de bolsas, a de latência e os doze botões da Barra de ação 1 até um /reload. Agora as três voltam sozinhas.",
    ["Rows that span the page now start their control where their neighbours do, instead of each sizing its own label."] = "As linhas que ocupam a largura toda começam seu controle onde as vizinhas começam, em vez de cada uma medir o próprio rótulo.",
    -- Patch notes 1.42.0
    ["Watch this unit – A group can follow your target, your focus or your pet instead of you"] = "Observar esta unidade – Um grupo pode seguir seu alvo, seu foco ou seu companheiro em vez de você",
    ["Only what I cast myself – A group can require the aura to be your own, not anyone's"] = "Apenas o que eu mesmo lanço – Um grupo pode exigir que a aura seja sua e não de qualquer um",
    ["Order – Sort a group by the time left instead of the order you added things in"] = "Ordem – Ordenar um grupo pelo tempo restante em vez da ordem em que você o preencheu",
    ["Conditions belong to the individual entry now, not only to the kind of group it sits in. One entry can ask for a stack count or for the last few seconds while its neighbours ask for nothing."] = "As condições pertencem agora à entrada individual, não apenas ao tipo de grupo em que ela está. Uma entrada pode pedir uma contagem de acúmulos ou os últimos segundos enquanto as vizinhas não pedem nada.",
    ["Cast bars in front of other plates – So the cast you are watching is not hidden behind the plate beside it"] = "Barras de conjuração à frente das outras placas – Para que a conjuração que você acompanha não fique escondida atrás da placa ao lado",
    ["Darken enemies out of combat – With its own strength, so an idle mob reads as idle at a glance"] = "Escurecer inimigos fora de combate – Com intensidade própria, assim um inimigo parado se lê como parado num relance",
    ["Highlight strength – How far the plate under your cursor lifts out of the row"] = "Intensidade do destaque – O quanto a placa sob seu cursor se levanta da fileira",
    ["The clickable area is measured from the plate now instead of assumed, so the width and height settings land where your cursor really is."] = "A área clicável agora é medida na placa em vez de suposta, então os ajustes de largura e altura caem onde seu cursor realmente está.",
    ["A dropdown with more entries than fit on screen scrolls instead of running off the bottom, and a label that had grown too long fits its row again."] = "Uma lista suspensa com mais entradas do que cabem na tela agora rola em vez de sair por baixo, e um rótulo que ficara comprido demais volta a caber na sua linha.",
    -- Patch notes 1.43.0
    ["Compatibility"] = "Compatibilidade",
    ["The character window stayed empty on clients we had never named. The panel asked whether the client called itself one of two specific versions and refused every other one, including clients that have exactly the frames it needs. It now asks for the one thing it cannot work without. Enchants, sockets and item stats were missing for the same reason and return with it."] = "A janela de personagem ficava vazia em clientes que nunca havíamos nomeado. O painel perguntava se o cliente se dizia uma de duas versões específicas e recusava todas as outras, inclusive as que têm exatamente os quadros de que ele precisa. Agora ele pergunta pela única coisa sem a qual não consegue funcionar. Encantamentos, engastes e atributos de item faltavam pelo mesmo motivo e voltam junto.",
    ["Hit rating, haste rating and spell hit rating appear on Wrath-based clients too. They were tied to a single version by name, although the game there has those stats."] = "Índice de acerto, índice de aceleração e índice de acerto mágico aparecem também em clientes baseados no Wrath. Estavam presos pelo nome a uma única versão, embora o jogo lá tenha esses atributos.",
    ["The stat rows Wrath draws in pages with two dropdowns are hidden underneath our own panel now, instead of showing through it."] = "As linhas de atributos que o Wrath desenha em páginas com dois menus suspensos ficam agora escondidas sob o nosso próprio painel, em vez de transparecerem através dele.",
    ["Titan Reforged – The addon no longer reports itself out of date on the Chinese client, whose build is listed now"] = "Titan Reforged – O addon não se declara mais desatualizado no cliente chinês, cuja versão agora consta na lista",
    ["Version detection falls back to the build number whenever a client reports an identifier we have no name for. Such a client used to end up with every version flag false, which left it worse off than a client with no identifier at all, because that one at least fell back to something."] = "A detecção de versão recorre ao número da compilação sempre que um cliente informa um identificador para o qual não temos nome. Antes, esse cliente terminava com todos os sinalizadores de versão falsos, o que o deixava pior que um cliente sem identificador nenhum, porque esse ao menos recorria a alguma coisa.",
    ["242 texts that nothing in the interface looks up any more are gone from all nine language files, roughly eight percent of each. Renamed settings left them behind: the action bars were given clearer names a while ago and the old entries simply stayed. A check now asks the reverse question after every change, whether every translated text is still in use, so they cannot pile up again."] = "242 textos que nada mais na interface consulta sumiram dos nove arquivos de idioma, cerca de oito por cento de cada um. Foram as configurações renomeadas que os deixaram para trás: há algum tempo as barras de ação ganharam nomes mais claros e as entradas antigas simplesmente ficaram. Uma verificação agora faz a pergunta inversa após cada mudança, se cada texto traduzido ainda é usado, para que não voltem a se acumular.",
    ["Call button – A fifth totem button for the spells that summon a whole saved totem set, shown only to characters who know one"] = "Botão de chamado – Um quinto botão de totem para as magias que invocam um conjunto inteiro de totens salvo, visível apenas para personagens que conheçam alguma",
    ["Icon Strip"] = "Faixa de ícones",
    ["Distance from frame"] = "Distância do quadro",
    ["Spacing between icons"] = "Espaçamento entre os ícones",
    ["Racial, PvP trinket and the DR row sit on the same edge of the frame and are placed one after the other, in that order, outwards from the frame."] = "A habilidade racial, o berloque de PvP e a fila de DR ficam na mesma borda do quadro e são posicionados um após o outro, nessa ordem, para fora.",
    ["Where it sits is set once for all three trackers under Layout, Icon Strip."] = "A posição é definida uma única vez para os três rastreadores em Disposição, Faixa de ícones.",
    ["Gap below each frame. The opponent's pet bar hangs off the bottom of the frame, so a small gap lets it reach into the next one."] = "Espaço abaixo de cada quadro. A barra do lacaio do oponente ultrapassa a parte de baixo do quadro, então um espaço pequeno faz com que ela invada o próximo.",
    ["Arena: racial, PvP trinket and the DR row now share one icon strip; your chosen side was kept."] = "Arena: habilidade racial, berloque de PvP e fila de DR agora compartilham uma única faixa de ícones; o lado que você escolheu foi mantido.",
    ["|cffff5555Arena layout failed:|r %s"] = "|cffff5555Falha na disposição da arena:|r %s",
    ["|cffff5555Arena icon strip error:|r %s"] = "|cffff5555Erro na faixa de ícones da arena:|r %s",
    ["Drag to reorder. Right-click removes it."] = "Arraste para reordenar. Clique com o botão direito para remover.",
    ["That icon is added automatically — switch off auto-tracking to remove it."] = "Esse ícone é adicionado automaticamente — desligue o rastreamento automático para removê-lo.",
    ["Drag to reorder. Right-click an icon to remove it."] = "Arraste para reordenar. Clique com o botão direito em um ícone para removê-lo.",
    ["Nothing in this bar yet. Add a spell or trinket below, or drag one onto the bar."] = "Ainda não há nada nesta barra. Adicione abaixo uma magia ou berloque, ou arraste um para a barra.",
    ["+  New cooldown bar"] = "+  Nova barra de recargas",
    ["+  New buff / proc bar"] = "+  Nova barra de benefícios e procs",
    ["+  New target debuff bar"] = "+  Nova barra de perdas no alvo",
    ["+  New missing-buff reminder"] = "+  Novo lembrete de benefícios ausentes",
    ["Buffs & Procs"] = "Benefícios e procs",
    ["Target debuffs"] = "Perdas no alvo",
    ["Missing buffs"] = "Benefícios ausentes",
    ["New name for this bar"] = "Novo nome para esta barra",
    ["Delete this bar and everything on it?"] = "Excluir esta barra e tudo o que está nela?",
    ["That is the last bar — there has to be one."] = "Essa é a última barra — precisa sobrar uma.",
    ["Drag to reorder bars"] = "Arraste para reordenar as barras",
    ["Rename this bar"] = "Renomear esta barra",
    ["Delete this bar"] = "Excluir esta barra",
    ["Duplicate bar"] = "Duplicar barra",
    ["Copies the selected bar with all entries and layout settings."] = "Copia a barra selecionada com todas as entradas e ajustes de disposição.",
    ["Bar layout"] = "Disposição da barra",
    ["Icon appearance"] = "Aparência dos ícones",
    ["Icon display"] = "Exibição dos ícones",
    ["Movable cooldown bars grouped however you like — procs, defensives, offensives, each with its own look and position."] = "Barras de recarga móveis agrupadas como você quiser — procs, defensivas, ofensivas, cada uma com aparência e posição próprias.",
    ["Which IDs should be shown in tooltips? Some types do not exist on this game version and are ignored (e.g. TraitNodeID, SourceID)."] = "Quais IDs devem aparecer nas dicas? Alguns tipos não existem nesta versão do jogo e são ignorados (ex.: TraitNodeID, SourceID).",
    ["CDM Bars"] = "Barras CDM",
    ["Bug Fixes"] = "Correções de Erros",
    ["Bar Glows"] = "Brilhos da barra",
    ["Click to edit this icon's glow."] = "Clique para editar o brilho deste ícone.",
    ["Click an icon to edit its glow."] = "Clique em um ícone para editar seu brilho.",
    ["Nothing in this bar yet. Add a spell or trinket on the CDM Bars tab first."] = "Ainda não há nada nesta barra. Adicione primeiro uma magia ou berloque na aba Barras CDM.",
    ["|cffaaaaaaEach icon can glow while a buff of yours is active — or missing. Click an icon in the preview above, then add one or more watchers; the first whose condition holds paints the icon.|r"] = "|cffaaaaaaCada ícone pode brilhar enquanto um benefício seu estiver ativo — ou ausente. Clique em um ícone na prévia acima e adicione um ou mais vigias; o primeiro cuja condição valer pinta o ícone.|r",
    ["|cff888888No icon picked yet.|r"] = "|cff888888Nenhum ícone escolhido ainda.|r",
    ["Glows: %s"] = "Brilhos: %s",
    ["Glow when"] = "Brilhar quando",
    ["Buff is active"] = "O benefício está ativo",
    ["Buff is missing"] = "O benefício está ausente",
    ["Action button glow"] = "Brilho de botão de ação",
    ["Pulsing fill"] = "Preenchimento pulsante",
    ["Gold (default)"] = "Ouro (padrão)",
    ["Pick color..."] = "Escolher cor...",
    ["Remove this glow"] = "Remover este brilho",
    ["Watches: %s"] = "Vigia: %s",
    ["Add watcher (buff name / ID)"] = "Adicionar vigia (nome da magia / ID)",
    ["|cffaaaaaaNo watcher yet. Most spells put a buff of the same name on you when used — one click below makes this icon glow while that buff is on you. Or type any other buff into the field.|r"] = "|cffaaaaaaAinda não há vigia. A maioria das magias coloca em você um benefício de mesmo nome ao ser usada — um clique abaixo faz este ícone brilhar enquanto esse benefício estiver em você. Ou digite qualquer outro benefício no campo.|r",
    ["Glow while '%s' is on me"] = "Brilhar enquanto '%s' estiver em mim",
    -- Patch notes 1.44.0
    ["Icon Strip – Racial, trinket and the diminishing-returns row share one edge of the frame in a fixed order, with one set of controls — they can no longer land on top of each other"] = "Faixa de ícones – A habilidade racial, o berloque e a fila de DR dividem uma borda do quadro em ordem fixa, com um só conjunto de controles — eles não podem mais cair um sobre o outro",
    ["The frame layout — order, spacing, grow direction — never actually applied: its hooks were installed before the arena interface had loaded. The frames now report their own moves and the layout follows; during a fight they are protected, so a move mid-round is corrected when it ends."] = "A disposição dos quadros de arena — ordem, espaçamento, direção de crescimento — nunca chegou a valer: seus ganchos eram instalados antes de a interface da arena carregar. Os quadros agora relatam os próprios movimentos e a disposição acompanha; em combate eles são protegidos, e um deslocamento no meio da rodada é corrigido quando ela termina.",
    ["The default gap between frames clears the opponent's pet bar, and the drag box in edit mode covers the whole stack instead of a fixed area."] = "O espaçamento padrão entre os quadros deixa livre a barra do lacaio do oponente, e a caixa de arrasto do modo de edição cobre a pilha inteira em vez de uma área fixa.",
    ["Bar Glows – Any icon can glow while a buff of yours is active or missing: three styles, gold, class or custom color, and one click watches the spell's own buff"] = "Brilhos da barra – Qualquer ícone pode brilhar enquanto um benefício seu estiver ativo ou ausente: três estilos, ouro, cor da classe ou cor própria, e um clique vigia o próprio benefício da magia",
    ["The page is built around a preview that stays put while you scroll: the bar picker with rename, delete and drag-to-reorder on top, under it every icon of the bar at its real size and shape with the real cooldown sweep. Drag reorders, right-click removes."] = "A página é construída em torno de uma prévia que fica parada enquanto você rola: em cima o seletor de barras com renomear, excluir e arrastar para reordenar, embaixo cada ícone da barra em seu tamanho e forma reais com a varredura de recarga real. Arrastar reordena, o clique direito remove.",
    ["The page is split into tabs, and the resource bar moved in as one of them. Spells you add belong to the class that added them and no longer show up on your other characters."] = "A página foi dividida em abas, e a barra de recursos se mudou para dentro como uma delas. As magias que você adiciona pertencem à classe que as adicionou e não aparecem mais nos seus outros personagens.",
    ["The third extra-item slot no longer stretches across the page with its box flung to the far edge."] = "O terceiro compartimento de itens extras não se estica mais pela página inteira com o campo jogado na borda.",
    ["The interface no longer compares itself with the other game version anywhere; a check keeps such wording out for good."] = "A interface não se compara mais em lugar nenhum com a outra versão do jogo; uma verificação mantém esse tipo de redação fora para sempre.",
    ["Modules with several pages show them as a tab row along the top; when the tabs outgrow the row, two arrows page through it instead of wrapping into a second line."] = "Módulos com várias páginas as mostram como uma fileira de abas na borda superior; quando as abas passam da fileira, duas setas a percorrem em vez de quebrar para uma segunda linha.",
    ["The sidebar got shorter: player and target frames, font bars, castbar and cooldown pulse are one entry now, and a new General entry under Reminders collects the former Extras, Character and Bug Fixes rows — the bug fixes as a single tab."] = "A barra lateral encurtou: os quadros de jogador e alvo, as barras de fonte, a barra de lançamento e o pulso de recarga agora são uma entrada só, e uma nova entrada Geral sob Lembretes reúne as antigas fileiras Extras, Personagem e Correções de Erros — as correções como uma única aba.",
    ["Typing into an add field and then clicking the button beside it silently did nothing; the typed text only counted after pressing Enter. Buttons now take the field's text with them."] = "Digitar em um campo de adicionar e clicar no botão ao lado não fazia nada, em silêncio; o texto digitado só contava depois do Enter. Os botões agora levam o texto do campo junto.",
    ["Developer"] = "Desenvolvedor",
    ["Suppress Lua Errors"] = "Ocultar erros de Lua",
    ["Hides the game's own Lua error popup (CVar scriptErrors). Errors still happen and error-collecting addons still see them - they just stop interrupting you."] = "Oculta a janela de erros de Lua do jogo (CVar scriptErrors). Os erros continuam acontecendo e addons que os coletam ainda os veem - eles só param de interromper você.",
    ["Show IDs in Tooltips"] = "Mostrar IDs nas dicas",
    ["Shows spell, item, NPC and other IDs in tooltips. Which ID types appear can be fine-tuned on the Tooltip IDs page in the Extras group."] = "Mostra IDs de feitiços, itens, NPCs e mais nas dicas. Quais tipos de ID aparecem pode ser ajustado na página IDs nas Dicas do grupo Extras.",
    ["Reset All Settings"] = "Redefinir todas as configurações",
    ["Optimize My FPS and Graphics"] = "Otimizar meus FPS e gráficos",
    ["Applies a proven set of graphics settings that noticeably raises FPS while keeping the game looking good - shadows, liquids, ambient occlusion and view distance go down, textures and spell effects stay sharp. Your current values are saved first and the restore button brings them back. Only settings this client knows are touched."] = "Aplica um conjunto comprovado de configurações gráficas que aumenta bastante os FPS mantendo o jogo bonito - sombras, líquidos, oclusão de ambiente e distância de visão caem, texturas e efeitos de feitiços continuam nítidos. Seus valores atuais são salvos antes e o botão de restaurar os traz de volta. Só são alteradas configurações que este cliente conhece.",
    ["Restore My Graphics Settings"] = "Restaurar minhas configurações gráficas",
    ["Returns every graphics setting the optimize button changed to its previous value and removes the backup."] = "Devolve cada configuração gráfica alterada pelo botão de otimizar ao valor anterior e remove o backup.",
    ["Graphics optimized: %d settings applied."] = "Gráficos otimizados: %d configurações aplicadas.",
    ["Graphics settings restored."] = "Configurações gráficas restauradas.",
    ["Fonts & Colors"] = "Fontes e cores",
    ["Global Font"] = "Fonte global",
    ["The font for the whole VuloClassicUI interface. Fonts shared by other addons appear here too.\n\n|cffaaaaaaRequires /reload to apply everywhere.|r"] = "A fonte de toda a interface do VuloClassicUI. Fontes compartilhadas por outros addons também aparecem aqui.\n\n|cffaaaaaaRequer /reload para valer em toda parte.|r",
    ["Outline Mode"] = "Modo de contorno",
    ["Default outline for VuloClassicUI text. Elements with their own outline setting keep it.\n\n|cffaaaaaaRequires /reload to apply everywhere.|r"] = "Contorno padrão dos textos do VuloClassicUI. Elementos com ajuste próprio de contorno o mantêm.\n\n|cffaaaaaaRequer /reload para valer em toda parte.|r",
    ["Apply to All Game Texts"] = "Aplicar a todos os textos do jogo",
    ["Replaces the font of the game's own texts (chat, tooltips, quest log and more) with the global font.\n\n|cffaaaaaaTurning it off requires /reload to restore the original fonts.|r"] = "Substitui a fonte dos textos do próprio jogo (bate-papo, dicas, registro de missões e mais) pela fonte global.\n\n|cffaaaaaaAo desativar, é preciso /reload para restaurar as fontes originais.|r",
    ["Class Colors"] = "Cores de classe",
    ["Resource Colors"] = "Cores de recursos",
    ["Font changed. /reload required to apply it everywhere."] = "Fonte alterada. É preciso /reload para aplicá-la em toda parte.",
    ["Reset to default"] = "Redefinir para o padrão",
    ["Rename..."] = "Renomear...",
    ["Rename loadout '%s'. Enter new name:"] = "Renomear o conjunto “%s”. Novo nome:",
    ["A loadout named '%s' already exists."] = "Já existe um conjunto chamado “%s”.",
    ["Loadout '%s' renamed to '%s'."] = "Conjunto “%s” renomeado para “%s”.",
    -- Patch notes 1.45.0
    ["The item level on equipment links sits after the link now, not inside its brackets. Some clients re-check link text against their own data, and the changed text turned the link into the name of whatever quest carried that number."] = "O nível de item nos vínculos de equipamento agora fica depois do vínculo, não dentro dos colchetes. Alguns clientes reverificam o texto dos vínculos contra os próprios dados, e o texto alterado transformava o vínculo no nome da missão com aquele número.",
    ["A spell no longer shows up on another class just because that class owns a different spell with the same name. Entries respect their class stamp on the bars, and old entries are adopted by spell ID instead of by name."] = "Um feitiço não aparece mais em outra classe só porque ela possui um feitiço diferente com o mesmo nome. As entradas respeitam sua marca de classe nas barras, e as antigas são adotadas pelo identificador do feitiço em vez do nome.",
    ["The bundled media library silently dropped font registrations when no other addon shipped a newer copy of it; the addon font now registers on every install."] = "A biblioteca de mídia incluída descartava em silêncio registros de fontes quando nenhum outro addon trazia uma cópia mais nova; a fonte do addon agora se registra em toda instalação.",
    ["Rename... – In the set's right-click menu and on the sets page; icon, contents and talent binding move along with the name"] = "Renomear... – No menu de clique direito do conjunto e na página de conjuntos; ícone, conteúdo e vínculo de talentos se mudam junto com o nome",
    ["Optimize My FPS and Graphics – A proven set of graphics settings with a one-time backup; the restore button next to it brings your old values back"] = "Otimizar meus FPS e gráficos – Um conjunto comprovado de configurações gráficas com backup único; o botão de restaurar ao lado devolve seus valores antigos",
    ["Fonts & Colors – A new tab: global font with outline mode, optionally for all game texts, plus class and resource colors with a reset on every row"] = "Fontes e cores – Uma aba nova: fonte global com modo de contorno, opcionalmente para todos os textos do jogo, mais cores de classe e de recursos com redefinir em cada linha",
    ["Developer – Suppress Lua errors, switch tooltip IDs and reset all settings from a new section on the General tab"] = "Desenvolvedor – Ocultar erros de Lua, alternar os IDs nas dicas e redefinir todas as configurações, em uma nova seção da aba Geral",
    ["The General tab is organised in sections on a two-column grid like the rest of the window. The new tab ships a texture file: restart the client once after updating, a /reload alone will not show the reset arrows."] = "A aba Geral está organizada em seções sobre uma grade de duas colunas, como o resto da janela. A aba nova traz um arquivo de textura: reinicie o cliente uma vez após atualizar, um /reload sozinho não mostra as setas de redefinir.",
    ["The enlargement stays off on Wrath-based clients (Titan Reforged): their quest log is already the wide two-pane frame, and enlarging it pushed the detail pane into the button row."] = "A ampliação fica desligada em clientes baseados no Wrath (Titan Reforged): o registro de missões deles já é a janela larga de dois painéis, e ampliá-lo empurrava o painel de detalhes para a fileira de botões.",
    ["Long dropdown lists open upwards when there is no room below. They used to run off the bottom edge of the screen, where the last entries could never be scrolled into view."] = "Listas suspensas longas abrem para cima quando não há espaço embaixo. Antes elas passavam da borda inferior da tela, onde as últimas entradas nunca podiam ser vistas.",
    ["On"] = "Ligado",
    ["Select all"] = "Selecionar tudo",
    ["Deselect all"] = "Desmarcar tudo",
    ["Interface layout (window positions and links)"] = "Disposição da interface (posições e vínculos de janelas)",
    ["Fonts & colors (account-wide)"] = "Fontes e cores (conta inteira)",
    ["Also carries your account-wide font and color settings; they apply immediately when the string is imported."] = "Também leva suas configurações de fonte e cor da conta inteira; elas se aplicam imediatamente ao importar a sequência.",
    ["|cffaaaaaaThe export will include %d of %d modules.|r"] = "|cffaaaaaaA exportação incluirá %d de %d módulos.|r",
    ["Nothing selected to export."] = "Nada selecionado para exportar.",
    ["|cffaaaaaaUntick modules to share only a part - a partial string merges onto the importer's active profile.|r"] = "|cffaaaaaaDesmarque módulos para compartilhar só uma parte - uma sequência parcial se funde com o perfil ativo de quem importa.|r",
    ["Standard Action Bars"] = "Barras de ação padrão",
    ["Modern"] = "Moderno",
    ["|cffaaaaaaThe game's own action bars stay in place. Frame style and Dark Mode below come from the Dark Skin module and style Blizzard's buttons directly.|r"] = "|cffaaaaaaAs barras de ação do próprio jogo permanecem. O estilo de moldura e o Modo Escuro abaixo vêm do módulo Dark Skin e estilizam diretamente os botões da Blizzard.|r",
    ["Apply layout to all bars"] = "Aplicar disposição a todas as barras",
    ["Copies this bar's layout - scale, icon size, buttons per row, spacing, direction - to every other bar."] = "Copia a disposição desta barra - escala, tamanho do ícone, botões por fileira, espaçamento, direção - para todas as outras.",
    ["Layout applied to all bars."] = "Disposição aplicada a todas as barras.",
    ["Text sizes"] = "Tamanhos de texto",
    ["Bar Display"] = "Exibição das barras",
    ["Menu, Bags & XP Bar"] = "Menu, bolsas e barra de XP",
    ["|cffaaaaaaOnly active in Modern mode (Bar Display tab).|r"] = "|cffaaaaaaAtivo apenas no modo Moderno (aba Exibição das barras).|r",
    ["Click: layout settings. Right-click: text sizes."] = "Clique: configurações de disposição. Clique direito: tamanhos de texto.",
    ["Bar Animations"] = "Animações das barras",
    ["Tint the pressed state"] = "Tingir o estado pressionado",
    ["Colours the flash a button shows while it is pressed down."] = "Colore o clarão que um botão mostra enquanto está pressionado.",
    ["Tint the hover highlight"] = "Tingir o destaque ao passar o mouse",
    ["Colours the glow a button shows under the mouse."] = "Colore o brilho que um botão mostra sob o mouse.",
    ["Use class colour"] = "Usar cor da classe",
    ["Enable bar background"] = "Ativar fundo da barra",
    ["A flat colour panel behind the bar, sized with it."] = "Um painel de cor sólida atrás da barra, dimensionado com ela.",
    ["Padding"] = "Margem",
    ["Flat (default)"] = "Sólido (padrão)",
    ["Core"] = "Principal",
    ["Opacity"] = "Opacidade",
    ["Durability"] = "Durabilidade",
    ["Talent points"] = "Pontos de talento",
    ["Pulse"] = "Pulsar",
    ["Steady"] = "Constante",
    ["Background"] = "Plano de fundo",
    ["Low"] = "Baixo",
    ["Medium"] = "Médio",
    ["High"] = "Alto",
    ["Dialog"] = "Diálogo",
    ["Click an icon to jump to its settings."] = "Clique em um ícone para ir à sua configuração.",
    ["Middle-click: hide until the next loading screen."] = "Clique do meio: ocultar até a próxima tela de carregamento.",
    ["Nothing to preview: every reminder is switched off."] = "Nada para pré-visualizar: todos os lembretes estão desativados.",
    ["Show effects missing on others"] = "Mostrar efeitos faltando nos outros",
    ["Scans your party or raid for class buffs you could cast and reminds you when someone lacks one."] = "Examina seu grupo ou raide em busca de bônus de classe que você poderia lançar e avisa quando alguém estiver sem um.",
    ["Missing on %s: %s"] = "Faltando em %s: %s",
    ["In raids (minutes)"] = "Em raides (minutos)",
    ["In dungeons (minutes)"] = "Em masmorras (minutos)",
    ["0 uses the global warn threshold."] = "0 usa o limite de aviso global.",
    ["Preferred food"] = "Comida preferida",
    ["Preferred flask or elixir"] = "Frasco ou elixir preferido",
    ["Preferred weapon enhancement"] = "Aprimoramento de arma preferido",
    ["Automatic (best in bags)"] = "Automático (melhor nas bolsas)",
    ["Click to use."] = "Clique para usar.",
    ["Attach reminders to the cursor"] = "Fixar lembretes no cursor",
    ["Shows small copies of the current reminders next to the mouse cursor."] = "Mostra pequenas cópias dos lembretes atuais ao lado do cursor do mouse.",
    ["Helpers"] = "Ajudantes",
    ["Queue countdown, buff minigame helper and class trainer book in one place."] = "Contagem regressiva da fila, ajudante do minijogo de bônus e livro do treinador em um só lugar.",
    ["Open group board"] = "Abrir painel de grupos",
    ["Scans chat for people forming groups and lists them by Classic/TBC instance in a window (/vlfg or the button below)."] = "Varre o bate-papo em busca de pessoas formando grupos e as lista por instância de Classic/TBC em uma janela (/vlfg ou o botão abaixo).",
    ["Show minimap button"] = "Mostrar botão do minimapa",
    ["PvP Settings"] = "Configurações JxJ",
    ["Fullscreen"] = "Tela cheia",
    ["Fullscreen dialog"] = "Diálogo em tela cheia",
    ["Tooltip"] = "Dica de contexto",
    ["Orientation"] = "Orientação",
    ["Horizontal"] = "Horizontal",
    ["Vertical (up)"] = "Vertical (para cima)",
    ["Vertical (down)"] = "Vertical (para baixo)",
    ["Fill opacity"] = "Opacidade do preenchimento",
    ["Below 100 the world shows through the filled part of the bar."] = "Abaixo de 100, o mundo aparece através da parte preenchida da barra.",
    ["The fill fades into a second colour towards its end."] = "O preenchimento se funde a uma segunda cor em direção à sua extremidade.",
    ["Name inside the bar"] = "Nome dentro da barra",
    ["Anchors the name at the left edge inside the health bar instead of above it — the right edge stays free for the health text."] = "Ancora o nome na borda esquerda dentro da barra de vida em vez de acima — a borda direita fica livre para o texto de vida.",
    ["Show plates for enemy pets"] = "Mostrar placas de ajudantes inimigos",
    ["Divider line on the target's bar"] = "Linha divisória na barra do alvo",
    ["Draws a thin vertical line at the given percent of the health bar — an execute marker."] = "Desenha uma linha vertical fina na porcentagem indicada da barra de vida — um marcador de execução.",
    ["Line position (%)"] = "Posição da linha (%)",
    ["Only on your target"] = "Somente no seu alvo",
    ["Spell name"] = "Nome do feitiço",
    ["Colour the last tick"] = "Colorir o último tique",
    ["Show latency text"] = "Mostrar texto de latência",
    ["Vertical"] = "Vertical",
    ["Automatic stacks a side slot as a column and a top or bottom slot as a row."] = "Automático empilha um espaço lateral em coluna e um espaço superior ou inferior em linha.",
    ["Show older versions"] = "Mostrar versões anteriores",
    ["%d broken numeric values were removed from the settings so they can be saved again."] = "%d valores numéricos corrompidos foram removidos das configurações para que possam ser salvas de novo.",
    ["Widen window"] = "Alargar janela",
    ["Extra width for the friends window so long names, notes and zones fit on one line. 0 keeps Blizzard's width."] = "Largura extra para a janela de amigos, para que nomes longos, notas e zonas caibam em uma linha. 0 mantém a largura da Blizzard.",
    ["Classic+ keeps Blizzard's layout with extras. Modern adds the dark chrome and moves all stats into a panel on the right of the character window."] = "Classic+ mantém o layout da Blizzard com extras. Modern adiciona o visual escuro e move todos os atributos para um painel à direita da janela do personagem.",
    ["Overrides the group switch for this entry alone - e.g. to track a buff someone else casts on you."] = "Substitui a opção do grupo só para esta entrada - p. ex. para monitorar um bônus que outra pessoa lança em você.",
    ["Group default"] = "Padrão do grupo",
    ["Anyone's"] = "De qualquer um",
    ["Use conditions"] = "Usar condições",
    ["Unticked parks this entry: it keeps its settings but never shows. The gear holds moving, removing and per-entry settings."] = "Desmarcado deixa esta entrada de reserva: ela mantém as configurações, mas nunca aparece. A engrenagem guarda mover, remover e ajustes individuais.",
    ["Talent Window"] = "Janela de Talentos",
    ["Shows all three talent trees side by side in one window."] = "Mostra as três árvores de talentos lado a lado em uma janela.",
    ["Points left: %d"] = "Pontos restantes: %d",
    ["TALENTS"] = "TALENTOS",
    ["Open Blizzard's talent window"] = "Abrir a janela de talentos da Blizzard",
    ["For glyphs and everything this window does not cover."] = "Para glifos e tudo o que esta janela não cobre.",
    ["|cffaaaaaaAll three talent trees side by side, with live ranks and click-to-learn. Glyphs stay in Blizzard's window, one button away.|r"] = "|cffaaaaaaAs três árvores de talentos lado a lado, com graduações ao vivo e aprendizado por clique. Os glifos ficam na janela da Blizzard, a um botão de distância.|r",
    ["Replace Blizzard's talent window"] = "Substituir a janela de talentos da Blizzard",
    ["Opening talents shows this window instead. Turn it off to get Blizzard's one-tree window back."] = "Abrir os talentos mostra esta janela no lugar. Desative para voltar à janela de uma árvore da Blizzard.",
    ["Open talent window"] = "Abrir janela de talentos",
    ["See-through"] = "Transparência",
    ["Hide the box fill and labels while editing, so you can see the interface you are aligning. The thin borders stay."] = "Oculta o preenchimento e os rótulos das caixas durante a edição para você ver a interface que está alinhando. As bordas finas permanecem.",
    -- Patch notes 1.46.0
    ["Options"] = "Opções",
    ["Talents"] = "Talentos",
    ["The page opens with two modes: Standard keeps Blizzard's bars with the skin rows, Modern runs the addon's own bars with a live preview, a per-bar background, button press and hover tints and an XP bar texture"] = "A página abre com dois modos: Padrão mantém as barras da Blizzard com as linhas de visual, Moderno usa as barras próprias do addon com prévia ao vivo, fundo por barra, tons de clique e de foco nos botões e uma textura para a barra de experiência",
    ["Modern – Third player cast bar style: flat look with name and timer on the bar, plus bar texture, border, a coloured last tick and a latency readout"] = "Moderno – Terceiro estilo da barra de lançamento do jogador: visual plano com nome e tempo na barra, além de textura da barra, borda, um último tique colorido e um indicador de latência",
    ["The options page carries a live preview; clicking its icon or bar jumps to the matching section"] = "A página de opções traz uma prévia ao vivo; clicar no ícone ou na barra leva à seção correspondente",
    ["Enchant and gem displays no longer displace each other on non-English clients, and Chinese enchant text is no longer cut mid-character"] = "As exibições de encantamento e gemas não se deslocam mais uma à outra em clientes não ingleses, e o texto de encantamento chinês não é mais cortado no meio de um caractere",
    ["Tracked entries sit two per row, each with a gear: park an entry without deleting it, move or remove it, set conditions, and override Only what I cast myself for that entry alone"] = "As entradas seguidas ficam duas por linha, cada uma com engrenagem: estacionar uma entrada sem apagá-la, movê-la ou removê-la, definir condições e substituir Apenas o que eu mesmo lanço só para aquela entrada",
    ["See-through – Hides the box fill and labels while editing, so you can see the interface you are aligning"] = "Transparência – Oculta o preenchimento e os rótulos das caixas durante a edição para você ver a interface que está alinhando",
    ["Coordinates appear on the box while dragging or nudging, and the window being snapped to pulses white"] = "Ao arrastar ou ajustar, as coordenadas aparecem na própria caixa, e a janela de encaixe pulsa em branco",
    ["The loot window can be moved on Wrath clients"] = "A janela de saque pode ser movida em clientes Wrath",
    ["Widen window – Extra width so long names, notes and zones fit on one line"] = "Alargar janela – Largura extra para que nomes longos, notas e zonas caibam em uma linha",
    ["The close glyph of every window is larger now"] = "O sinal de fechar de todas as janelas agora é maior",
    ["Three tabs with a pinned live preview, a name-in-bar option and thousands separators on health numbers"] = "Três abas com prévia fixada, uma opção de nome dentro da barra e separadores de milhar nos números de vida",
    ["Gear rows open inside their own column, aura rows align per row, helper tools share one tab, and the pinned page header of the last visited tab is cleared on switching"] = "As linhas de engrenagem abrem dentro da própria coluna, as linhas de auras se alinham por linha, as ferramentas auxiliares compartilham uma aba, e o cabeçalho fixado da última aba visitada é limpo ao trocar",
    ["Only the last five versions build at once; a button loads the older ones"] = "Apenas as últimas cinco versões são montadas de uma vez; um botão carrega as mais antigas",
    ["Orientation, fill opacity, frame strata and a live preview on the options page"] = "Orientação, opacidade do preenchimento, camada do quadro e uma prévia na página de opções",
    ["A profile string can carry a selection: chosen modules, the window layout, talent overrides, and the account-wide fonts and colours"] = "Uma cadeia de perfil pode levar uma seleção: módulos escolhidos, a disposição das janelas, as substituições de talentos e as fontes e cores da conta",
    ["Per-rule switches with class-coloured names, a group scan for missing buffs, preferred food, flask and weapon oil, raid and dungeon thresholds, glow styles, scale and a live preview; middle-click hides a reminder until the next loading screen"] = "Interruptores por regra com nomes nas cores de classe, uma varredura do grupo para bônus ausentes, comida, frasco e óleo de arma preferidos, limites para raide e masmorra, estilos de brilho, escala e uma prévia; o clique do meio oculta um lembrete até a próxima tela de carregamento",
    ["Broken numeric values are removed before saving and reported at the next login. A single such value used to reset every setting of the account to defaults"] = "Valores numéricos corrompidos são removidos antes de salvar e informados no próximo login. Um único valor assim redefinia todas as configurações da conta para o padrão",
    ["Totemic Recall stands as its own button after the elements on Wrath clients"] = "O recolhimento de totens tem botão próprio após os elementos em clientes Wrath",
    ["Talent Window – All three talent trees side by side with live ranks and click-to-learn on Wrath clients; glyphs stay one button away"] = "Janela de Talentos – As três árvores de talentos lado a lado com ranques ao vivo e aprendizado por clique em clientes Wrath; os glifos ficam a um botão",
    ["The string is selected - press Ctrl+C to copy it."] = "A sequência está selecionada: pressione Ctrl+C para copiá-la.",
    ["%d characters"] = "%d caracteres",
    ["Paste the string here with Ctrl+V."] = "Cole a sequência aqui com Ctrl+V.",
    ["String captured - %d characters."] = "Sequência capturada: %d caracteres.",
    ["Partial string: anything missing is taken from your active profile."] = "Sequência parcial: o que faltar é retirado do seu perfil ativo.",
    ["Unticked parts keep your current settings."] = "As partes desmarcadas mantêm suas configurações atuais.",
    ["Profile '%s' imported. Switch to it now and reload the UI?"] = "Perfil '%s' importado. Mudar para ele agora e recarregar a interface?",
    ["Switch and reload"] = "Mudar e recarregar",
    ["Save a backup copy"] = "Salvar uma cópia de segurança",
    ["Creates a dated copy of the active profile as a restore point. Nothing switches - the copy just sits in the profile list."] = "Cria uma cópia datada do perfil ativo como ponto de restauração. Nada é trocado: a cópia apenas fica na lista de perfis.",
    ["Backup '%s' created."] = "Cópia de segurança '%s' criada.",
    ["Go back"] = "Voltar",
    ["Pixel-true plate size"] = "Tamanho da placa em pixels exatos",
    ["Sizes the plates in screen pixels instead of interface units: height 27 is then 27 pixels on any monitor and UI scale."] = "Dimensiona as placas em pixels da tela em vez de unidades da interface: altura 27 vira 27 pixels em qualquer monitor e escala.",
    -- Patch notes 1.47.0
    ["The boxes now cover their window exactly, in the same dark look as the rest of the interface, with the name centred and shown in orange when the window is docked to another one"] = "As caixas agora cobrem exatamente a sua janela, no mesmo visual escuro do resto da interface, com o nome centralizado e em laranja quando a janela está acoplada a outra",
    ["Outside the editor the small drag handle stays, so an unlocked cooldown bar still accepts dropped spells and test previews stay visible"] = "Fora do editor a alça pequena permanece, então uma barra de recargas destravada continua aceitando feitiços arrastados e as prévias de teste ficam visíveis",
    ["The cloak equipment slot was translated with the navigation word for back in six languages and now reads correctly everywhere"] = "O compartimento de equipamento da capa estava traduzido em seis idiomas com a palavra de navegação voltar e agora aparece correto em todo lugar",
    ["Pixel-true plate size – Sizes the plates in screen pixels, so height 27 is 27 pixels on any monitor and interface scale"] = "Tamanho da placa em pixels exatos – Dimensiona as placas em pixels da tela, então altura 27 é 27 pixels em qualquer monitor e escala da interface",
    ["Plate sizes now mean exactly what the sliders say: the game no longer secretly enlarges the target's plate or shrinks distant ones, and the live preview matches the game — making the target larger is now solely the job of the target plate scale option"] = "Os tamanhos das placas agora significam exatamente o que os controles dizem: o jogo não aumenta mais em segredo a placa do alvo nem encolhe as distantes, e a prévia ao vivo bate com o jogo — deixar o alvo maior agora é tarefa exclusiva da opção de escala da placa do alvo",
    ["Save a backup copy – One click keeps a dated copy of the active profile as a restore point"] = "Salvar uma cópia de segurança – Um clique guarda uma cópia datada do perfil ativo como ponto de restauração",
    ["Exporting opens a proper window with the string already selected, and importing shows a preview first: rename the profile and untick the parts you do not want before anything is written"] = "Exportar abre uma janela de verdade com a sequência já selecionada, e importar mostra primeiro uma prévia: renomeie o perfil e desmarque o que não quiser antes de qualquer coisa ser gravada",
    ["Export strings are compressed to a fraction of their old length and fit in a chat message; strings from older versions still import"] = "As sequências de exportação são comprimidas a uma fração do tamanho antigo e cabem em uma mensagem de bate-papo; sequências de versões antigas continuam importando",
    ["On the Wrath client the talent tooltip showed a placeholder instead of the description, and the talent key would open the window but not close it — both fixed"] = "No cliente do Wrath a dica de talento mostrava um marcador no lugar da descrição, e a tecla de talentos abria a janela mas não a fechava — ambos corrigidos",
    ["%s Locked"] = "%s bloqueada",
    ["|cffffffffLOSS OF CONTROL|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffPERDA DE CONTROLE|r\n|cffaaaaaaArraste ou use as setas|r",
    ["%.1f seconds"] = "%.1f segundos",
    ["Loss of control mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Press the button again to finish."] = "Movimentação da perda de controle ativa. |cff9b6cffArraste a caixa roxa|r ou use as |cff9b6cffsetas|r (SHIFT = 5 px). Pressione o botão novamente para terminar.",
    ["Preview"] = "Pré-visualização",
    ["Loss of Control"] = "Perda de controle",
    ["Shows what is controlling you right now -- stun, fear, root, silence, disarm or a school lockout -- with the effect icon, its name and the time left. Where two effects run at once the one that matters is shown large, and the next one as a small icon beside it."] = "Mostra o que está controlando você agora – atordoamento, medo, enraizamento, silêncio, desarme ou uma escola bloqueada – com o ícone do efeito, seu nome e o tempo restante. Quando dois efeitos estão ativos ao mesmo tempo, o mais importante aparece grande e o seguinte como um ícone pequeno ao lado.",
    ["Show loss of control alert"] = "Mostrar aviso de perda de controle",
    ["Show in"] = "Mostrar em",
    ["Arena and battlegrounds"] = "Arenas e campos de batalha",
    ["Arena only"] = "Somente em arenas",
    ["Name font size"] = "Tamanho da fonte do nome",
    ["Timer font size"] = "Tamanho da fonte do tempo",
    ["Background and red lines"] = "Fundo e linhas vermelhas",
    ["Show the next effect"] = "Mostrar o próximo efeito",
    ["Profile changed. Use /reload when you are out of combat."] = "Perfil alterado. Use /reload quando sair do combate.",
    ["Profile keybind"] = "Atalho do perfil",
    ["Switches to this profile outside combat and then asks to reload the UI. Override bindings are restored at login."] = "Muda para este perfil fora de combate e depois pergunta se deseja recarregar a interface. Os atalhos são restaurados ao entrar.",
    ["Use the global font"] = "Usar a fonte global",
    ["Name color"] = "Cor do nome",
    ["Timer color"] = "Cor do tempo",
    ["|cffffffffINTERRUPTS|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffINTERRUPÇÕES|r\n|cffaaaaaaArraste ou use as setas|r",
    ["Interrupt bar mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Press the button again to finish."] = "Movimentação da barra de interrupções ativa. |cff9b6cffArraste a caixa roxa|r ou use as |cff9b6cffsetas|r (SHIFT = 5 px). Pressione o botão novamente para terminar.",
    ["Interrupts"] = "Interrupções",
    ["Watches the combat log for enemy interrupts and starts a cooldown for each one, tracked per caster -- two enemies of the same class get an icon each. The border carries the caster's class colour."] = "Observa o registro de combate em busca de interrupções inimigas e inicia um tempo de recarga para cada uma, separado por conjurador: dois inimigos da mesma classe recebem um ícone cada. A borda carrega a cor de classe do conjurador.",
    ["Show interrupt bar"] = "Mostrar a barra de interrupções",
    ["Show interrupts that are still ready"] = "Mostrar também as interrupções disponíveis",
    ["Timer text on the icons"] = "Texto de tempo nos ícones",
    ["Cooldown swipe on the icons"] = "Varredura de recarga nos ícones",
    ["Only take over the key while a fishing pole is worn"] = "Ocupar a tecla apenas com um caniço equipado",
    ["Without a pole in hand the key keeps whatever you bound it to, so it stays usable outside fishing. A cast already in the water keeps the key. This switches off auto-equipping a pole, which needs the key exactly while none is worn."] = "Sem caniço na mão a tecla mantém o que você atribuiu a ela, continuando útil fora da pesca. Um lançamento já na água mantém a tecla. Isso desliga equipar o caniço automaticamente, porque essa função precisa da tecla justamente quando nenhum está equipado.",
    ["Stand-in for an enemy frame: the side strip is placed by the settings below."] = "Espaço reservado de um quadro inimigo: a faixa lateral é posicionada pelas opções abaixo.",
    -- Patch notes 1.48.0
    ["Options Window"] = "Janela de opções",
    ["Loss of Control – Shows the stun, fear, root, silence or lockout holding you, with its icon, its name and the time left"] = "Perda de controle – Mostra o atordoamento, medo, enraizamento, silêncio ou bloqueio que o prende, com ícone, nome e tempo restante",
    ["Interrupts – Tracks enemy interrupts from the combat log, one icon per caster, bordered in the caster's class colour"] = "Interrupções – Acompanha as interrupções inimigas pelo registro de combate, um ícone por conjurador, com borda na cor da classe dele",
    ["Timer Text On The Icons – Seconds left on the interrupt icons, with their own font, outline and colour"] = "Texto de tempo nos ícones – Segundos restantes nos ícones de interrupção, com fonte, contorno e cor próprios",
    ["Cooldown Swipe On The Icons – Drop the sweeping shade and keep only the number"] = "Varredura de recarga nos ícones – Tira a sombra que gira e deixa só o número",
    ["The icon strip beside the enemy frames has a live preview on the General tab. Those frames exist only inside an arena, so its sliders used to move something you could not see."] = "A faixa de ícones ao lado dos quadros inimigos tem uma prévia ao vivo na aba Geral. Esses quadros só existem dentro de uma arena, então seus controles moviam algo que você não podia ver.",
    ["An unlocked mover box no longer vanished a moment after the button put it there. The box and a running preview now ignore the zone filter: you place a bar where you are standing, and that is rarely an arena."] = "Uma caixa de movimentação destravada não some mais um instante depois de o botão exibi-la. A caixa e uma prévia em andamento agora ignoram o filtro de zona: você posiciona uma barra onde está, e isso raramente é uma arena.",
    ["The pinned icon strip also appears on the Layout tab, where icon size, spacing, shape and zoom read back off it while the slider moves."] = "A faixa de ícones fixada aparece agora também na aba Layout, onde tamanho, espaçamento, forma e zoom são lidos nela enquanto o controle se move.",
    ["Moving Blizzard frames no longer marks every Edit Mode window as touched by this addon, which had the pet frame refused in combat. Selecting a layout caused it, and that ran on every editor entry even when nothing had been placed."] = "Mover quadros da Blizzard não marca mais cada janela do modo de edição como tocada por este complemento, o que fazia o jogo recusar a exibição do quadro do mascote em combate. A causa era selecionar um layout, e isso acontecia a cada entrada no editor mesmo sem nada ter sido posicionado.",
    ["The icon picker has a close button, and no longer floats over the game after the character sheet is shut."] = "O seletor de ícones tem um botão de fechar e não fica mais flutuando sobre o jogo depois que a ficha do personagem é fechada.",
    ["Only Take Over The Key While A Fishing Pole Is Worn – Without a pole the key keeps whatever you bound it to"] = "Ocupar a tecla apenas com um caniço equipado – Sem caniço a tecla mantém o que você atribuiu a ela",
    ["The mouse wheel scrolls the sidebar and the page. The window also shrinks to fit a screen smaller than itself, which is what left it undraggable on a high interface scale."] = "A roda do mouse rola a barra lateral e a página. A janela também encolhe para caber em uma tela menor que ela, que era justamente o que a deixava impossível de arrastar com uma escala de interface alta.",
    ["Profile Keybind – Put a profile on a key and switch to it out of combat"] = "Atalho do perfil – Coloque um perfil em uma tecla e mude para ele fora de combate",
    ["The bag sweep behind the food, flask and weapon oil reminders is kept until the bags change, instead of walking every bag three times over twice a second."] = "A varredura de bolsas por trás dos lembretes de comida, frasco e óleo de arma é mantida até as bolsas mudarem, em vez de percorrer todas as bolsas três vezes duas vezes por segundo.",
    ["The modern player frame style no longer reaches into the pet and totem frames."] = "O estilo moderno do quadro do jogador não mexe mais nos quadros de mascote e de totem.",
    ["Fine tuning for this slot"] = "Ajuste fino desta posição",
    ["Slot settings"] = "Ajustes da posição",
    ["Border settings"] = "Ajustes da borda",
    ["Border size"] = "Espessura da borda",
    ["How solid the empty part of the bar is."] = "Quão sólida é a parte vazia da barra.",
    ["Absorb settings"] = "Ajustes de absorção",
    ["Border around the cast bar"] = "Borda ao redor da barra de conjuração",
    ["Off leaves the cast bar without its own outline; the health bar keeps one."] = "Desligado deixa a barra de conjuração sem contorno próprio; a barra de vida mantém o dela.",
    ["Top text"] = "Texto superior",
    ["Left text"] = "Texto à esquerda",
    ["Right text"] = "Texto à direita",
    ["Centred text"] = "Texto centralizado",
    ["Unit name"] = "Nome da unidade",
    ["Main text positions"] = "Posições principais de texto",
    ["|cffaaaaaaOne thing per slot. The level rides at the name's left edge and follows it.|r"] = "|cffaaaaaaUma coisa por posição. O nível fica na borda esquerda do nome e o acompanha.|r",
    ["Health and cast bar"] = "Barra de vida e de conjuração",
    ["Health bar width"] = "Largura da barra de vida",
    ["Health bar height"] = "Altura da barra de vida",
    ["Cast icon"] = "Ícone de conjuração",
    ["Cast icon settings"] = "Ajustes do ícone de conjuração",
    ["Cast background"] = "Fundo da conjuração",
    ["Cast bar border"] = "Borda da barra de conjuração",
    ["Thickness of the cast bar's own border. 0 removes it; the health bar keeps its own."] = "Espessura da borda própria da barra de conjuração. 0 a remove; a barra de vida mantém a dela.",
    ["Cast bar border colour"] = "Cor da borda da barra de conjuração",
    ["Cast timer"] = "Cronômetro de conjuração",
    ["Cast timer settings"] = "Ajustes do cronômetro",
    ["Cast bar Y offset"] = "Deslocamento Y da barra de conjuração",
    ["Cast colours and effects"] = "Cores e efeitos de conjuração",
    ["The bar's colour while a spell is being cast."] = "A cor da barra enquanto uma magia é conjurada.",
    ["More cast colours"] = "Mais cores de conjuração",
    ["Interrupt ready"] = "Interrupção pronta",
    ["Interrupt flash"] = "Clarão de interrupção",
    ["Interrupt-ready hint"] = "Aviso: interrupção pronta",
    ["Show cast bars in front of nameplates"] = "Mostrar barras de conjuração à frente das placas",
    ["Casts draw above every plate, so a cast you care about is never hidden behind another unit's bar."] = "As conjurações são desenhadas acima de todas as placas, para que uma conjuração importante nunca fique atrás da barra de outra unidade.",
    ["The enemy's cast bar flashes and reads 'Interrupted' for a moment when their cast is stopped."] = "A barra de conjuração do inimigo pisca e mostra «Interrompido» por um instante quando a magia é parada.",
    ["Interrupt flash settings"] = "Ajustes do clarão de interrupção",
    ["Target, focus and hover effects"] = "Efeitos de alvo, foco e mouse",
    ["Target effect"] = "Efeito de alvo",
    ["A coloured edge around the plate you have targeted."] = "Uma borda colorida ao redor da placa que você tem como alvo.",
    ["Target effect settings"] = "Ajustes do efeito de alvo",
    ["Target arrows"] = "Setas do alvo",
    ["Arrow settings"] = "Ajustes das setas",
    ["Target bar colour on"] = "Ativar cor do alvo",
    ["Focus bar colour on"] = "Ativar cor do foco",
    ["A coloured edge around the plate you have set as your focus."] = "Uma borda colorida ao redor da placa definida como foco.",
    ["Mouseover effect"] = "Efeito ao passar o mouse",
    ["Mouseover effect settings"] = "Ajustes do efeito do mouse",
    ["General text"] = "Texto geral",
    ["Debuff duration"] = "Duração dos debuffs",
    ["Buff duration"] = "Duração dos buffs",
    ["Crowd control duration"] = "Duração do controle",
    ["Aura stacks"] = "Acúmulos de auras",
    ["Timer text colour"] = "Cor do cronômetro",
    ["Stack text colour"] = "Cor dos acúmulos",
    ["Text settings"] = "Ajustes do texto",
    ["Spell target"] = "Alvo da magia",
    ["Background settings"] = "Ajustes do fundo",
    ["Hide the gryphons"] = "Ocultar os grifos",
    ["Removes the two beasts at the ends of Blizzard's main action bar. The bar itself stays."] = "Remove as duas feras nas pontas da barra de ação original. A barra em si permanece.",
    ["Extra indicators"] = "Indicadores adicionais",
    ["Enemy colours"] = "Cores dos inimigos",
    ["Enemy types"] = "Tipos de inimigo",
    ["The health bar colour a unit takes from its reaction to you."] = "A cor que a barra assume conforme a atitude da unidade em relação a você.",
    ["Neutral enemies"] = "Inimigos neutros",
    ["Units that are not hostile until you make them so."] = "Unidades que só ficam hostis quando você as provoca.",
    ["Other nameplates"] = "Outras placas de nome",
    ["Nameplate spacing"] = "Espaçamento das placas",
    ["|cffaaaaaaThe game's own settings, changed live and not part of the profile — except the hitbox. Not changeable in combat.|r"] = "|cffaaaaaaAjustes do próprio jogo, aplicados na hora e fora do perfil — exceto a área de clique. Não podem ser mudados em combate.|r",
    ["Stackable nameplates"] = "Placas empilháveis",
    ["Extra aura options"] = "Opções extras de auras",
    ["Target and focus effects"] = "Efeitos de alvo e foco",
    ["Plate scale while casting"] = "Tamanho da placa ao conjurar",
    ["A casting unit's plate grows to this size, so the one that matters stands out. 100 = off."] = "A placa de uma unidade conjurando cresce até este tamanho, para que a que importa se destaque. 100 = desligado.",
    ["Opacity while casting"] = "Opacidade ao conjurar",
    ["A casting unit's plate is at least this opaque, even when something else is targeted."] = "A placa de uma unidade conjurando mantém ao menos esta opacidade, mesmo com outro alvo selecionado.",
    ["The unit's name gives way to the spell name for as long as the cast runs."] = "O nome da unidade dá lugar ao nome da magia enquanto durar a conjuração.",
    ["Active talent group"] = "Grupo de talentos ativo",
    ["Left-click: show this talent group"] = "Clique esquerdo: mostrar este grupo de talentos",
    ["Right-click: activate this talent group"] = "Clique direito: ativar este grupo de talentos",
    ["Talent group %d (not active)"] = "Grupo de talentos %d (inativo)",
    ["Talents can only be learned in the active talent group."] = "Os talentos só podem ser aprendidos no grupo de talentos ativo.",
    ["Talent groups cannot be switched in combat."] = "Não é possível trocar de grupo de talentos em combate.",
    ["This client refused to switch the talent group."] = "Este cliente recusou a troca de grupo de talentos.",
    ["Input line above the chat"] = "Linha de digitação acima do chat",
    ["Puts the chat input line above the message area instead of below it. The panel and the tab bar follow it."] = "Coloca a linha de digitação acima da área de mensagens em vez de abaixo. O painel e a barra de abas a acompanham.",
    ["Own background for the input line"] = "Fundo próprio para a linha de digitação",
    ["Draws the input line on our own dark background instead of Blizzard's. The dark background panel already covers the input line, so this shows once that panel is off."] = "Desenha a linha de digitação sobre um fundo escuro próprio em vez do da Blizzard. O painel de fundo escuro já cobre a linha de digitação, então isto aparece quando esse painel está desligado.",
    ["Addon buttons"] = "Botões de addons",
    ["Click to show or hide the collected buttons."] = "Clique para mostrar ou ocultar os botões reunidos.",
    ["Where other addons' minimap buttons sit: around the map, hidden until the mouse is over it, or gathered in one box under it."] = "Onde ficam os botões de minimapa de outros addons: ao redor do mapa, ocultos até o mouse passar por cima, ou reunidos numa caixa abaixo.",
    ["Around the minimap"] = "Ao redor do minimapa",
    ["Only on mouseover"] = "Somente ao passar o mouse",
    ["Collected in a box"] = "Reunidos numa caixa",
    -- Patch notes 1.49.0
    ["Hide The Gryphons – Takes the two beasts off the ends of Blizzard's main bar without dimming anything else"] = "Ocultar os grifos – Tira as duas feras das pontas da barra principal da Blizzard sem escurecer mais nada",
    ["Switching the module off now switches it off. Its handlers are registered when the addon loads, so a module that was already off at login never ran its shutdown: being stunned in a battleground still popped the loss-of-control display, and the interrupt bar filled up and never emptied again, because the ticker that clears its icons only starts when the module is switched on."] = "Desligar o módulo agora o desliga de verdade. Seus manipuladores são registrados no carregamento, então um módulo já desligado ao entrar nunca passava pelo desligamento: ficar atordoado num campo de batalha ainda fazia surgir o aviso de perda de controle, e a barra de interrupções enchia e nunca mais esvaziava, porque o temporizador que limpa seus ícones só começa quando o módulo é ligado.",
    ["The interrupt bar no longer reads the whole world's combat log. It registered on load and never unregistered, so every combat line anywhere — several thousand a second in a raid — was taken apart for a bar whose own default is arena and battlegrounds only. It uses the same zone filter as the display beside it now."] = "A barra de interrupções não lê mais o registro de combate do mundo inteiro. Ela se registrava no carregamento e nunca se desregistrava, então cada linha de combate em qualquer lugar — vários milhares por segundo numa raide — era desmontada para uma barra cujo próprio padrão é arena e campos de batalha apenas. Agora usa o mesmo filtro de zona do aviso ao lado.",
    ["Switching the module on inside an arena counts as arriving. The zone decision used to live in the loading screen alone, so anyone who enabled it while already in there got no diminishing-returns ticker until the next one."] = "Ligar o módulo dentro de uma arena conta como chegar. A decisão de zona vivia só na tela de carregamento, então quem o ligava já estando lá dentro não tinha temporizador de efeito decrescente até a próxima.",
    ["The item level text size slider works again. It looked for the numbers in two places it hoped they would be, and where a client parents its paper doll buttons elsewhere it found none and quietly did nothing — which from the outside is indistinguishable from the text simply being too small."] = "O controle de tamanho do texto de nível de item funciona de novo. Ele procurava os números em dois lugares onde esperava encontrá-los, e onde um cliente pendura seus botões de equipamento em outro lugar não encontrava nenhum e não fazia nada em silêncio — o que de fora não se distingue de o texto ser simplesmente pequeno demais.",
    ["Input Line Above The Chat – Puts the input line over the message area instead of under it, with the panel and the tab bar following it; Wrath client only"] = "Linha de digitação acima do chat – Coloca a linha de digitação sobre a área de mensagens em vez de abaixo, e o painel e a barra de abas a acompanham; somente no cliente Wrath",
    ["Own Background For The Input Line – Draws the input line on its own dark background instead of Blizzard's, which is what you saw once the dark panel was off; Wrath client only"] = "Fundo próprio para a linha de digitação – Desenha a linha de digitação sobre um fundo escuro próprio em vez do da Blizzard, que era o que você via depois de desligar o painel escuro; somente no cliente Wrath",
    ["Icon zoom is now called Icon crop and reads in percent. It is the same question the nameplate sliders ask, and it was answering in hundredths while they answered in percent."] = "O zoom do ícone agora se chama corte do ícone e é lido em porcentagem. É a mesma pergunta que os controles das placas de nome fazem, e ela vinha sendo respondida em centésimos enquanto aqueles respondiam em porcentagem.",
    ["The extra width belongs to the friends tab alone now. The row texts there stretch with the window, but the column headers on the who, guild and raid tabs sit at fixed offsets and stay put, so every point of width you added landed in an empty right half. Those three tabs go back to Blizzard's own proportions, which is what their columns were measured for."] = "A largura extra pertence agora somente à aba de amigos. Os textos das linhas ali se esticam com a janela, mas os cabeçalhos de coluna das abas de busca, guilda e raide ficam em posições fixas e não se mexem, então cada ponto de largura acrescentado acabava numa metade direita vazia. Essas três abas voltam às proporções da própria Blizzard, para as quais suas colunas foram medidas.",
    ["The set list and the icon picker take the character panel's style. In the classic style they used to be a flat dark surface with a purple edge holding Blizzard's red buttons — two materials in a hand's width. They now carry Blizzard's dialog frame there and stand in the same material as the window they hang off, while the modern style keeps the flat look."] = "A lista de conjuntos e o seletor de ícones assumem o estilo da janela de personagem. No estilo clássico eram uma superfície escura e chapada com borda roxa segurando os botões vermelhos da Blizzard — dois materiais num palmo. Agora levam ali a moldura de diálogo da Blizzard e ficam no mesmo material da janela em que se apoiam, enquanto o estilo moderno mantém o visual chapado.",
    ["The character panel no longer breaks when the sidebar builds its first set row. The marker bar on the row still reached for an accent colour that had been removed, so the list stayed empty and the panel came up bare."] = "A janela de personagem não quebra mais quando a barra lateral monta sua primeira linha de conjunto. A barra marcadora da linha ainda buscava uma cor de destaque que havia sido removida, então a lista ficava vazia e a janela abria pelada.",
    ["Addon Buttons – Choose where other addons' buttons sit: around the map, hidden until you mouse over it, or gathered in one box below it; Wrath client only"] = "Botões de addons – Escolha onde ficam os botões de outros addons: ao redor do mapa, ocultos até o mouse passar por cima, ou reunidos numa caixa abaixo; somente no cliente Wrath",
    ["Icon Crop (%) – How much of the border the game bakes into its icons is cut away, set per aura row and for the cast bar icon"] = "Corte do ícone (%) – Quanto da borda que o jogo embute em seus ícones é cortado, ajustável por linha de auras e para o ícone da barra de conjuração",
    ["The rounded bar style no longer leaves dead space at both ends. The round shape does not fill its own image — a transparent border runs all the way round it — and stretching that border across a wide, short bar put roughly eleven points of empty bar at each end and barely one above and below, which is why it showed up sideways and not upright."] = "O estilo de barra arredondada não deixa mais espaço morto nas duas pontas. A forma redonda não preenche a própria imagem — uma borda transparente corre em volta dela toda —, e esticar essa borda sobre uma barra larga e baixa deixava cerca de onze pontos de barra vazia em cada ponta e mal um acima e abaixo, por isso aparecia na horizontal e não na vertical.",
    ["The options page is cut by question instead of by mechanism. Sixteen sections had settings that belong together lying far apart, with the bar texture under one heading and the cast bar's texture under another; eight settings were reachable from two sections at once."] = "A página de opções está cortada por perguntas em vez de por mecânica. Dezesseis seções tinham ajustes que andam juntos espalhados longe uns dos outros, com a textura da barra sob um título e a da barra de conjuração sob outro; oito ajustes eram alcançáveis a partir de duas seções ao mesmo tempo.",
    ["Every text on the plate sits in a slot now, the way the aura rows already did: top, left, right or centred, filled with the unit name or the health text. Four on/off switches became position pickers, each starting on the place its text already had."] = "Cada texto da placa ocupa agora uma posição, do jeito que as linhas de auras já faziam: em cima, à esquerda, à direita ou centralizado, preenchido com o nome da unidade ou o texto de vida. Quatro interruptores viraram seletores de posição, cada um começando no lugar que seu texto já tinha.",
    ["The stacking dropdown had no readable value at all. It was reading a setting this client does not have; the one it does have is now read and written, measured in the running game."] = "O menu suspenso de empilhamento não mostrava valor legível nenhum. Ele lia um ajuste que este cliente não tem; o que ele tem passou a ser lido e escrito, medido no jogo em execução.",
    ["A gear icon on a half-width row opens a small floating window instead of unfolding inside the cell. Half a cell has no room for a slider, and six of them had been squeezed into stubs."] = "Uma engrenagem numa linha de meia largura abre uma janelinha flutuante em vez de se desdobrar dentro da célula. Meia célula não tem espaço para um controle deslizante, e seis deles tinham sido espremidos em tocos.",
    ["Colour swatches, eyes, gears and arrows sit directly beside the control they belong to rather than in the icon strip on the right, which stays reserved for the gear and the info dot."] = "Amostras de cor, olhos, engrenagens e setas ficam logo ao lado do controle a que pertencem, em vez de na tira de ícones à direita, que segue reservada para a engrenagem e o ponto de informação.",
    ["On the Wrath client the module stands down completely and the client keeps its own window. Our restyle addresses Blizzard's widgets by name and by region number, and behind those names that client has a different anatomy: black holes where the hidden regions used to be, a stretched title bar, dropdowns over the recipe list — and no error, because nothing throws, it simply lands on the wrong widgets."] = "No cliente Wrath o módulo recua por completo e o cliente mantém a própria janela. Nosso reestilo endereça os elementos da Blizzard por nome e por número de região, e por trás desses nomes aquele cliente tem outra anatomia: buracos pretos onde ficavam as regiões ocultas, uma barra de título esticada, menus suspensos sobre a lista de receitas — e nenhum erro, porque nada estoura, apenas aterrissa nos elementos errados.",
    ["Talent group buttons run down the right edge, one for each group you have bought. Left-click shows a group, right-click activates it, the same split Blizzard's own window uses. Talents can only be learned in the active group, so a click in the preview does nothing and the tooltip says so beforehand."] = "Pela borda direita correm botões de grupos de talentos, um para cada grupo que você comprou. Clique esquerdo mostra um grupo, clique direito o ativa, a mesma divisão que a própria janela da Blizzard usa. Talentos só podem ser aprendidos no grupo ativo, então um clique na prévia não faz nada e a dica avisa antes.",
    ["The tab carries a book instead of a question mark. That mark is Blizzard's placeholder for a missing icon and read like a defect."] = "A aba leva um livro em vez de um ponto de interrogação. Essa marca é o espaço reservado da Blizzard para um ícone ausente e parecia um defeito.",
    ["Glyphs"] = "Glifos",
    ["CHARACTER"] = "Personagem",
    ["Packs the selected bar setup into a string you can pass on. Slots, macros and key bindings travel with it."] = "Empacota a configuração de barras selecionada em um texto que você pode repassar. Slots, macros e atalhos vão junto.",
    ["Reads a bar setup string into your library. Putting it onto your bars stays a separate step."] = "Lê um texto de configuração de barras para a sua biblioteca. Aplicá-lo às barras continua sendo um passo separado.",
    ["The bar setup string is damaged."] = "O texto da configuração de barras está danificado.",
    ["This is not a bar setup string."] = "Isto não é um texto de configuração de barras.",
    ["Bar setup '%s' imported."] = "Configuração de barras '%s' importada.",
    ["Macros left alone: the switch above is off."] = "Macros intocadas: o interruptor acima está desligado.",
    ["Macros: %d restored, |cffff8800%d failed|r -- the macro list may be full."] = "Macros: %d restauradas, |cffff8800%d falharam|r -- a lista de macros pode estar cheia.",
    ["Macros: %d restored."] = "Macros: %d restauradas.",
    ["Key bindings left alone: the switch above is off."] = "Atalhos intocados: o interruptor acima está desligado.",
    ["Key bindings: %d applied."] = "Atalhos de teclado: %d aplicados.",
    ["Bar setup '%s' saved: %d slots, %d macros, %d key bindings."] = "Configuração de barras '%s' salva: %d espaços, %d macros, %d atalhos de teclado.",
    ["|cffff8800No key bindings were captured.|r This client may not report them."] = "|cffff8800Nenhum atalho de teclado foi capturado.|r Este cliente pode não informá-los.",
    -- Patch notes 1.50.0
    ["Export as string – Packs the selected setup into a string you can pass on, with its slots, macros and key bindings"] = "Exportar como texto – Empacota a configuração selecionada num texto que você pode repassar, com seus espaços, macros e atalhos",
    ["Import from string – Reads someone else's setup into your library; a name you already use gets a number rather than being overwritten"] = "Importar de texto – Lê a configuração de outra pessoa para a sua biblioteca; um nome que você já usa ganha um número em vez de ser sobrescrito",
    ["An imported setup is rebuilt entry by entry before it is stored. The restore walks every entry, so a malformed one would have thrown in the middle of a run with part of your bars already changed. Broken entries are dropped, the rest still arrives."] = "Uma configuração importada é reconstruída entrada por entrada antes de ser guardada. A restauração percorre cada entrada, então uma malformada teria estourado no meio do processo com parte das suas barras já alterada. Entradas quebradas são descartadas e o resto chega assim mesmo.",
    ["Saving and loading say what they did. Both had been counting their work all along and throwing the numbers away, so a setup whose macros all failed looked exactly like one that had none, and a save that captured no key bindings said nothing at all."] = "Salvar e carregar dizem o que fizeram. Os dois vinham contando o próprio trabalho o tempo todo e jogando os números fora: uma configuração cujas macros falhavam todas parecia igual a uma sem macros, e um salvamento que não capturou nenhum atalho não dizia nada.",
    ["The character window can be placed by hand on the Wrath client. Blizzard's editor does not own that window, so it takes the same direct route the loot window already uses; one box moves the character, reputation and skills tabs together, and the stats panel and set list travel with it."] = "A janela de personagem pode ser posicionada à mão no cliente Wrath. O editor da Blizzard não é dono dessa janela, então ela segue a mesma rota direta que a janela de saque já usa; uma caixa move as abas de personagem, reputação e perícias juntas, e o painel de atributos e a lista de conjuntos vão junto.",
    ["The window starts wide on the Wrath client. The slider has always gone to 400 — it simply started at nothing, so the extra room only ever reached whoever went looking for it."] = "A janela começa larga no cliente Wrath. O controle sempre foi até 400 — ele apenas começava do nada, então o espaço extra só chegava a quem foi procurá-lo.",
    ["The glyph page opens from a button under the talent group buttons, and it is dark now. The rune circle is dimmed rather than removed, because it is what makes that page recognisable; the sockets take the accent colour, and the glyph artwork and the pickup highlight stay as they are."] = "A página de glifos abre por um botão abaixo dos botões de grupo de talentos, e agora é escura. O círculo rúnico é escurecido em vez de removido, porque é o que torna aquela página reconhecível; os encaixes assumem a cor de destaque, e a arte do glifo e o realce ao pegá-lo ficam como estão.",
    ["The talent group button shows its tree's icon instead of a question mark. It asked for that icon through an interface that does not answer on every client, and fell back to the placeholder; the answer is now worked out from the ranks themselves, which cannot be misread."] = "O botão de grupo de talentos mostra o ícone da sua árvore em vez de um ponto de interrogação. Ele pedia esse ícone por uma interface que não responde em todo cliente e recorria ao espaço reservado; agora a resposta é deduzida dos próprios níveis de talento, que não podem ser lidos errado.",
    ["The level number on the player frame sits where the client puts it on the Wrath client. Our two anchors are measured against one frame sheet, and where a different one ships, the number landed beside the portrait — the client keeps that anchor itself there anyway, moving it as the rest and PvP icons come and go."] = "O número de nível no quadro do jogador fica onde o cliente o coloca, no cliente Wrath. Nossas duas âncoras são medidas contra uma folha de moldura, e onde outra é distribuída o número acabava ao lado do retrato — ali o cliente mantém essa âncora sozinho e a move conforme os ícones de descanso e JxJ aparecem e somem.",

    -- Character Panel: socket strip
    ["Socket strip under the window"] = "Barra de encaixes abaixo da janela",
    ["Puts a strip with every socket of your equipped gear under the character window. Click a socket to put a gem from your bags into it. Stays empty on clients whose game has no gems."] = "Coloca abaixo da janela do personagem uma barra com todos os encaixes do seu equipamento. Clique em um encaixe para engastar nele uma gema das suas bolsas. Fica vazia em clientes cujo jogo não tem gemas.",
    ["Choose a gem"] = "Escolha uma gema",
    ["No gems in your bags."] = "Nenhuma gema nas suas bolsas.",
    ["Empty socket"] = "Encaixe vazio",
    ["Click to pick a gem from your bags."] = "Clique para escolher uma gema das suas bolsas.",
    ["Cannot socket gems in combat."] = "Não é possível engastar gemas em combate.",
    ["Close the socketing window first."] = "Feche primeiro a janela de engaste.",
    -- Patch notes 1.51.0
    ["Socket strip under the window – A row of every socket on your equipped gear, hung under the character window; click a socket to put a gem from your bags into it"] = "Barra de encaixes abaixo da janela – Uma fileira com todos os encaixes do seu equipamento, abaixo da janela do personagem; clique em um encaixe para engastar nele uma gema das suas bolsas",
    ["The enchant text on armour slots reads the enchant again instead of the item's difficulty tag. The filter took the first green line of the tooltip, and where an item carries a tag that tag stands above the enchant — so every such slot showed the tag, while a weapon two rows down showed its enchant correctly because nothing stood in front of it. The tag and the client's bracketed hints are both recognised now, in every language rather than only in English and German."] = "O texto de encantamento nos espaços de armadura mostra novamente o encantamento em vez da marca de dificuldade do item. O filtro pegava a primeira linha verde da dica, e onde um item carrega essa marca ela fica acima do encantamento — então cada espaço mostrava a marca, enquanto uma arma duas linhas abaixo mostrava o seu corretamente porque nada estava na frente. A marca e os avisos entre colchetes angulares do cliente são reconhecidos agora, e em todos os idiomas em vez de apenas em inglês e alemão.",
    ["The set list no longer casts a shadow past its own frame. What looked like the background standing out over the border was a drop shadow: not an outline but four filled rectangles reaching up to seven pixels beyond the frame on every side, and behind Blizzard's dialog frame there was nothing for it to fall on. It is gone in both looks."] = "A lista de conjuntos não projeta mais sombra além da própria moldura. O que parecia um fundo saindo pela borda era uma sombra: não um contorno, mas quatro retângulos preenchidos que chegavam a sete pixels além da moldura de cada lado, e atrás da moldura de diálogo da Blizzard não havia nada para ela cair. Sumiu nos dois estilos.",
    ["In the Classic+ look the dark ground stopped short of the ornate line instead of ending on it, and so showed past the frame on every side."] = "No estilo Classic+ o fundo escuro terminava antes da linha ornamentada em vez de sobre ela e, por isso, aparecia para fora da moldura em todos os lados.",

    -- Nameplates: layout preset + health text content
    ["Apply this arrangement"] = "Aplicar esta disposição",
    ["Puts the unit name and the health value inside the bar, crowd control left of it, incoming debuffs above that and buffs to its right, and gives the cast bar its icon, its remaining time and its target. Your current arrangement is saved first and the button beside this one brings it back."] = "Coloca o nome da unidade e o valor de vida dentro da barra, o controle de grupo à esquerda dela, as penalidades recebidas acima disso e os bônus à direita, e dá à barra de conjuração seu ícone, seu tempo restante e seu alvo. Sua disposição atual é salva antes e o botão ao lado a traz de volta.",
    ["Restore my arrangement"] = "Restaurar minha disposição",
    ["Puts every text and aura position back to what it was before the arrangement was applied, and removes the saved copy. Anything you moved by hand since then goes back as well."] = "Devolve cada posição de texto e de aura ao que era antes de a disposição ser aplicada e remove a cópia salva. Tudo o que você moveu à mão desde então também volta.",
    ["Nameplate layout applied. The button beside it puts your old one back."] = "Disposição das placas de nome aplicada. O botão ao lado traz a anterior de volta.",
    ["Nameplate layout restored."] = "Disposição das placas de nome restaurada.",
    ["Shows"] = "Mostra",
    ["Current health"] = "Vida atual",
    ["Current and maximum"] = "Atual e máxima",
    ["Current and percent"] = "Atual e porcentagem",
    ["Separator"] = "Separador",
    ["What goes between the two numbers, when the row above is set to current and percent."] = "O que fica entre os dois números, quando a linha acima está em atual e porcentagem.",
    ["Brackets"] = "Parênteses",
    ["Vertical bar"] = "Barra vertical",
    ["Dash"] = "Traço",
    ["Space"] = "Espaço",
    -- Patch notes 1.52.0
    ["The own background for the input line is offered on every client. It was limited to one client generation, and the code already said it would work everywhere."] = "O fundo próprio para a linha de entrada é oferecido em todos os clientes. Estava limitado a uma geração de cliente, e o código já dizia que funcionaria em toda parte.",
    ["The icon borders are pixel-exact. The border there is not a texture of its own but the rim of a plate behind the icon, so the two have to sit on the same pixel grid, the thickness has to be counted in pixels rather than frame units, and the icon size and spacing have to begin on whole pixels. None of the three was true, which is why a rim came out two pixels on one edge and none on the opposite."] = "As bordas dos ícones são exatas ao pixel. Ali a borda não é uma textura própria, mas a orla de uma placa atrás do ícone, então as duas precisam ficar na mesma grade de pixels, a espessura precisa ser contada em pixels e não em unidades de moldura, e tamanho e espaçamento precisam começar em pixels inteiros. Nenhuma das três valia, e por isso uma orla saía com dois pixels de um lado e nenhum do oposto.",
    ["Apply this arrangement – Puts the unit name and the health value inside the bar, crowd control left of it, incoming debuffs above that and buffs to its right, with the cast bar carrying its icon, its remaining time and its target"] = "Aplicar esta disposição – Coloca o nome da unidade e o valor de vida dentro da barra, o controle de grupo à esquerda dela, as penalidades recebidas acima e os bônus à direita, com a barra de conjuração levando seu ícone, seu tempo restante e seu alvo",
    ["The unit name was hidden behind the health bar fill as soon as a text slot put it inside the bar. The name and the health value hang from different parents: the value is created on the bar, the name on the plate, and the bar is a child of the plate — so it draws over anything the plate draws. While the name only ever sat above the bar this never showed. It has its own layer now, above the bar but not attached to it, because name-only mode hides that bar and a text parented to a hidden frame would go with it."] = "O nome da unidade ficava escondido atrás do preenchimento da barra de vida assim que um espaço de texto o colocava dentro da barra. O nome e o valor de vida pendem de pais diferentes: o valor é criado na barra, o nome na placa, e a barra é filha da placa — portanto desenha por cima de tudo o que a placa desenha. Enquanto o nome só ficou acima da barra, isso nunca apareceu. Agora ele tem uma camada própria, acima da barra mas sem estar preso a ela, porque o modo somente nome esconde essa barra e um texto preso a um quadro escondido iria junto.",
    ["The health text has its controls back: what it shows, and which mark goes between the two numbers. Both were still being read and had been unreachable since the page was rebuilt."] = "O texto de vida tem seus controles de volta: o que ele mostra e qual sinal fica entre os dois números. Ambos continuavam sendo lidos e estavam inalcançáveis desde que a página foi refeita.",
    ["The active talent group was always reported as the first one on clients that do not carry the newer interface for it. Everything behind that believed group one was running: the header called the group you were standing in not active, the activate button offered to switch to the one already on, and the switch reported success while changing nothing. Five files ask that same question, so profile overrides and bar setups were reading it too."] = "O grupo de talentos ativo era sempre informado como o primeiro em clientes que não trazem a interface mais nova para isso. Tudo o que vem depois acreditava que o grupo um estava em uso: o cabeçalho chamava de não ativo o grupo em que você estava, o botão de ativar oferecia trocar para o que já estava em uso, e a troca informava sucesso sem mudar nada. Cinco arquivos fazem essa mesma pergunta, então substituições de perfil e configurações de barras também liam dali.",
    ["The glyph page stands permanently beside the window. It is lifted out of Blizzard's talent frame, where it lives inside the scroll area of the very window we replace, and handed back when ours closes."] = "A página de glifos fica permanentemente ao lado da janela. Ela é retirada do quadro de talentos da Blizzard, onde vive dentro da área de rolagem da mesma janela que substituímos, e devolvida quando a nossa fecha.",
    ["The separate glyph button is gone with it. Its only job was to send you to the page that now stands in front of you."] = "O botão de glifos separado some junto. Sua única tarefa era mandar você para a página que agora está à sua frente.",
    ["A band under the header carries the activate button and the name of the talent group on screen. Until now switching existed only as a right-click on the small side icons, and nothing announced it."] = "Uma faixa abaixo do cabeçalho leva o botão de ativar e o nome do grupo de talentos em tela. Até agora a troca existia apenas como clique direito nos pequenos ícones laterais, e nada a anunciava.",
    ["Form paging"] = "Paginação por forma",
    ["Keep the main bar on its page in every form"] = "Manter a barra principal na sua página em todas as formas",
    ["|cffaaaaaaCat, bear, stealth, stances and Shadowform normally swap the main bar to their own page. Switch this off to keep the bar you built through every form.|r"] = "|cffaaaaaaFelino, urso, furtividade, posturas e Forma das Sombras normalmente trocam a barra principal para a página delas. Desative isto para manter em todas as formas a barra que você montou.|r",
    -- Patch notes 1.52.1
    ["Keep the main bar on its page in every form – Cat, bear, stealth, stances and Shadowform stop swapping action bar 1 to a page of their own"] = "Manter a barra principal na sua página em todas as formas – Felino, urso, furtividade, posturas e Forma das Sombras param de trocar a barra de ação 1 para uma página própria",
    ["The ticker that paints cooldown dimming and range colouring no longer walks switched-off bars. It read and repainted every action bar five times a second, including the ones whose buttons nobody can see, so running two bars cost as much as running all of them."] = "O ticker que desenha o escurecimento por recarga e a coloração por alcance não percorre mais as barras desligadas. Ele lia e repintava cada barra de ação cinco vezes por segundo, inclusive aquelas cujos botões ninguém consegue ver, então usar duas barras custava o mesmo que usar todas.",
    ["Leaving a button no longer builds a fresh check each time. The check only ever reads the bar, not the button, so it is built once per bar and shared by all of its buttons."] = "Sair de um botão não constrói mais uma verificação nova a cada vez. A verificação só lê a barra, não o botão, então é construída uma vez por barra e compartilhada por todos os seus botões.",
    ["The opponent frames are left alone unless you actually asked for a different arrangement. They are protected frames: anchoring one from our side is allowed outside a fight, but it marks the frame for the rest of the session, and the next time the default interface repositions it during a round its own call is refused and the block is reported against us. There is no way to anchor a protected frame without leaving that mark, so an untouched setup now keeps the default stacking. Order, spacing, grow direction and slot offsets all still work — the message becomes the price of a feature you asked for rather than something every arena hands out for free."] = "Os quadros dos oponentes ficam intocados, a menos que você tenha realmente pedido outra disposição. São quadros protegidos: ancorar um deles do nosso lado é permitido fora de combate, mas marca o quadro pelo resto da sessão, e na próxima vez que a interface padrão o reposicionar no meio de uma rodada, a chamada dela é recusada e o bloqueio é atribuído a nós. Não há como ancorar um quadro protegido sem deixar essa marca, então uma configuração intocada mantém agora o empilhamento padrão. Ordem, espaçamento, direção de crescimento e deslocamentos de espaço continuam funcionando: a mensagem passa a ser o preço de um recurso que você pediu, em vez de algo que toda arena distribui de graça.",
    ["Move up and move down work again on a category you switched off and back on. The order list was filled once, while it was still empty, so anything that did not exist at that moment never got an entry, and its arrows then did nothing at all for the rest of the session without saying so."] = "Mover para cima e mover para baixo voltam a funcionar em uma categoria que você desligou e ligou de novo. A lista de ordem era preenchida uma única vez, enquanto ainda estava vazia, então o que não existia naquele momento nunca ganhava uma entrada, e suas setas não faziam mais nada pelo resto da sessão, sem avisar.",
    ["Switching a module off releases its event handlers again. The note recording which module owns a handler stayed behind when the handler was unregistered, and that note kept a hard reference to every handler the module had ever registered."] = "Desligar um módulo libera novamente seus manipuladores de eventos. A nota que registra a qual módulo pertence um manipulador permanecia quando ele era removido, e essa nota mantinha uma referência forte a cada manipulador que o módulo já tivesse registrado.",
    -- Patch notes 1.52.2
    ["Casting out of the spell book keeps working after the book was opened from the micro menu. Our micro buttons are stand-ins that hand the click on to the default button behind them, which runs everything that follows inside our own call — and for the spell book that ends in the book writing down which half of itself it is showing. That note then counted as ours, the book reads it on every click on a spell, and so every cast from the book was refused as coming from an addon. Out of combat as well, for the rest of the session, until the interface was reloaded. Opening the book by its key was never affected. The micro menu now carries the default button itself, wearing our icon, so nothing is handed through us any more."] = "Conjurar a partir do livro de magias continua funcionando depois de abri-lo pelo micromenu. Nossos botões do micromenu são dublês que repassam o clique ao botão original atrás deles, de modo que tudo o que vem depois roda dentro da nossa própria chamada — e no livro de magias isso termina com o livro anotando qual metade de si mesmo está mostrando. Essa anotação passava a contar como nossa, o livro a lê a cada clique numa magia, e assim toda conjuração a partir do livro era recusada como vinda de um addon. Fora de combate também, pelo resto da sessão, até recarregar a interface. Abrir o livro pela tecla nunca foi afetado. O micromenu agora carrega o próprio botão original, com o nosso ícone, de modo que nada mais passa por nós.",
    ["Pointing at a bag slot shows the tooltip of the bag itself — quality colour, how much it holds, everything the item carries — with the click hints under it, instead of the bare name. In the inventory window as well as at the bank, which had drifted apart although the two bars are the same thing."] = "Apontar para um espaço de bolsa mostra a dica da própria bolsa — cor de qualidade, quanto ela guarda, tudo o que o item traz — com as indicações de clique embaixo, em vez do nome puro. Na janela de inventário e também no banco, que haviam se separado embora as duas barras sejam a mesma coisa.",
    ["The bar in the inventory window takes bags now, the way the one at the bank already did: drag a bag onto a slot to put it there, or left-click a slot with a bag on the cursor. Right-click with an empty hand takes the bag off again, and left-click with an empty hand still shows and hides it. The backpack and the keyring are not slotted bags, so they accept nothing and are not offered the right-click line in the first place."] = "A barra da janela de inventário aceita bolsas, como a do banco já fazia: arraste uma bolsa até um espaço para colocá-la ali, ou clique com o botão esquerdo num espaço com uma bolsa no cursor. O clique direito de mão vazia tira a bolsa de novo, e o clique esquerdo de mão vazia continua mostrando e escondendo. A mochila e o chaveiro não são bolsas equipadas, portanto não aceitam nada e nem recebem a linha do clique direito.",
    ["The enchant on the wrist slot sits closer to the rows around it, and the enchant on the weapon sits six pixels lower."] = "O encantamento do espaço dos pulsos fica mais perto das linhas ao redor, e o da arma seis pixels mais abaixo.",
    ["The trainer tab is a button of its own now. It used to be a spare tab of the spell book that we wrote on with every update, and the book reads those tabs back in the middle of its own pass. It also goes away with the pet book, where it used to stay behind."] = "A aba do treinador agora é um botão próprio. Antes era uma aba livre do livro de magias, que escrevíamos a cada atualização, e o livro relê essas abas no meio da própria passagem. Ela também desaparece junto com o livro do lacaio, onde antes ficava para trás.",
    -- Nameplates: aura border + CC size
    ["Match the health bar height"] = "Ajustar à altura da barra de vida",
    ["The icon becomes a square exactly as tall as the health bar. The three size sliders below step aside while this is on."] = "O ícone fica quadrado e exatamente da mesma altura que a barra de vida. Os três controles de tamanho abaixo ficam de lado enquanto isto estiver ligado.",
    ["Border around aura icons"] = "Borda ao redor dos ícones de auras",
    ["The thin rim around debuff, damage-over-time, buff and crowd-control icons. Its thickness follows the border size of the plate."] = "A borda fina ao redor dos ícones de penalidades, dano ao longo do tempo, benefícios e controle de grupo. A espessura acompanha a espessura da borda da placa.",
    ["Aura border colour"] = "Cor da borda das auras",
    ["Border in the aura's own school colour"] = "Borda na cor de escola da aura",
    ["Magic blue, curse purple, disease orange, poison green — instead of the one colour beside it."] = "Magia azul, maldição roxo, doença laranja, veneno verde — em vez da cor única ao lado.",
    -- Global settings: settings window scale
    ["Settings Window Scale"] = "Tamanho da janela de configurações",
    ["Scales this settings window on its own. The game's interface keeps the size it has."] = "Redimensiona apenas esta janela de configurações. A interface do jogo mantém o tamanho que tem.",
    -- Patch notes 1.52.3
    ["Match the health bar height – Makes the crowd-control icon a square exactly as tall as the health bar, in place of its own size sliders"] = "Ajustar à altura da barra de vida – Torna o ícone de controle de grupo um quadrado exatamente da altura da barra de vida, no lugar dos seus próprios controles de tamanho",
    ["Border around aura icons – Switches the rim around debuff, damage-over-time, buff and crowd-control icons on or off, with its colour beside it"] = "Borda ao redor dos ícones de auras – Liga ou desliga a borda dos ícones de penalidades, dano ao longo do tempo, benefícios e controle de grupo, com a cor ao lado",
    ["Text size – Sets how large the unit name and the health value are drawn, in the panel behind each of those two rows"] = "Tamanho do texto – Define o tamanho com que o nome da unidade e o valor de vida são desenhados, no painel atrás de cada uma dessas duas linhas",
    ["A long unit name is trimmed with three dots instead of running through the health value. The two share the bar as soon as both sit inside it, so the name now gets the width that is actually free — and only a health value at the other end takes room away, because sharing one slot is something you did on purpose. Only a name that would overflow is capped at all, which is what keeps the level number glued to the name instead of hanging off an oversized box."] = "Um nome de unidade comprido é cortado com três pontos em vez de atravessar o valor de vida. Os dois dividem a barra assim que ambos ficam dentro dela, então o nome recebe agora a largura que está de fato livre — e só um valor de vida na outra ponta tira espaço dele, porque dividir a mesma posição foi escolha sua. Só é limitado um nome que transbordaria, e é isso que mantém o número de nível colado ao nome em vez de pendurado na borda de uma caixa larga demais.",
    ["The aura border can also take the colour of the aura's own school. That switch was read from the start and had no control anywhere."] = "A borda das auras também pode assumir a cor de escola da aura. Esse interruptor era lido desde o começo e não tinha controle em lugar nenhum.",
    ["Settings Window Scale – Scales this settings window on its own, from 70 to 130 per cent, while the game's interface keeps the size it has"] = "Tamanho da janela de configurações – Redimensiona apenas esta janela de configurações, de 70 a 130 por cento, enquanto a interface do jogo mantém o seu tamanho",
    ["Making the window smaller now gives it back its full size on a screen that was cutting it off. The fitting measured the room in the game's units and the window in its own, so scaling it down changed nothing about what it was allowed to be."] = "Diminuir a janela devolve agora o tamanho completo dela em uma tela que antes a cortava. O ajuste media o espaço nas unidades do jogo e a janela nas dela, de modo que diminuí-la não mudava nada do que ela podia ocupar.",
    -- Nameplates: reverse aura swipe
    ["Reverse the swipe"] = "Inverter a varredura",
    ["The shade grows back as the aura runs out, so a nearly clear icon means it is nearly gone."] = "A sombra volta a crescer enquanto a aura se esgota, então um ícone quase limpo significa que está quase no fim.",
    -- Character panel: socket overwrite confirmation
    ["Replace %s with %s? The gem that comes out is destroyed."] = "Substituir %s por %s? A gema que sai é destruída.",
    ["That socket has changed — nothing was socketed."] = "Esse engaste mudou — nada foi engastado.",
    ["Click to replace the gem — the old one is destroyed."] = "Clique para substituir a gema — a antiga é destruída.",
    ["Ask before overwriting a gem"] = "Perguntar antes de sobrescrever uma gema",
    ["A click on a socket that already holds a gem asks first — putting a gem in destroys the one that comes out."] = "Um clique em um engaste que já tem uma gema pergunta primeiro — colocar uma gema destrói a que sai.",
    -- Loadouts: equipping straight out of the bank
    ["%d of them came out of the bank."] = "%d deles saíram do banco.",
    ["in the bank — open the bank window to equip it"] = "no banco — abra a janela do banco para equipá-lo",
    -- Patch notes 1.52.4
    ["Ask before overwriting a gem – A click on a socket that already holds a gem asks first, because putting a gem in destroys the one that comes out"] = "Perguntar antes de sobrescrever uma gema – Um clique em um engaste que já tem uma gema pergunta primeiro, porque colocar uma gema destrói a que sai",
    ["Pointing at an occupied socket says what a click on it costs. Clicking one was always allowed, nothing ever said so, and the gem that comes out is destroyed. The question names both gems in their quality colours, and it drops the action when the gear moved while it was standing — otherwise a swap under the open dialog would answer for a socket you never looked at."] = "Apontar para um engaste ocupado diz o que custa clicar nele. Clicar sempre foi possível, ninguém nunca disse, e a gema que sai é destruída. A pergunta nomeia as duas gemas nas suas cores de qualidade e descarta a ação se o equipamento mudou enquanto ela estava aberta — caso contrário, uma troca sob a janela aberta responderia por um engaste que você nunca olhou.",
    ["Equipping a set at the bank takes the pieces that are lying in the bank, as long as the bank window is open. Until now they counted as missing, so you could stand at the bank and be told the set was not equippable. The message says how many of them came out of the bank, and the piece that comes off goes into the bank slot the new one came from. With the bank closed, a missing piece in there no longer only names its place, it says to open the bank window."] = "Equipar um conjunto no banco pega as peças que estão no banco, enquanto a janela do banco estiver aberta. Até agora elas contavam como ausentes, então você podia estar no banco e ouvir que o conjunto não podia ser equipado. A mensagem diz quantas delas saíram do banco, e a peça que sai vai para o espaço do banco de onde veio a nova. Com o banco fechado, uma peça ausente que esteja lá não nomeia mais apenas o lugar, ela diz para abrir a janela do banco.",
    ["The line that tells you which sets an item belongs to appears in item tooltips. It was built and hooked up from the start, but it went in through the one tooltip mechanism this client offers and never uses, so no line was ever drawn and nothing complained."] = "A linha que diz a quais conjuntos um item pertence aparece nas dicas de item. Ela estava construída e ligada desde o começo, mas passava pelo único mecanismo de dica que este cliente oferece e nunca usa, então nenhuma linha foi desenhada e nada reclamou.",
    ["Reverse the swipe – The shade grows back as the aura runs out, so a nearly clear icon means it is nearly gone"] = "Inverter a varredura – A sombra volta a crescer enquanto a aura se esgota, então um ícone quase limpo significa que está quase no fim",
    ["The cooldown swipe on the aura icons has a control of its own. It was read from the start and could not be changed anywhere."] = "A varredura de recarga nos ícones de aura tem um controle próprio. Ela era lida desde o começo e não podia ser mudada em lugar algum.",
    ["The raid target marker is visible at all. The eight marks live on one sheet, and the call that picks a tile out of it was working on a frame that never got the sheet — a cut-out of nothing, on every plate and in the preview, since the module was built."] = "O marcador de raide aparece. Os oito símbolos ficam em uma única folha, e a chamada que escolhe um quadro dela trabalhava sobre uma superfície que nunca recebeu a folha — um recorte de nada, em cada placa e na pré-visualização, desde que o módulo foi construído.",
    ["The raid target marker takes one of the six named slots, like the four aura rows. It had three positions of its own and could land on top of a row, which is the very collision the slots exist for. The old choice moves into the matching slot once and then goes, so there is no second control for the same question. Its room is reserved as soon as it is switched on, not only once a unit really carries a mark, so the rows do not jump every time somebody sets a skull."] = "O marcador de raide ocupa uma das seis posições nomeadas, como as quatro fileiras de auras. Ele tinha três posições próprias e podia cair sobre uma fileira, exatamente a colisão para a qual essas posições existem. A escolha antiga passa uma vez para a posição correspondente e depois desaparece, para não haver dois controles para a mesma pergunta. O lugar dele é reservado assim que é ligado, não só quando uma unidade realmente carrega um símbolo, para que as fileiras não pulem cada vez que alguém marca uma caveira.",
    ["The marker's own offset and spacing sliders take effect again. They were writing two fields of their own while the plate read the slot, so the visible control was the one without an effect. The old values move across once."] = "Os controles de deslocamento e espaçamento próprios do marcador voltam a ter efeito. Eles escreviam em dois campos próprios enquanto a placa lia a posição, então o controle visível era o sem efeito. Os valores antigos são levados uma vez.",
    ["A mark set between two aura passes lands where it belongs. Where the marker goes is worked out in the aura pass, because only that knows how far the rows on its side reach, and the plate now remembers that point for the event that shows the marker on its own."] = "Um símbolo marcado entre duas passagens de auras aparece onde deve. Onde o marcador vai é calculado na passagem de auras, porque só ela sabe até onde chegam as fileiras do seu lado, e a placa agora guarda esse ponto para o evento que mostra o marcador sozinho.",
    ["The cast time and the cast target show something in the preview. Both only exist for a cast that is really running on a real unit, so both stayed empty while their switches, colours and side settings stood next to them with nothing to show."] = "O tempo de conjuração e o alvo da conjuração mostram algo na pré-visualização. Os dois só existem para uma conjuração realmente em andamento sobre uma unidade real, então ambos ficavam vazios enquanto seus interruptores, cores e ajustes de lado estavam ao lado sem nada a mostrar.",
    -- Slot picker: the bags moved under an open picker
    ["Your bags moved — pick the item again."] = "Suas bolsas mudaram — escolha o item de novo.",
    -- Bar setups: load confirmation, imported macros left alone
    ["Load '%s'? Every button on your bars is overwritten or cleared."] = "Carregar '%s'? Cada botão das suas barras é sobrescrito ou esvaziado.",
    ["Macros: %d restored, %d of your own kept (an import does not rewrite them)."] = "Macros: %d restauradas, %d suas mantidas (uma importação não as reescreve).",
    -- Patch notes 1.52.5
    ["The enchant text of the wrist slot sits under its slot instead of beside it. The wrist is the last slot of the left column, and to the right of it lies the weapon row, which is where the line was writing."] = "O texto de encantamento das braçadeiras fica abaixo do espaço em vez de ao lado. As braçadeiras são o último espaço da coluna da esquerda, e à direita delas está a fileira de armas, exatamente onde a linha estava sendo escrita.",
    ["Search field in the enchanting window – Leaves only the recipes whose name or reagents match what you type"] = "Campo de busca na janela de encantamento – Deixa apenas as receitas cujo nome ou reagentes correspondam ao que você digita",
    ["The enchanting window is the one profession window that never had a search box. The field sits between the title and the slot dropdown: type into it and only the recipes whose name or one of their reagents matches stay, with the scroll bar shortening along with the list instead of leaving empty rows under the last hit. Recipes you starred still float to the top of what is left, and closing the window clears the text — otherwise the next visit would open on a list with most of the recipes missing and nothing on screen to explain it."] = "A janela de encantamento é a única janela de profissão que nunca teve um campo de busca. Ele fica entre o título e o menu de espaços: digite nele e ficam apenas as receitas cujo nome ou um dos reagentes corresponde, com a barra de rolagem encurtando junto com a lista em vez de deixar linhas vazias abaixo do último resultado. Receitas marcadas com estrela continuam subindo para o topo do que sobrou, e fechar a janela limpa o texto; caso contrário, a próxima visita começaria com uma lista sem a maioria das receitas e nada na tela para explicar isso.",
    -- Patch notes 1.52.5
    ["Diminishing returns and interrupts recognise every rank of a spell. Both lists carried one identifier per spell, usually the one for rank one, so what is really cast at level seventy fell through: no icon for the polymorph, no bar for the kick. All ranks share their name, and the client knows the name behind every identifier already in the list, so one pass builds a name index that covers every rank at once, in the client's own language, which is the one the combat log speaks."] = "As reduções decrescentes e as interrupções reconhecem todos os postos de uma magia. As duas listas carregavam um único identificador por magia, quase sempre o do posto um, então escapava o que de fato é conjurado no nível setenta: sem ícone para a transformação, sem barra para o chute. Todos os postos compartilham o nome, e o cliente conhece o nome de cada identificador já presente na lista, então uma passagem monta com eles um índice de nomes que cobre todos os postos de uma vez, no idioma do próprio cliente, o mesmo que o registro de combate fala.",
    ["Loading a setup asks first. It sets a hundred and twenty slots and empties the ones the setup has nothing for, and a single click in the dropdown was enough. The only warning, for a setup belonging to another class, was a chat line that arrived after the damage was done."] = "Carregar uma configuração pergunta antes. Ela ocupa cento e vinte espaços e esvazia aqueles para os quais não tem nada, e bastava um clique no menu suspenso. O único aviso, para uma configuração de outra classe, era uma linha de bate-papo que chegava depois do estrago.",
    ["Importing a setup leaves your own macros and keybindings alone. Macros are matched by name, and a name like Pull belongs to everyone, so a foreign setup replaced the contents of your own macro of that name with the switch on by default and without a word about it. Imported setups are marked as foreign now and keep what is already there, and the message says how many were kept. A backup entry carrying no keys at all no longer gets restored either, which used to clear the keys of that command and save the result."] = "Importar uma configuração deixa suas próprias macros e teclas de atalho em paz. Macros são associadas pelo nome, e um nome como Pull pertence a todo mundo, então uma configuração alheia substituía o conteúdo da sua macro de mesmo nome, com a chave ligada por padrão e sem dizer nada. Configurações importadas agora são marcadas como alheias e mantêm o que já existe, e a mensagem diz quantas foram preservadas. Uma entrada de backup sem tecla alguma também não é mais restaurada, o que até agora apagava as teclas daquele comando e salvava o resultado.",
    ["The enchant text of a weapon sits above its slot. Beside a weapon there is the next weapon, and to the left the whole text column, so the line had nowhere to go; above the weapon row the paper doll is empty. It is centred over its own slot and wraps upward, so two enchanted weapons no longer write across each other."] = "O texto de encantamento de uma arma fica acima do seu espaço. Ao lado de uma arma está a arma seguinte, e à esquerda toda a coluna de texto, de modo que a linha não tinha para onde ir; acima da fileira de armas o boneco está vazio. Ela fica centralizada sobre o próprio espaço e quebra para cima, então duas armas encantadas não escrevem mais uma por cima da outra.",
    ["The question before overwriting a gem is only armed once the dialog is really standing. If one was already open the client reuses it, and rebuilding it cleared the note that had just been made, so the second question answered nothing at all and said nothing about it. The recheck now compares the item as well, and an open window on its own no longer counts as proof that it is the right one."] = "A pergunta antes de sobrescrever uma gema só é armada quando a caixa de diálogo está realmente em pé. Se já havia uma aberta o cliente a reaproveita, e reconstruí-la apagava a anotação recém-feita, então a segunda pergunta não respondia a nada e não avisava disso. A reconferência agora compara também o item, e uma janela aberta por si só não vale mais como prova de que é a certa.",
    ["The item level of a piece the client has not cached yet appears once it arrives. The retry ran into the very gate that had excluded it and drew nothing, ever. It is capped at twenty attempts per item so it cannot turn into a loop that runs every tenth of a second."] = "O nível de item de uma peça que o cliente ainda não guardou aparece assim que chega. A nova tentativa caía exatamente no portão que a havia excluído e nunca desenhava nada. Agora ela é limitada a vinte tentativas por item, para não virar um laço a cada décimo de segundo.",
    ["Deleting an entry removes the one you clicked. It went by the position the row was built with, and the list is rewritten behind the open page whenever the trinket matching adds or removes entries after an equipment change, so the neighbour disappeared instead."] = "Excluir uma entrada remove aquela em que você clicou. Ia pela posição com que a linha foi construída, e a lista é reescrita atrás da página aberta assim que o pareamento de berloques insere ou remove entradas depois de uma troca de equipamento, de modo que sumia a vizinha.",
    ["Logging in no longer opens the edit mode behind your back. Restoring frame positions used to apply the layout by showing the client's own edit mode manager, and that rebuilds every system the editor owns out of our call stack, which hands them to the addon for the rest of the session. Measured in game: one such call three seconds after login, and twenty seconds later 1593 refused actions in combat, party and raid frames among them. The layout is still written, and the client applies it the next time it does so itself. A frame you drag by hand still settles immediately."] = "Entrar no jogo não abre mais o modo de edição pelas suas costas. Restaurar as posições dos quadros aplicava o layout mostrando o gerenciador de modo de edição do próprio cliente, e ele reconstrói cada sistema do editor a partir da nossa pilha de chamadas, o que os entrega ao addon pelo resto da sessão. Medido no jogo: uma chamada dessas três segundos após entrar e, vinte segundos depois, 1593 ações recusadas em combate, quadros de grupo e de raide incluídos. O layout continua sendo salvo, e o cliente o aplica na próxima vez que o aplica por conta própria. Um quadro que você arrasta na mão continua se assentando na hora.",
    ["A frame dropped after a fight has started keeps the spot you dropped it at. A drag can only begin out of combat but it can end in one, and letting go wrote the anchor onto a protected frame without asking. The position was already saved by then, so the saved value and the frame on screen would have disagreed for the rest of the session. The write now waits for the fight to end and is made good afterwards."] = "Um quadro solto depois que um combate começou fica onde você o soltou. Um arrasto só pode começar fora de combate, mas pode terminar dentro dele, e soltar escrevia a âncora em um quadro protegido sem perguntar. A posição já estava salva a essa altura, então o valor salvo e o quadro na tela teriam se contradito pelo resto da sessão. A escrita agora espera o fim do combate e é feita depois.",
    ["The client settings the fishing mode borrows survive a crash. The backup of your own values lived in memory only, so a reload, a disconnect or a crash while fishing mode was running took it along, and music, ambience, auto loot and soft targeting stayed on the fishing values for good with nothing left anywhere to say what they had been."] = "As configurações do cliente que o modo de pesca toma emprestadas sobrevivem a uma queda. A cópia dos seus próprios valores vivia só na memória, então uma recarga, uma desconexão ou uma queda com o modo de pesca ligado a levava junto, e música, ambiente, coleta automática e alvo suave ficavam para sempre nos valores de pesca, sem sobrar em lugar nenhum o que havia antes.",
    ["Switching the camera zoom option off returns the zoom to the client's default. The comment promised as much and the code did nothing of the sort, so with the option already on from an earlier session there was no value of ours to fall back to and the maximum stayed for every session after. It is only reset while the value still is our maximum, so anything you have set yourself since then stays."] = "Desligar a opção de zoom da câmera devolve o zoom ao padrão do cliente. O comentário prometia isso e o código não fazia nada do tipo, e se a opção já viesse ligada de uma sessão anterior não havia valor nosso para o qual voltar, então o máximo ficava também em todas as sessões seguintes. A restauração só acontece enquanto o valor ainda for o nosso máximo, então tudo o que você ajustou desde então permanece.",
    ["Unit tooltips no longer throw a Lua error on a unit without an identifier. The fallback one line above did the arithmetic on the missing identifier itself and handed the result to the very call that cannot take it."] = "As dicas de unidade não lançam mais erro de Lua em uma unidade sem identificador. O recurso alternativo da linha acima fazia ele mesmo a conta com o identificador ausente e passava o resultado justamente para a chamada que não pode aceitá-lo.",
    ["A set finds its own piece when two items share an identifier, the way the owl's ring and the bear's ring do. Sets store the full reference but searched by the bare identifier; the search goes by identifier and suffix now, while enchants and gems stay out of it because those change during an item's life and would make a set report its own piece as missing."] = "Um conjunto acha a própria peça quando dois itens dividem um identificador, como o anel da coruja e o do urso. Conjuntos guardam a referência completa mas procuravam pelo identificador puro; agora a busca vai por identificador e sufixo, enquanto encantamentos e gemas ficam de fora de propósito, porque mudam ao longo da vida de um item e fariam um conjunto declarar a própria peça como faltante.",
    ["The name comes back after a cast the same way the interrupt flash already decides it. A retired field was still being asked, although the options page says it is read nowhere any more."] = "O nome volta depois de uma conjuração do mesmo jeito que o clarão de interrupção já decide. Um campo aposentado continuava sendo consultado, embora a página de opções diga que ele não é mais lido em lugar nenhum.",
    ["The click area of a plate returns to its measured size. The value that means the client's own size was only right as long as the setter had never run, so afterwards the old area stood until a reload and the sliders went up without ever coming back."] = "A área de clique de uma placa volta ao seu tamanho medido. O valor que significa o tamanho do próprio cliente só estava certo enquanto o ajustador nunca tivesse rodado; depois disso a área antiga ficava até uma recarga, e os controles subiam sem nunca voltar.",
    ["An installation from before the schema stamp runs its migrations instead of skipping them. No stamp meant two opposite things, a fresh installation with nothing to migrate or one older than the stamp with everything still pending, and both were stamped current and skipped, so the older one silently lost every migration, its bar setups in their old storage place among them. The two are told apart now by whether there is any module data at all."] = "Uma instalação anterior ao carimbo de esquema roda suas migrações em vez de pulá-las. A ausência de carimbo significava duas coisas opostas, uma instalação nova sem nada a migrar ou uma mais antiga que o carimbo com tudo pendente, e as duas eram carimbadas como atuais e puladas, de modo que a mais antiga perdia em silêncio todas as migrações, inclusive suas configurações de barras no antigo lugar de armazenamento. Agora as duas são distinguidas por haver ou não algum dado de módulo.",
    ["The strip for the weapon slots opens downward instead of sideways. The three weapons are the only slots standing in a row rather than a column, at the bottom of the paper doll, where sideways always runs into their own neighbour. It grows away from the middle of the screen so it cannot pass the near edge, and it tips upward when the window sits at the bottom of the screen."] = "A tira dos espaços de arma se abre para baixo em vez de para o lado. As três armas são os únicos espaços dispostos em fileira e não em coluna, na parte de baixo do boneco, onde para o lado sempre se esbarra na própria vizinha. Ela cresce se afastando do centro da tela para não passar da borda próxima, e tomba para cima quando a janela está na borda inferior.",
    ["A click in the picker can no longer hit whatever has moved into that bag slot in the meantime. It remembered bag and slot from the moment it was filled and listened to no bag event, so after a sort run a click hit what was lying there by then, which with a merchant window open would have been a sale. It follows bag changes now, and every click checks the item in place against the one the button was built for."] = "Um clique no seletor não pode mais acertar o que escorregou para aquele espaço da bolsa nesse meio-tempo. Ele guardava bolsa e espaço do momento em que foi preenchido e não ouvia nenhum evento de bolsa, então depois de uma organização o clique acertava o que estivesse ali naquele momento, e com uma janela de vendedor aberta isso teria sido uma venda. Agora ele acompanha as mudanças nas bolsas, e cada clique confere o item no lugar contra aquele para o qual o botão foi construído.",
    ["The merchant lock covers both trinket slots. A mixed-up condition left it applying to the lower one only."] = "A trava do vendedor vale para os dois espaços de berloque. Uma condição trocada a deixava valer só para o de baixo.",
    ["The addon no longer stamps the client's own health text and target classification with its taint. Both called the client's updaters from our call stack, the very thing the same file forbids two hundred lines further down in writing and with a reason, which makes the client's next pass over those frames unsafe. Both write what they need themselves now. The standard border returns the moment the client next classifies your target."] = "O addon não carimba mais o texto de vida nem a classificação de alvo do cliente com a sua contaminação. Os dois chamavam os atualizadores do cliente a partir da nossa pilha de chamadas, exatamente o que o mesmo arquivo proíbe duzentas linhas abaixo, por escrito e com motivo, e o que torna insegura a próxima passagem do cliente por esses quadros. Agora cada um escreve por conta própria o que precisa. A borda padrão volta assim que o cliente classificar seu alvo da próxima vez.",
    ["|cffff7777What it costs, and why this is off unless you switch it on: the answer has to sit on a name the client's own protected code reads, which hands the party and raid frames to this addon for the rest of the session. In combat they then refuse to resize and name this addon while doing it. Switching it back off stops it happening again but does not undo the session it already happened in - that takes a reload.|r"] = "|cffff7777O que isso custa, e por que fica desligado até você ligar: a resposta precisa ficar em um nome que o próprio código protegido do cliente lê, e isso entrega os quadros de grupo e de raide a este addon pelo resto da sessão. Em combate eles passam a recusar o redimensionamento, citando este addon. Desligar de novo só evita que aconteça outra vez, não desfaz a sessão em que já aconteceu: para isso é preciso recarregar.|r",
    ["not applied - this client does reject the call, so the error is firing"] = "não aplicado: este cliente realmente recusa a chamada, então o erro ocorre",
    -- Patch notes 1.52.6
    ["X Offset / Y Offset – Nudge the stack and reagent numbers away from their chosen corner; both sit behind the gear of the position row"] = "Deslocamento X / Deslocamento Y – Afasta os números de pilha e reagentes do canto escolhido; ambos ficam atrás da engrenagem da linha de posição",
    ["Opening Edit Mode no longer hands the party and raid frames to the addon for the rest of the session. Merely opening it drove the client's frame editor through the addon, and in combat the client then refused to update those frames, naming the addon in the message. Only really moving one of Blizzard's frames still writes to the editor, and a frame that is hidden, like the focus frame while nothing is focused, never does."] = "Abrir o modo de edição não entrega mais os quadros de grupo e raide ao addon pelo resto da sessão. Só de abri-lo, o editor de quadros do cliente passava pelo addon, e em combate o cliente depois se recusava a atualizar esses quadros, nomeando o addon na mensagem. Apenas mover de verdade um quadro da Blizzard ainda escreve no editor, e um quadro oculto, como o de foco sem foco algum, nunca escreve.",
    ["Opening Edit Mode closes the options window. It sat exactly on top of the boxes it had just unlocked."] = "Abrir o modo de edição fecha a janela de opções. Ela ficava exatamente em cima das caixas que acabava de destravar.",
    ["The equipment list steps aside for the rune engraving panel. That panel opens on the right side of the character sheet, exactly where the list docks, so the two stood on top of each other. The list now follows the panel's edge, and where the screen is too narrow for sheet, panel and list together, it moves to the left side of the sheet."] = "A lista de equipamento sai do caminho do painel de gravação de runas. Esse painel abre à direita da janela do personagem, exatamente onde a lista se encaixa, então as duas ficavam uma sobre a outra. A lista agora acompanha a borda do painel e, onde a tela é estreita demais para janela, painel e lista juntos, passa para o lado esquerdo da janela.",
    ["The role fix ships switched off. What it fixes is a silent error that truncates one update when a nameplate appears; what it costs is that the party and raid frames count as touched by the addon for the whole session and refuse to resize in combat, with the addon named in the message. That price was reaching players who never chose it, so now only whoever switches the fix on pays it."] = "A correção de função vem desligada. O que ela corrige é um erro silencioso que corta uma atualização quando uma placa de nome aparece; o que ela custa é que os quadros de grupo e raide contam como tocados pelo addon pela sessão inteira e se recusam a mudar de tamanho em combate, com o addon nomeado na mensagem. Esse preço vinha sendo pago por quem nunca o escolheu, então agora só paga quem liga a correção.",
    ["The status line of the role fix tells the whole truth. With the fix off it used to claim it was not needed on this client, even for players who do have the error; it now says whether the fix is applied, not needed, or simply not switched on while the error is firing."] = "A linha de estado da correção de função diz toda a verdade. Com a correção desligada, ela afirmava que não era necessária neste cliente, mesmo para jogadores que têm o erro; agora diz se a correção está aplicada, se não é necessária ou se simplesmente não foi ligada enquanto o erro acontece.",
    ["The bar ships switched off. A second resource bar is a strong opinion to hand someone who never asked for one, and the client already draws its own. Installations that already exist keep the bar exactly as it was."] = "A barra vem desligada. Uma segunda barra de recurso é uma opinião forte para impor a quem nunca pediu, e o cliente já desenha a dele. Instalações que já existem mantêm a barra exatamente como estava.",
    ["The dark skin keeps Blizzard's rim off the stance buttons for good. Their updates write the button art back directly, past the hook that guards the action bars, so the rim used to return the first time you switched."] = "O visual escuro mantém a borda da Blizzard longe dos botões de forma, de vez. As atualizações deles reescrevem a arte do botão diretamente, passando ao largo do gancho que protege as barras de ação, então a borda voltava na primeira troca.",
    ["Bonus"] = "Bônus",
    ["Rating"] = "Índice",
    ["Base"] = "Base",
    ["Block value"] = "Valor de bloqueio",
    ["Spell Haste"] = "Aceleração de feitiços",
    ["Increases your melee attack power."] = "Aumenta seu poder de ataque corpo a corpo.",
    ["Increases your armor, critical strike chance, and chance to dodge."] = "Aumenta sua armadura, chance de acerto crítico e chance de esquiva.",
    ["Increases your maximum health."] = "Aumenta sua vida máxima.",
    ["Increases your maximum mana and spell critical strike chance."] = "Aumenta sua mana máxima e a chance de acerto crítico com feitiços.",
    ["Increases your health and mana regeneration."] = "Aumenta sua regeneração de vida e mana.",
    ["Chance for your melee attacks to critically hit."] = "Chance de seus ataques corpo a corpo serem críticos.",
    ["Increases your melee attack speed."] = "Aumenta sua velocidade de ataque corpo a corpo.",
    ["Reduces the chance that your melee attacks miss."] = "Reduz a chance de seus ataques corpo a corpo errarem.",
    ["Increases the damage of your spells."] = "Aumenta o dano dos seus feitiços.",
    ["Increases the healing done by your spells."] = "Aumenta a cura dos seus feitiços.",
    ["Chance for your spells to critically hit."] = "Chance de seus feitiços serem críticos.",
    ["Reduces the cast time of your spells."] = "Reduz o tempo de lançamento dos seus feitiços.",
    ["Reduces the chance that your spells miss."] = "Reduz a chance de seus feitiços errarem.",
    ["Increases your damage with melee weapons by %.1f damage per second."] = "Aumenta seu dano com armas corpo a corpo em %.1f de dano por segundo.",
    ["Reduces physical damage taken by %.2f%% against enemies of your level."] = "Reduz o dano físico recebido em %.2f%% contra inimigos do seu nível.",
    ["Reduces your chance to be hit and to be critically hit."] = "Reduz sua chance de ser atingido e de sofrer acertos críticos.",
    ["Chance to dodge enemy melee attacks."] = "Chance de esquivar de ataques corpo a corpo inimigos.",
    ["Chance to parry enemy melee attacks."] = "Chance de aparar ataques corpo a corpo inimigos.",
    ["Chance to block enemy melee attacks with your shield."] = "Chance de bloquear ataques corpo a corpo inimigos com seu escudo.",
    ["Shadow (darkened Blizzard border)"] = "Sombra (borda da Blizzard escurecida)",
    ["Standard (Blizzard's own look)"] = "Padrão (visual original da Blizzard)",
    ["Pick how the action buttons look: Blizzard's own untouched button, the dark Shadow skin, or a masked shape (circle, square, hexagon)."] = "Escolha o visual dos botões de ação: o botão original da Blizzard, o estilo escuro Sombra ou uma forma mascarada (círculo, quadrado, hexágono).",
    ["|cff9b6cffButton border / icon style lives in the Dark Skin module (Action Bars > Bar style): Blizzard's own look, the dark Shadow skin, or masked shapes.|r"] = "|cff9b6cffO estilo de borda e ícone dos botões fica no módulo Dark Skin (Barras de ação > Estilo da barra): o visual original da Blizzard, o estilo escuro Sombra ou formas mascaradas.|r",
    ["Circle (masked shape)"] = "Círculo (forma mascarada)",
    ["Square (masked shape)"] = "Quadrado (forma mascarada)",
    ["Hexagon (masked shape)"] = "Hexágono (forma mascarada)",
    ["WeakAuras style"] = "Estilo do WeakAuras",
    ["Style for WeakAuras icons, independent of the action bars."] = "Estilo dos ícones do WeakAuras, independente das barras de ação.",
    ["Shadow 1"] = "Shadow 1",
    ["Shadow 2"] = "Shadow 2",
    ["Shadow 3"] = "Shadow 3",
    ["Shadow 4"] = "Shadow 4",
    ["Shadow 5"] = "Shadow 5",
    ["Border color"] = "Cor da borda",
    ["Tints the frame of the Shadow and shape styles. Reset it to get each style's built-in coloring back."] = "Tinge a moldura dos estilos Sombra e de formas. Redefina para recuperar a cor integrada de cada estilo.",
    ["Tints the border layer of the aura sets. Reset it to get each set's built-in coloring back."] = "Tinge a camada de borda dos conjuntos de auras. Redefina para recuperar a cor integrada de cada conjunto.",
    ["Spell lists"] = "Listas de feitiços",
    ["Edit spell lists"] = "Editar listas de feitiços",
    ["Always-show and never-show spell IDs for this row."] = "IDs de feitiço para sempre mostrar ou nunca mostrar nesta fileira.",
    ["Always show"] = "Sempre mostrar",
    ["Never show"] = "Nunca mostrar",
    ["Auras on this list always appear in this row, even when its own rules would hide them."] = "Auras desta lista sempre aparecem nesta fileira, mesmo quando as regras dela as esconderiam.",
    ["Auras on this list never appear in this row."] = "Auras desta lista nunca aparecem nesta fileira.",
    ["No entries yet."] = "Ainda não há entradas.",
    ["Unknown spell"] = "Feitiço desconhecido",
    ["Click to switch this entry on or off without deleting it."] = "Clique para ativar ou desativar esta entrada sem excluí-la.",
    ["Mine"] = "Meus",
    ["Any"] = "Todos",
    ["Counts only your own casts - click to count any caster."] = "Só os seus lançamentos contam - clique para contar qualquer lançador.",
    ["Counts any caster - click to count only your own casts."] = "Qualquer lançador conta - clique para contar só os seus lançamentos.",
    ["Low-health glow"] = "Brilho com vida baixa",
    ["Lights the plate up once the unit drops below the chosen health percentage."] = "Ilumina a placa quando a unidade cai abaixo da porcentagem de vida escolhida.",
    ["Thin ring"] = "Anel fino",
    ["Pulsing glow"] = "Brilho pulsante",
    ["Low-health percent"] = "Porcentagem de vida baixa",
    -- Patch notes 1.53.0
    ["Every row of the stats sheet now explains itself when you point at it, and spell haste has joined the sheet."] = "Cada linha da folha de atributos agora se explica quando você aponta para ela, e a aceleração de feitiços entrou para a folha.",
    ["Custom class colours moved into the addon's own colour book. Writing them into the client's shared tables marked the party and raid frames as touched by the addon at every login, and the client then refused to resize them in combat. The clean-up has a price: the client's own windows and other addons show the standard class colours again, while the custom ones colour everything this addon draws."] = "As cores de classe personalizadas se mudaram para o livro de cores do próprio addon. Escrevê-las nas tabelas compartilhadas do cliente marcava as molduras de grupo e de raide como tocadas pelo addon a cada login, e o cliente então se recusava a ajustá-las em combate. A limpeza tem um preço: as janelas do próprio cliente e outros addons voltam a mostrar as cores de classe padrão, enquanto as personalizadas colorem tudo o que este addon desenha.",
    ["Edit spell lists – Every aura row carries an always-show and a never-show spell ID list, kept in its own editing window behind the slot's fine tuning"] = "Editar listas de feitiços – Cada fileira de auras carrega uma lista de sempre mostrar e uma de nunca mostrar por ID de feitiço, mantidas em sua própria janela de edição atrás do ajuste fino da posição",
    ["Low-health glow – Marks plates below a chosen health percentage, as a thin ring or a soft pulsing glow, in a colour of your choice"] = "Brilho com vida baixa – Marca as placas abaixo de uma porcentagem de vida escolhida, como anel fino ou como brilho pulsante suave, na cor que você escolher",
    ["The pulsing glow ships as a new texture file, so it takes one full client restart to appear; a reload is not enough."] = "O brilho pulsante chega como um novo arquivo de textura, então é preciso um reinício completo do cliente para ele aparecer; recarregar não basta.",
    ["The seal-twist helper no longer counts a swing ahead on parries or when attacking starts; its window used to point at a swing that never came."] = "O ajudante de troca de selos não conta mais um golpe adiantado em aparos ou no início do ataque; sua janela apontava para um golpe que nunca vinha.",
    ["The import preview no longer sits on top of the paste step of the import dialog."] = "A prévia de importação não fica mais sobre a etapa de colagem do diálogo de importação.",
    ["The clock keeps ticking through abilities that replace the swing, Heroic Strike and Cleave among them: they write their own combat log line instead of a swing line, so the bar used to stand still exactly for the classes that queue such an ability on every swing."] = "O relógio continua correndo com as habilidades que substituem o golpe, Golpe Heroico e Cutilada entre elas: elas escrevem sua própria linha no registro de combate em vez de uma linha de golpe, então a barra ficava parada justamente para as classes que colocam uma dessas habilidades em cada golpe.",
    ["Swing-resetting spells that deal no damage, parried special attacks and extra attacks now reach the clock too."] = "Feitiços que reiniciam o golpe sem causar dano, ataques especiais aparados e ataques extras agora também chegam ao relógio.",
    ["WeakAuras style – A separate icon style for WeakAuras, independent of the action bars, with five Shadow aura sets"] = "Estilo do WeakAuras – Um estilo de ícones à parte para o WeakAuras, independente das barras de ação, com cinco conjuntos de auras Shadow",
    ["Border color – Tints the frame of the Shadow and shape styles; resetting it restores each style's built-in colouring"] = "Cor da borda – Tinge a moldura dos estilos Shadow e de formas; redefini-la devolve a coloração embutida de cada estilo",
    ["The bar style now starts at Blizzard's own untouched look, and the masked shapes circle, square and hexagon bring their own frames."] = "O estilo de barras agora começa no visual intocado da Blizzard, e as formas mascaradas círculo, quadrado e hexágono trazem molduras próprias.",
    -- Action Ring
    ["%d of %d entries"] = "%d de %d entradas",
    ["360 is a full circle; anything less opens a fan of that width."] = "360 é um círculo completo; qualquer valor menor abre um leque com essa largura.",
    ["Action Ring"] = "Anel de ações",
    ["Action Ring %d"] = "Anel de ações %d",
    ["Add an entry that runs a slash command or macro text."] = "Adiciona uma entrada que executa um comando de barra ou texto de macro.",
    ["Add entry"] = "Adicionar entrada",
    ["Add new ring"] = "Adicionar novo anel",
    ["All %d rings are in use."] = "Todos os %d anéis estão em uso.",
    ["An extra key that closes the ring without using anything. ESCAPE always works."] = "Uma tecla extra que fecha o anel sem usar nada. ESCAPE sempre funciona.",
    ["Arc width"] = "Largura do arco",
    ["At the cursor"] = "No cursor",
    ["Bind or change the key that opens this ring."] = "Vincule ou altere a tecla que abre este anel.",
    ["Cancel key: %s"] = "Tecla de cancelamento: %s",
    ["Clear cancel key"] = "Limpar tecla de cancelamento",
    ["Clear select key"] = "Limpar tecla de seleção",
    ["Click an entry to add it to the ring."] = "Clique em uma entrada para adicioná-la ao anel.",
    ["Custom command"] = "Comando personalizado",
    ["Custom command..."] = "Comando personalizado...",
    ["Delete ring"] = "Excluir anel",
    ["Distance from centre"] = "Distância do centro",
    ["Edit ring"] = "Editar anel",
    ["Enable action ring"] = "Ativar anel de ações",
    ["Entries"] = "Entradas",
    ["Fixed screen position"] = "Posição fixa na tela",
    ["Grey out unusable entries"] = "Acinzentar entradas inutilizáveis",
    ["Hold a keybind to open a ring of actions around the cursor; aim at an entry and release to use it."] = "Mantenha um atalho pressionado para abrir um anel de ações ao redor do cursor; mire em uma entrada e solte para usá-la.",
    ["Horizontal offset"] = "Deslocamento horizontal",
    ["Keep the ring open"] = "Manter o anel aberto",
    ["Key %s was bound to '%s' - now opens %s."] = "A tecla %s estava vinculada a '%s' - agora abre %s.",
    ["Keybind: %s"] = "Atalho: %s",
    ["Macros"] = "Macros",
    ["Markers"] = "Marcadores",
    ["Not bound"] = "Não vinculado",
    ["Open position"] = "Posição de abertura",
    ["Opens this ring without a key press. It closes by itself after a while, or press the button again."] = "Abre este anel sem pressionar tecla. Ele se fecha sozinho depois de um tempo, ou pressione o botão novamente.",
    ["Press a key... (ESC to cancel)"] = "Pressione uma tecla... (ESC para cancelar)",
    ["Raid marker"] = "Marcador de raide",
    ["Release to cancel"] = "Solte para cancelar",
    ["Remove marker"] = "Remover marcador",
    ["Ring name"] = "Nome do anel",
    ["Ring setup"] = "Configuração do anel",
    ["Select key: %s"] = "Tecla de seleção: %s",
    ["Show cooldowns"] = "Mostrar tempos de recarga",
    ["Show ring name in the middle"] = "Mostrar o nome do anel no centro",
    ["Shown in the middle of the ring and in the keybinding list."] = "Exibido no centro do anel e na lista de atalhos.",
    ["Spells"] = "Feitiços",
    ["The key that uses the aimed entry while the ring is kept open. Without it the ring falls back to hold-and-release."] = "A tecla que usa a entrada mirada enquanto o anel permanece aberto. Sem ela, o anel volta ao modo de pressionar e soltar.",
    ["The ring grows on its own when entries would overlap; this is the smallest size."] = "O anel cresce sozinho quando as entradas se sobreporiam; este é o tamanho mínimo.",
    ["The ring stays open after the key is released. Aim and press the select key to use an entry; ESCAPE or the ring's key closes it."] = "O anel permanece aberto depois que a tecla é solta. Mire e pressione a tecla de seleção para usar uma entrada; ESCAPE ou a tecla do anel o fecha.",
    ["This ring is empty - add entries below."] = "Este anel está vazio - adicione entradas abaixo.",
    ["This ring is empty - add entries in the options."] = "Este anel está vazio - adicione entradas nas opções.",
    ["This ring is full (%d entries)."] = "Este anel está cheio (%d entradas).",
    ["Unbind"] = "Desvincular",
    ["|cffaaaaaaHold a keybind to open a ring of actions. Aim at an entry and release the key to use it; release over the middle to cancel. Each ring has its own keybind and its own entries.|r"] = "|cffaaaaaaMantenha um atalho pressionado para abrir um anel de ações. Mire em uma entrada e solte a tecla para usá-la; solte sobre o centro para cancelar. Cada anel tem seu próprio atalho e suas próprias entradas.|r",
    -- Action Ring
    ["A dotted line from the centre toward the cursor. Ring layout only."] = "Uma linha pontilhada do centro em direção ao cursor. Apenas no layout de anel.",
    ["A near-square grid keeps the worst pointer travel short."] = "Uma grade quase quadrada mantém curto o pior trajeto do cursor.",
    ["Apply this look to all rings"] = "Aplicar esta aparência a todos os anéis",
    ["Cancel form"] = "Cancelar forma",
    ["Choose columns automatically"] = "Escolher colunas automaticamente",
    ["Clear all markers"] = "Limpar todos os marcadores",
    ["Columns"] = "Colunas",
    ["Custom"] = "Personalizado",
    ["Custom selection colour"] = "Cor de seleção personalizada",
    ["Cycle raid markers"] = "Alternar marcadores de raide",
    ["Empty ring"] = "Anel vazio",
    ["Entries each side"] = "Entradas de cada lado",
    ["Hide entries this character cannot use"] = "Ocultar entradas que este personagem não pode usar",
    ["Invert scroll direction"] = "Inverter direção de rolagem",
    ["New ring - empty or template"] = "Novo anel - vazio ou modelo",
    ["Override the look for this ring"] = "Substituir a aparência deste anel",
    ["Ring"] = "Anel",
    ["Select with the mouse"] = "Selecionar com o mouse",
    ["Selection colour"] = "Cor de seleção",
    ["Show entry names"] = "Mostrar nomes das entradas",
    ["Show pointer needle"] = "Mostrar agulha do ponteiro",
    ["Strip (mouse wheel)"] = "Faixa (roda do mouse)",
    ["Strip direction"] = "Direção da faixa",
    ["Templates are built from what this character has right now."] = "Os modelos são criados a partir do que este personagem tem agora.",
    ["The release fires the entry under the pointer; with this off, the wheel's entry fires."] = "Ao soltar, dispara a entrada sob o ponteiro; com isto desativado, a entrada da roda é disparada.",
    ["The shared settings take this ring's values and every ring's own override is removed."] = "As configurações compartilhadas assumem os valores deste anel e a substituição própria de cada anel é removida.",
    ["Theme colour"] = "Cor do tema",
    ["This ring keeps its own layout and display settings; every other ring follows the shared ones above."] = "Este anel mantém suas próprias configurações de layout e exibição; todos os outros anéis seguem as compartilhadas acima.",
    ["This ring's own look"] = "Aparência própria deste anel",
    ["Unknown spells and missing macros are left out of the ring entirely. The stored entries stay for characters that can use them."] = "Feitiços desconhecidos e macros ausentes ficam totalmente fora do anel. As entradas salvas permanecem para personagens que podem usá-las.",
    ["|cffaaaaaaTurn the override on to give this ring its own settings.|r"] = "|cffaaaaaaAtive a substituição para dar a este anel suas próprias configurações.|r",
    ["Target markers"] = "Marcadores de alvo",
    ["Hearthstone"] = "Pedra de Regresso",
    ["Teleports"] = "Teletransportes",
    ["Potions"] = "Poções",
    ["Druid forms"] = "Formas de druida",
    ["Stances and auras"] = "Posturas e auras",
    ["Quest items"] = "Itens de missão",
    -- Action Ring
    ["Not in combat - keybinds can't be changed while fighting."] = "Não em combate: as teclas não podem ser alteradas durante a luta.",
    -- Action Ring
    ["Colour while a swing attack is queued"] = "Colorir enquanto um golpe está na fila",
    ["While an on-next-swing attack (Heroic Strike, Cleave, Raptor Strike, Maul) is queued, the bar takes this colour - the resource it will eat is already spoken for."] = "Enquanto um ataque no próximo golpe (Golpe Heroico, Cutilada, Golpe do Raptor, Esmagar) está na fila, a barra assume esta cor: o recurso que ele consumirá já está comprometido.",
    ["Queued colour"] = "Cor na fila",
    -- Patch notes 1.54.0
    ["Action Ring – Hold a keybind to open a ring of actions, aim at an entry and release to use it, spells, items and macros alike, in and out of combat"] = "Anel de ações – Segure uma tecla atribuída para abrir um anel de ações; mire em uma entrada e solte para usá-la, feitiços, itens e macros por igual, dentro e fora de combate",
    ["Choose between a ring, a grid and a mouse-wheel strip, run up to 16 rings with their own keys, entries and look, and start from ready-made templates such as raid marks, teleports, potions or shapeshifts."] = "Dá para escolher entre anel, grade e tira de roda do mouse, ter até 16 anéis com teclas, entradas e aparência próprias, e começar por modelos prontos como marcas de raide, teletransportes, poções ou mudanças de forma.",
    ["The options page shows a live preview of the selected ring that redraws while you drag a slider, and a plus button right in the picture adds entries."] = "A página de opções mostra uma prévia ao vivo do anel escolhido que se redesenha enquanto você arrasta um controle, e um botão de mais dentro da imagem adiciona entradas.",
    ["Colour while a swing attack is queued – The resource bar shows a colour of your choice while an on-next-swing attack waits for the hit, so you can see that the resource is already spoken for"] = "Colorir enquanto um golpe está na fila – A barra de recursos mostra uma cor à sua escolha enquanto um ataque no próximo golpe espera a vez, para você ver que aquele recurso já está comprometido",
    ["The low-health glow now reaches further past the plate and rounds its corners more generously; before, it hugged the frame so tightly that it read as a border instead of a glow."] = "O brilho de vida baixa agora avança mais além da placa e arredonda os cantos com mais generosidade; antes ele ficava tão colado ao quadro que parecia uma borda em vez de um brilho.",
    ["The glow texture changed on disk, so it takes one full client restart to show its new shape; a reload is not enough."] = "A textura do brilho mudou no disco, então é preciso reiniciar o cliente por completo para ver a nova forma; recarregar não basta.",
    ["The bar colour opens a full colour picker instead of a short list of presets; existing profiles keep the colour they had."] = "A cor da barra abre um seletor de cores completo no lugar de uma lista curta de opções fixas; os perfis existentes mantêm a cor que tinham.",
} end)
